    { name = "UnitSpeed", value = 0 },
    { name = "UnitBankAngle", value = 0 },
    { name = "UnitHealth", value = 100 },
    { name = "ConstructionSpeed", value = 0 },
    { name = "IsSelected", value = 0 },
}

local function CreateUnitAudioRtpcs()
    local rtpcs = {}
    for _, rtpc in ipairs(UnitAudioRtpcStartValues) do
        local _, rtpcID = Engine.GetAudioRTPCID(rtpc.name)
        table.insert(rtpcs, EngineClasses.AudioRtpcTemplate(rtpcID, rtpc.value))
    end
    return rtpcs
end

