local function SCO_BuildFacingReindex(hierarchyEntities, entityNameToHierarchyIndex)
    for entityName in pairs(entityNameToHierarchyIndex) do
        entityNameToHierarchyIndex[entityName] = nil
    end
    for index, entity in ipairs(hierarchyEntities) do
        if entityNameToHierarchyIndex[entity.entityName] then
            error("SCOM builder facing found duplicate hierarchy entity " .. entity.entityName)
        end
        entityNameToHierarchyIndex[entity.entityName] = index
    end
end

local function SCO_BuildFacingIsDescendant(hierarchyEntities, entityNameToHierarchyIndex, childName, ancestorName)
    local cursor = childName
    local seen = {}
    while cursor do
        if cursor == ancestorName then return true end
        if seen[cursor] then return false end
        seen[cursor] = true
        local index = entityNameToHierarchyIndex[cursor]
        local entity = index and hierarchyEntities[index]
        cursor = entity and entity.parentEntityName or nil
    end
    return false
end

local function SCO_BuildFacingInsertIdentityParent(hierarchyEntities, entityNameToHierarchyIndex, childName, wrapperName, preservePivot)
    local childIndex = entityNameToHierarchyIndex[childName]
    local child = childIndex and hierarchyEntities[childIndex]
    if not child or not child.parentEntityName then
        error("SCOM builder facing could not parent " .. childName)
    end
    if entityNameToHierarchyIndex[wrapperName] then
        error("SCOM builder facing wrapper already exists: " .. wrapperName)
    end
    local position = EngineClasses.float3()
    local offsetName = wrapperName .. "Offset"
    if preservePivot then
        if entityNameToHierarchyIndex[offsetName] or not child.localTranslation then
            error("SCOM builder facing pivot contract drifted: " .. childName)
        end
        local p = child.localTranslation
        position = EngineClasses.float3(p.x, p.y, p.z)
    end
    local wrapper = EngineClasses.EntityTemplate(
        wrapperName, child.parentEntityName, position,
        1, GetIdentityQuaternion(), true)
    child.parentEntityName = preservePivot and offsetName or wrapperName
    table.insert(hierarchyEntities, childIndex, wrapper)
    if preservePivot then
        -- Keep authored bone translations unchanged while rotating at their joint.
        table.insert(hierarchyEntities, childIndex + 1, EngineClasses.EntityTemplate(
            offsetName, wrapperName, EngineClasses.float3(-position.x, -position.y, -position.z),
            1, GetIdentityQuaternion(), true))
    end
    SCO_BuildFacingReindex(hierarchyEntities, entityNameToHierarchyIndex)
end

local function SCO_BuildFacingAimBoneIsUnowned(tp, aimBone)
    for _, weapon in ipairs(tp.weapons or {}) do
        for _, controller in ipairs(weapon.aimControllers or {}) do
            if controller.aimBone == aimBone then return false end
        end
    end
    return true
end

local function SCO_BuildFacingInstallControllers(tp, hierarchyEntities, entityNameToHierarchyIndex, aimControllerTemplates)
    local tpId = tp and tp.general and tp.general.tpId
    local spec = tpId and SCO_BuildFacingSpecs[tpId]
    if not spec then return end
    local preservePivot = tpId == "uel1501" or tpId == "uel2501" or tpId == "uel3501"
    if tp.additions ~= nil and type(tp.additions) ~= "table" then
        error("SCOM builder facing found invalid additions for " .. tpId)
    end
    for _, controller in ipairs(spec.controllers) do
        if not SCO_BuildFacingAimBoneIsUnowned(tp, controller.aimBone)
            or not SCO_BuildFacingIsDescendant(hierarchyEntities, entityNameToHierarchyIndex, controller.aimBone, controller.pitchBone)
            or not SCO_BuildFacingIsDescendant(hierarchyEntities, entityNameToHierarchyIndex, controller.pitchBone, controller.yawBone)
        then
            error("SCOM builder facing rig contract drifted for " .. tpId)
        end
        SCO_BuildFacingInsertIdentityParent(
            hierarchyEntities, entityNameToHierarchyIndex,
            controller.yawBone, controller.yawEntity, preservePivot)
        if not spec.torsoYawOnly then
            SCO_BuildFacingInsertIdentityParent(
                hierarchyEntities, entityNameToHierarchyIndex,
                controller.pitchBone, controller.pitchEntity, preservePivot)
        end
        hierarchyEntities[entityNameToHierarchyIndex[controller.aimBone]].forceSimulated = true
        table.insert(aimControllerTemplates, EngineClasses.AimControllerTemplate(
            controller.aimBone, controller.aimBone,
            controller.yawEntity, not spec.torsoYawOnly and controller.pitchEntity or nil,
            BallisticType.None,
            -180, 180, 360, EngineClasses.float3(0, 1, 0),
            -90, 90, 360, EngineClasses.float3(1, 0, 0),
            0.2, 0, 1000, 1000, _G.defaultGravityAcceleration,
            0, 0, false, false, false))
    end
    if #spec.controllers > 0 then
        if entityNameToHierarchyIndex.SCOConstructionTarget then
            error("SCOM builder facing target marker already exists: " .. tpId)
        end
        table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
            "SCOConstructionTarget", TemplateHeadEntityName, EngineClasses.float3(),
            1, GetIdentityQuaternion(), true))
        SCO_BuildFacingReindex(hierarchyEntities, entityNameToHierarchyIndex)
    end
    if spec.torsoYawOnly then
        -- Unskinned muzzle markers pitch the shot without moving the arm mesh.
        -- Independent weapons retain their own articulation.
        for _, weapon in ipairs(tp.weapons or {}) do
            for _, controller in ipairs(weapon.aimControllers or {}) do
                if controller.yawBone == "Torso" then controller.pitchBone = controller.aimBone end
            end
        end
    end
    tp.additions = tp.additions or {}
    tp.additions.scomBuildFacing = spec
end

local function InsertAudioTemplate(audioTemplates, entityName, audio, categoryKey, rtpcs)
    local AudioCategories = Import("client/audio/audioCategories.lua")

    local startName = audio.name .. "_start"
    AudioCategories.ResolveEventName(startName)

    local recoverEventID = EngineClasses.AudioEventID()
    if audio.looping then
        -- Hack: For now the start event doubles as the recover event
        recoverEventID = AudioCategories.TryResolveEventName(audio.name .. "_recover") or AudioCategories.eventIDs[startName]

        audio.stopEventID = AudioCategories.TryResolveEventName(audio.name .. "_stop")
    end

    local cullEventID = AudioCategories.TryResolveEventName(audio.name .. "_cull") or EngineClasses.AudioEventID()

    table.insert(audioTemplates, EngineClasses.AudioTemplate(entityName,
        AudioCategories.eventIDs[startName],
        recoverEventID,
        cullEventID,
        audio.basePriority or -1,
        AudioCategories.categoryNameToID[categoryKey],
        rtpcs,
        nil,
        false,
        false
    ))
end

local function CreateColliderEntity(entityColliderName, entityColliderParent, volumeColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)

    table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
        entityColliderName,
        entityColliderParent,
        EngineClasses.float3(0, 0, 0),
        1.0,
        GetIdentityQuaternion(),
        true
    ))

    table.insert(globalVolumeColliderTemplates, volumeColliderTemplate)
end

--- Converts loaded unit template to a unit prefab and registers it with the engine.
-- @param the unit template
function CreateUnitPrefab(tp)
    if not SCOM_EditableUnits.IsEditable(tp) then
        SCO_SourceFinalizeTemplate(tp)
        SCO_ApplyCommanderWeaponBrightness(tp)
    end
    -- Editable Aeon templates use the same shield-colored death presentation.
    SCO_ApplyAeonDeathSmokeVisuals(tp)

    -- Looks like: "Units/tpId/LOD0/tpId"
    local unitPath = "Units/"..tp.general.tpId.."/LOD0/"..tp.general.tpId

    local skeletonPath = unitPath..".sanskeleton"
    local meshPath = unitPath.."_lod0.sanmodel"
    meshPath = SCO_SourceBodyModel(tp, meshPath)
    local materialPath = unitPath.."_lod0.sanmaterial"

    local _, skeletonBones = Engine.GetSkeletonBones(skeletonPath)

    local hierarchyEntities = HierarchyTemplateLoader.GetHierarchyEntities(skeletonBones)

    local entityNameToHierarchyIndex = {}
    for index, template in ipairs(hierarchyEntities) do
        entityNameToHierarchyIndex[template.entityName] = index
    end

    -- SCOM Field Fix: strategic silo simulated muzzle 1.0.0
    SCO_FieldFixStrategicSiloMuzzleHierarchy(
        tp, entityNameToHierarchyIndex, hierarchyEntities)
    SCO_UefGunshipAimHierarchy(tp, entityNameToHierarchyIndex, hierarchyEntities)
    SCO_AhwassaAimHierarchy(tp, entityNameToHierarchyIndex, hierarchyEntities)

    if tp.construction then
        ConstructionSpawnPositionLoader.GetConstructorSpawnBones(tp, skeletonBones)

        if tp.construction.platformBoneName then
            local index = entityNameToHierarchyIndex[tp.construction.platformBoneName]
            if index then
                hierarchyEntities[index].forceSimulated = true
            end
        end
    end

    -- Global Templates Lists
    local healthTemplates = {}
    local globalVolumeColliderTemplates = {}
    local aimControllerTemplates = {}
    SCO_BuildFacingInstallControllers(
        tp, hierarchyEntities, entityNameToHierarchyIndex,
        aimControllerTemplates)
    local navmapModifierTemplates = {}
    if tp.general and tp.general.tpId == "uel0000" then
        local podSpawnBones = {
            { name = "AttachSpecial02", parent = "Left_Arm_B01" },
            { name = "AttachSpecial01", parent = "Right_Arm_B01" },
        }
        for _, specification in ipairs(podSpawnBones) do
            local index = entityNameToHierarchyIndex[specification.name]
            local entity = index and hierarchyEntities[index]
            if entity == nil
                or entity.parentEntityName ~= specification.parent
            then
                error("SCOM UEF commander pod-bone hierarchy drifted: "
                    .. specification.name)
            end
            entity.forceSimulated = true
        end
    end
    if tp.general and tp.general.tpId == "ugl0000" then
        local aliasName = "SCOTorpedoMuzzle"
        local sourceName = "Turret_Muzzle_03"
        local sourceIndex = entityNameToHierarchyIndex[sourceName]
        local sourceEntity = sourceIndex and hierarchyEntities[sourceIndex]
        if sourceEntity == nil
            or sourceEntity.parentEntityName ~= "Center_Turret"
            or entityNameToHierarchyIndex[aliasName] ~= nil
        then
            error("SCOM Cybran torpedo muzzle hierarchy drifted")
        end
        table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
            aliasName, sourceName, EngineClasses.float3(),
            1, GetIdentityQuaternion(), true))
        entityNameToHierarchyIndex[aliasName] = #hierarchyEntities
    end
    local globalGridModifierTemplates = {}
    local movementTemplates = {}
    local animationTemplates = {}
    local rotatorTemplates = {}

    -- Local Templates Lists
    local cullingTemplates = {}
    local meshTemplates = {}
    local lodTemplates = {}
    local skinnedMeshTemplates = {}
    local skinnedMeshBoneTemplates = {}
    local localVolumeColliderTemplates = {}
    local holesTemplates = {}
    local iconsTemplates = {}
    local rangeRingsTemplates = {}
    local progressBarsTemplates = {}
    local localGridModifierTemplates = {}
    local particleTemplates = {}

    --- Loading Global Templates ---

    -- Collider which allows this object to be targeted.
    table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
        "TargetCollider",
        TemplateHeadEntityName,
        tp.collisionInfo.centerOffset,
        1.0,
        GetIdentityQuaternion(),
        true
    ))
    -- Allows the unit to be detected by weapon systems.
    table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(
        "TargetCollider",
        tp.collisionInfo.collisionSize,
        EngineClasses.float3(),
        ColliderType.Box,
        CollisionWorld.Targeting,
        1,
        2,
        ColliderFlags.Disabled + ColliderFlags.EventsDisabled -- Default state is disabled because we are a placement ghost.
    ))

    table.insert(healthTemplates, EngineClasses.HealthTemplate(TemplateHeadEntityName,
        tp.defence.health.value or 0,
        tp.defence.health.max or 0,
        tp.defence.health.regen or 0,
        true
    ))

    local progressBarsList = {}
    local progressBarCurrentOffset = EngineClasses.float2(0, 20)
    local progressBarSize = EngineClasses.float2(math.round(tp.footprint.x * 40), 12)
    local offsetBetweenBars = 10

    -- Health
    table.insert(progressBarsList, EngineClasses.ProgressBarTemplate(
        ProgressBarType.Health,
        EngineClasses.float2(0, progressBarCurrentOffset.y),
        progressBarSize,
        tp.defence.health.value,
        tp.defence.health.max,
        false,
        false
    ))

    progressBarCurrentOffset.y = progressBarCurrentOffset.y + offsetBetweenBars

    -- Construction progress
    table.insert(progressBarsList, EngineClasses.ProgressBarTemplate(
        ProgressBarType.Orange,
        EngineClasses.float2(0, progressBarCurrentOffset.y),
        progressBarSize,
        0,
        1.0,
        true,
        false
    ))

    progressBarCurrentOffset.y = progressBarCurrentOffset.y + offsetBetweenBars

    local audioTemplates = {}

    if tp.defence.shields ~= nil then
        for shieldIndex, shield in ipairs(tp.defence.shields) do

            local shieldEntityName = shield.entityName
                or shield.boneName..'ShieldEntity'

            if shield.audio and shield.audio.onImpact and shield.audio.onImpact.name then
                local audio = shield.audio.onImpact
                audio.prefabID = AudioPrefabLoader.CreateOneShotAudioPrefab(tp.general.tpId .. "_shield" .. shieldIndex .. "_onImpactAudio", audio.name, "impacts", audio.basePriority)
            end

            -- Will create the entities for the shield. Only creates local templates for rendering the shields.
            -- Global templates must be created by the units.
            ShieldTemplateLoader.CreateShieldEntity(tp, shield, shieldEntityName, hierarchyEntities, meshTemplates, cullingTemplates);

            if IsClient and shield.audio and shield.audio.active and shield.audio.active.name then
                InsertAudioTemplate(audioTemplates, shieldEntityName, shield.audio.active, "unitShields")
            end

            table.insert(healthTemplates, EngineClasses.HealthTemplate(shieldEntityName,
                shield.value,
                shield.max,
                shield.regen,
                false
            ))

            table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(shieldEntityName,
                (shield.scoFaTitanPersonalShield == true and not shield.scoFaTitanSphereCollider and shield.collisionSize) or shield.radii,
                (shield.scoFaTitanPersonalShield == true and not shield.scoFaTitanSphereCollider and shield.collisionOffset) or EngineClasses.float3(0, 0, 0),
                (shield.scoFaTitanPersonalShield == true and not shield.scoFaTitanSphereCollider and ColliderType.Box) or ColliderType.Sphere,
                CollisionWorld.Collision,
                (shield.scoPersonalDamageOwner == true and CollisionLayer.None) or CollisionLayer.Shields,
                CollisionLayer.None,
                ColliderFlags.Hollow
            ))

            table.insert(localVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(shieldEntityName,
                (shield.scoFaTitanPersonalShield == true and not shield.scoFaTitanSphereCollider and shield.collisionSize) or shield.radii,
                (shield.scoFaTitanPersonalShield == true and not shield.scoFaTitanSphereCollider and shield.collisionOffset) or EngineClasses.float3(0, 0, 0),
                (shield.scoFaTitanPersonalShield == true and not shield.scoFaTitanSphereCollider and ColliderType.Box) or ColliderType.Sphere,
                CollisionWorld.Collision,
                (shield.scoPersonalDamageOwner == true and CollisionLayer.None) or CollisionLayer.Shields,
                CollisionLayer.None,
                ColliderFlags.Hollow
            ))

            local shieldSignatureColliderName = shieldEntityName.."IntelVisionSignatureCollider"

            CreateColliderEntity(shieldSignatureColliderName, shieldEntityName,
                EngineClasses.VolumeColliderTemplate(shieldSignatureColliderName,
                    shield.radii,
                    EngineClasses.float3(0, 0, 0),
                    ColliderType.Sphere,
                    CollisionWorld.IntelVision,
                    CollisionLayer.None,
                    1,
                    ColliderFlags.None
                ),
                hierarchyEntities,
                globalVolumeColliderTemplates
            )

            table.insert(progressBarsList, EngineClasses.ProgressBarTemplate(
                ProgressBarType.Blue,
                EngineClasses.float2(0, progressBarCurrentOffset.y),
                progressBarSize,
                shield.value,
                shield.max,
                false,
                false
            ))

            progressBarCurrentOffset.y = progressBarCurrentOffset.y + offsetBetweenBars

            -- create entity for vfx
            if shield.effectsPersistent ~= nil then
                local templates = ParticleTemplateLoader.CreateParticleTemplatesUnit("persistentEffectShield", shield.effectsPersistent, hierarchyEntities)
                for _, v in ipairs(templates)  do
                    table.insert(particleTemplates, v)
                end
            end
        end
    end

    if tp.weapons then
        for weaponIndex, weapon in ipairs(tp.weapons) do 
            
            -- TODO: Implement range min.
            if weapon.rangeMax then

                weapon.weaponColliderEntityName = "Weapon"..weaponIndex.."RangeCollider"
                table.insert(hierarchyEntities, EngineClasses.EntityTemplate(weapon.weaponColliderEntityName, TemplateHeadEntityName))
                
                -- Target detection collider for the weapon.
                table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(weapon.weaponColliderEntityName, 
                    EngineClasses.float3(weapon.rangeMax),
                    EngineClasses.float3(),
                    ColliderType.Circle,
                    CollisionWorld.Targeting,
                    2,
                    1,
                    ColliderFlags.Disabled  -- Default state is disabled because we are a placement ghost.
                ))
            end

            if weapon.waterSensor then
                local waterSensor = weapon.waterSensor

                if entityNameToHierarchyIndex[waterSensor.bone] then
                    weapon.waterSensorEntityName = "Weapon"..weaponIndex.."WaterSensor"

                    table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
                        weapon.waterSensorEntityName,
                        waterSensor.bone,
                        EngineClasses.float3(0, 0, 0),
                        1.0,
                        GetIdentityQuaternion(),
                        true
                    ))

                    table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(weapon.waterSensorEntityName,
                        EngineClasses.float3(WaterSensorProbeRadius, 0, 0),
                        waterSensor.offset,
                        ColliderType.Sphere,
                        CollisionWorld.EnvironmentCollision,
                        CollisionLayer.None,
                        CollisionLayer.Water,
                        ColliderFlags.None
                    ))
                else
                    Warn(string.format("unitTemplateLoader: template '%s' weapon %d declares a waterSensor on bone '%s' which is not in the skeleton; ignoring.",
                        tp.general.tpId, weaponIndex, tostring(waterSensor.bone)))
                end
            end

            -- TODO: Some weapons only have like 5 fields and no aim controllers, what's up with that?
            if weapon.aimControllers then
                local weaponAimControllerEntities = { }

                for _, aimController in ipairs(weapon.aimControllers) do
                    local controllerType
                    if aimController.solverType == "NoArc" then
                        controllerType = BallisticType.None
                    elseif aimController.solverType == "LowArc" then
                        controllerType = BallisticType.LowArc
                    elseif aimController.solverType == "HighArc" then
                        controllerType = BallisticType.HighArc
                    else
                        Error("Invalid SolverType: " .. aimController.solverType)
                        controllerType = BallisticType.None
                    end

                    table.insert(aimControllerTemplates, EngineClasses.AimControllerTemplate(aimController.aimBone,
                        aimController.aimBone,
                        aimController.yawBone,
                        aimController.pitchBone,
                        controllerType,
                        aimController.yawMin or 0,
                        aimController.yawMax or 0,
                        aimController.yawSpeed or 0,
                        aimController.yawAxis or EngineClasses.float3(0, 1, 0),
                        aimController.pitchMin or 0,
                        aimController.pitchMax or 0,
                        aimController.pitchSpeed or 0,
                        aimController.pitchAxis or EngineClasses.float3(1, 0, 0),
                        aimController.aimTolerance,
                        weapon.rangeMin,
                        weapon.rangeMax,
                        aimController.projectileSpeed,
                        aimController.aimGravity or _G.defaultGravityAcceleration,
                        aimController.defaultYawAdjustment or 0,
                        aimController.defaultPitchAdjustment or 0,
                        aimController.leadTarget,
                        aimController.reduceMuzzleVelocityToTarget or false,
                        false
                    ))

                    table.insert(weaponAimControllerEntities, aimController.aimBone)
                end

                if weapon.muzzleGroups then
                    for _, muzzleGroup in ipairs(weapon.muzzleGroups) do
                        for _, muzzle in ipairs(muzzleGroup.muzzles) do
                            local hierarchyIndex = entityNameToHierarchyIndex[muzzle]
                            if hierarchyIndex then
                                hierarchyEntities[hierarchyIndex].forceSimulated = true
                            end

                            local isBeamWeapon = IsBeamWeapon(weapon)
                            if isBeamWeapon then
                                if (weapon.beamLifetime or -1) > 0 then
                                    if not weapon.beamPrefabID then
                                        weapon.beamPrefabID = BeamLoader.CreateBeamPrefab(tp.general.tpId .. "_Beam_" .. weaponIndex, weapon.beam)
                                    end
                                else
                                    BeamLoader.CreateBeamMeshes(hierarchyEntities, meshTemplates, muzzle, weapon.beam)
                                end

                                local beamSignatureColliderName = muzzle.."IntelVisionSignatureCollider"

                                CreateColliderEntity(beamSignatureColliderName, muzzle,
                                    EngineClasses.VolumeColliderTemplate(beamSignatureColliderName,
                                        EngineClasses.float3(1, 1, 1),
                                        EngineClasses.float3(0, 0, 0),
                                        ColliderType.Box,
                                        CollisionWorld.IntelVision,
                                        CollisionLayer.None,
                                        1,
                                        ColliderFlags.None
                                    ),
                                    hierarchyEntities,
                                    globalVolumeColliderTemplates
                                )
                            end
                        end
                    end
                end
            end
        end
    end

    -- It can build other units
    if tp.construction and tp.construction.beam then
        -- Entity for the constructon beam
        table.insert(hierarchyEntities, EngineClasses.EntityTemplate("Construction Beam",
            tp.construction.beam.boneName or TemplateHeadEntityName,
            tp.construction.beam.offset,
            1.0,
            GetIdentityQuaternion(),
            false
        ))

        -- Mesh for the construction beam
        local constructionBeamMaterialPath
        -- Supreme Commander Overhaul construction beam faction palette 1.3.3
        local SCO_GameplayBeamFactionCount = 0
        if type(tp.tags) == "table" then
            for _, factionTag in ipairs({ "EDA", "CHOSEN", "GUARD", "PROMETHEAN", "SERAPHIM" }) do
                if table.find(tp.tags, factionTag) then
                    SCO_GameplayBeamFactionCount = SCO_GameplayBeamFactionCount + 1
                end
            end
        end
        if SCO_GameplayBeamFactionCount ~= 1 then
            Engine.Error("UnitTemplate:"..tp.general.tpId.." did not have exactly one faction tag. ConstructionBeam materials will use the default EDA material.")
            constructionBeamMaterialPath = "VFX/SCOM/ConstructionBeams/uef.sanmaterial"
        elseif table.find(tp.tags, "GUARD") or table.find(tp.tags, "PROMETHEAN") then
            if table.find(tp.tags, "PROMETHEAN") then
                constructionBeamMaterialPath = "Prometheans/VFX/Materials/ConstructionBeams/Promethean_ConstructionBeam.sanmaterial"
            else
                constructionBeamMaterialPath = "VFX/SCOM/ConstructionBeams/cybran.sanmaterial"
            end
        elseif table.find(tp.tags, "CHOSEN") then
            constructionBeamMaterialPath = "VFX/SCOM/ConstructionBeams/aeon.sanmaterial"
        elseif table.find(tp.tags, "SERAPHIM") then
            constructionBeamMaterialPath = "VFX/SCOM/ConstructionBeams/seraphim.sanmaterial"
        else
            constructionBeamMaterialPath = "VFX/SCOM/ConstructionBeams/uef.sanmaterial"
        end

        table.insert(meshTemplates, EngineClasses.MeshTemplate("Construction Beam",
            "VFX/Models/Static/ConstructionBeam.sanmodel",
            constructionBeamMaterialPath,
            EngineClasses.float3(tp.construction.beam.shrink, 1, 1),
            ShadowCastingMode.Off,
            EngineClasses.float4(),
            EngineClasses.float4(),
            false
        ))
    end
    
    -- Main Unit Collider
    table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(TemplateHeadEntityName,
        tp.collisionInfo.collisionSize,
        tp.collisionInfo.centerOffset,
        ColliderType.Box,
        CollisionWorld.Collision,
        CollisionLayer.Units,
        CollisionLayer.None,
        ColliderFlags.Disabled -- This starts as disabled because we assume the unit will be a placement ghost by default.
    ))

    -- Collision collider inside the rendering world.
    table.insert(localVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(TemplateHeadEntityName,
        tp.collisionInfo.collisionSize,
        tp.collisionInfo.centerOffset,
        ColliderType.Box,
        CollisionWorld.Collision,
        CollisionLayer.Units,
        CollisionLayer.None,
        ColliderFlags.None
    ))

    table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
        "ConstructionCollider",
        TemplateHeadEntityName,
        EngineClasses.float3(0, 0, 0),
        1.0,
        GetIdentityQuaternion(),
        true
    ))
    
    table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate("ConstructionCollider",
        tp.collisionInfo.collisionSize,
        tp.collisionInfo.centerOffset,
        ColliderType.Box,
        CollisionWorld.Construction,
        CollisionLayer.Units,
        CollisionLayer.None,
        ColliderFlags.None
    ))

    if tp.movement and tp.movement.hullWaterSensor then
        table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
            HullWaterSensorName,
            TemplateHeadEntityName,
            EngineClasses.float3(0, 0, 0),
            1.0,
            GetIdentityQuaternion(),
            true
        ))

        table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate(HullWaterSensorName,
            EngineClasses.float3(WaterSensorProbeRadius, 0, 0),
            tp.movement.hullWaterSensor.offset,
            ColliderType.Sphere,
            CollisionWorld.EnvironmentCollision,
            CollisionLayer.None,
            CollisionLayer.Water,
            ColliderFlags.None
        ))
    end

    -- intel.
    if tp.intel then
        
        local visionSignatureColliderName = "IntelVisionSignatureCollider"
        local radarSignatureColliderName = "IntelRadarSignatureCollider"
        local sonarSignatureColliderName = "IntelSonarSignatureCollider"
        local visionDetectorColliderName = "IntelVisionDetectorCollider"
        local radarDetectorColliderName = "IntelRadarDetectorCollider"
        local sonarDetectorColliderName = "IntelSonarDetectorCollider"

        do  --Vision Signature Collider.
            local signatureColliderTemplate = EngineClasses.VolumeColliderTemplate(
                visionSignatureColliderName,
                tp.collisionInfo.collisionSize,
                tp.collisionInfo.centerOffset,
                ColliderType.Box,
                CollisionWorld.IntelVision,
                CollisionLayer.None,
                1,
                ColliderFlags.Disabled -- Default state is disabled because we are a placement ghost.
            )

            CreateColliderEntity(visionSignatureColliderName, TemplateHeadEntityName, signatureColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)
        end

        do  --Radar Signature Collider.
            local signatureColliderTemplate = EngineClasses.VolumeColliderTemplate(
                radarSignatureColliderName,
                tp.collisionInfo.collisionSize,
                tp.collisionInfo.centerOffset,
                ColliderType.Box,
                CollisionWorld.IntelRadar,
                CollisionLayer.None,
                1,
                ColliderFlags.Disabled -- Default state is disabled because we are a placement ghost.
            )

            CreateColliderEntity(radarSignatureColliderName, TemplateHeadEntityName, signatureColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)
        end

        do  --Sonar Signature Collider.
            local signatureColliderTemplate = EngineClasses.VolumeColliderTemplate(
                sonarSignatureColliderName,
                tp.collisionInfo.collisionSize,
                tp.collisionInfo.centerOffset,
                ColliderType.Box,
                CollisionWorld.IntelSonar,
                CollisionLayer.None,
                1,
                ColliderFlags.Disabled -- Default state is disabled because we are a placement ghost.
            )

            CreateColliderEntity(sonarSignatureColliderName, TemplateHeadEntityName, signatureColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)
        end

        -- Unit is equipped with vision detection.
        if tp.intel.visionRadius then

            local detectorColliderTemplate = EngineClasses.VolumeColliderTemplate(
                visionDetectorColliderName,
                -- NOTE: To make the game a little more playable, we factor in radar into vision because we do not have radar yet.
                EngineClasses.float3(tp.intel.visionRadius, 0, 0),
                EngineClasses.float3(),
                ColliderType.Circle,
                CollisionWorld.IntelVision,
                1,
                CollisionLayer.None,
                ColliderFlags.Disabled
            )

            CreateColliderEntity(visionDetectorColliderName, TemplateHeadEntityName, detectorColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)
        end
        
        -- Unit is equipped with radar detection.
        if tp.intel.radarRadius then

            local detectorColliderTemplate = EngineClasses.VolumeColliderTemplate(
                radarDetectorColliderName,
                EngineClasses.float3(tp.intel.radarRadius, 0, 0),
                EngineClasses.float3(),
                ColliderType.Circle,
                CollisionWorld.IntelRadar,
                1,
                CollisionLayer.None,
                ColliderFlags.Disabled
            )

            CreateColliderEntity(radarDetectorColliderName, TemplateHeadEntityName, detectorColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)
        end

        -- Unit is equipped with sonar detection.
        if tp.intel.sonarRadius then

            local detectorColliderTemplate = EngineClasses.VolumeColliderTemplate(
                sonarDetectorColliderName,
                EngineClasses.float3(tp.intel.sonarRadius, 0, 0),
                EngineClasses.float3(),
                ColliderType.Circle,
                CollisionWorld.IntelSonar,
                1,
                CollisionLayer.None,
                ColliderFlags.Disabled
            )

            CreateColliderEntity(sonarDetectorColliderName, TemplateHeadEntityName, detectorColliderTemplate, hierarchyEntities, globalVolumeColliderTemplates)
        end
    end

    if tp.collisionInfo.targetBones and next(tp.collisionInfo.targetBones) then
        for _, targetBoneName in ipairs(tp.collisionInfo.targetBones) do
            local hierarchyIndex = entityNameToHierarchyIndex[targetBoneName]
            if hierarchyIndex then
                hierarchyEntities[hierarchyIndex].forceSimulated = true
            end
        end
    else
        local simulationBoneName = "VirtualTargetBone"
        local centerOffset = tp.collisionInfo.centerOffset or EngineClasses.float3()
        
        table.insert(hierarchyEntities, EngineClasses.EntityTemplate(simulationBoneName,
            TemplateHeadEntityName,
            centerOffset,
            1.0,
            GetIdentityQuaternion(),
            true
        ))
        tp.collisionInfo.targetBones = { simulationBoneName }
    end

    if tp.skirtSize then
        tp.general.navmapModifierLayers = NavmapModifierLoader.AddNavmapModifierTemplates(
            TemplateHeadEntityName,
            Layers.GetStructureNavigationLayerNames(),
            EngineClasses.float2(tp.skirtSize.x, tp.skirtSize.y),
            true,
            hierarchyEntities,
            navmapModifierTemplates
        )

        if _G.IsClient then
            table.insert(localGridModifierTemplates, EngineClasses.GridModifierTemplate(TemplateHeadEntityName,
                EngineClasses.int2(tp.skirtSize.x, tp.skirtSize.y),
                EngineClasses.int2(0, 0),
                _G.localBuildingPlacementGridID,
                Layers.PlacementLayer.Default,
                Layers.PlacementLayer.None,
                false
            ))
        else
            table.insert(globalGridModifierTemplates, EngineClasses.GridModifierTemplate(TemplateHeadEntityName,
                EngineClasses.int2(tp.skirtSize.x, tp.skirtSize.y),
                EngineClasses.int2(0, 0),
                _G.globalBuildingPlacementGridID,
                Layers.PlacementLayer.Default,
                Layers.PlacementLayer.None,
                false
            ))
        end
    end

    if tp.movement ~= nil then
        -- TODO: Hard force capsule is setup to fit the unit collider but should
        -- ultimately use data from the unit template
        local capsuleInfo = Avoidance.getCapsuleInfo(tp.collisionInfo.collisionSize)

        local movement = tp.movement
        local movementConfigDefaults = {
            collisionMaskSpawn = { "LandSmall" },
            collisionMaskDefault = { "LandSmall" },
            referenceAltitude = "Ground",
            preferredAltitude = 0,
            terrainAlignmentFactor = 0,
            chassisRotationHalfLife = 0,
            maxBankDegrees = 0,
            bankHalfLife = 0.1,
        }
        for field, default in pairs(movementConfigDefaults) do
            if movement[field] == nil then
                movement[field] = default
            end
        end

        if type(movement.collisionMaskSpawn) == "table" then
            movement.collisionMaskSpawn = Layers.MovementCollisionLayerMaskFromList(movement.collisionMaskSpawn)
        end
        if type(movement.collisionMaskDefault) == "table" then
            movement.collisionMaskDefault = Layers.MovementCollisionLayerMaskFromList(movement.collisionMaskDefault)
        end
        if table.find(tp.tags, "AIR") and table.find(tp.tags, "MOBILE") then
            local isLarge = table.find(tp.tags, "TECH4") or table.find(tp.tags, "TECH5")
            local expectedLayer = isLarge and "AirLarge" or "Air"
            local otherLayer = isLarge and "Air" or "AirLarge"
            local hasExpected = bit.band(movement.collisionMaskDefault, Layers.MovementCollisionLayer[expectedLayer]) ~= 0
            local hasOther = bit.band(movement.collisionMaskDefault, Layers.MovementCollisionLayer[otherLayer]) ~= 0

            if hasOther or not hasExpected then
                Warn(string.format("unitTemplateLoader: air template '%s' should use the %s collision layer.", tp.general.tpId, expectedLayer))
            end
        end
        if type(movement.referenceAltitude) == "string" then
            local value = ReferenceAltitude[movement.referenceAltitude]
            if value == nil then
                Warn(string.format("unitTemplateLoader: template '%s' has unknown referenceAltitude '%s'; defaulting to Ground.", tp.general.tpId, tostring(movement.referenceAltitude)))
                value = ReferenceAltitude.Ground
            end
            movement.referenceAltitude = value
        end

        MovementPatterns.CreatePatterns(tp)

        table.insert(movementTemplates, EngineClasses.MovementTemplate(TemplateHeadEntityName,
            false,
            Layers.GetDefaultNavigationLayerFromTemplate(tp),
            movement.speed,
            movement.minSpeed or 0,
            movement.acceleration,
            movement.deceleration or (movement.acceleration * 3),
            movement.rotationSpeed,
            capsuleInfo.capsuleRadius,
            capsuleInfo.capsuleLength,
            capsuleInfo.capsuleMass,
            movement.collisionMaskSpawn,
            movement.referenceAltitude,
            movement.preferredAltitude,
            movement.altitudeChangeRate or math.huge,
            movement.terrainAlignmentFactor,
            movement.chassisRotationHalfLife,
            movement.maxBankDegrees,
            movement.bankHalfLife
        ))
    end

    --- Loading Local Templates ---

    table.insert(cullingTemplates, EngineClasses.CullingTemplate(TemplateHeadEntityName,
        -- TODO: Proper value for this. 
        -- In the engine, we had this calculation for the culling bounds: math.max(math.max(math.cmax(unit.footprint), math.cmax(unit.collisionInfo.collisionSize)) / 1.5f, 1.0f);
        -- cmax returns the maximum component cmax(v) = max(v.x, v.y, v.z, ...), 
        -- max compares two vectors and returns the maximum for each component: max(v1, v2) = floatN(max(v1.x, v2.x), max(v1.y, v2.y), max(v1.zy, v2.z), ..., N)
        10
    ))

    local renderDistance = StructureRenderDistance
    if tp.movement ~= nil then
        renderDistance = UnitRenderDistance
    end

    -- SCO_CzarRenderDistance
    -- Mobile units normally render to UnitRenderDistance (100 in this build).
    -- Give only the imported UAA0310 Czar five times that native cutoff.
    local SCO_CzarRenderSource =
        tp.additions and tp.additions.faSourceContract
    if tp.general.tpId == "uca4011"
        and SCO_CzarRenderSource
        and SCO_CzarRenderSource.targetId == "uca4011"
        and SCO_CzarRenderSource.sourceId == "UAA0310"
    then
        renderDistance = UnitRenderDistance * 5
    end

    -- The Kennel remains visible after the mobile-unit cutoff. Keep its real
    -- XEA3204 pod mesh until the authored terminal LOD cutoff as well.
    local sourcePod = tp.additions and tp.additions.scoSourcePods
    if tp.general.tpId == "uea5011"
        and sourcePod and sourcePod.kind == "pod"
        and sourcePod.sourceId == "XEA3204" and sourcePod.targetId == "uea5011"
    then
        local mesh = tp.visuals and tp.visuals.mesh
        assert(mesh and mesh.lod0distance == 107 and mesh.lod1distance == 279
            and meshPath == "Units/uea5011/LOD0/uea5011_lod0.sanmodel",
            "SCOM Kennel pod render contract changed: uea5011")
        renderDistance = mesh.lod1distance
    end

    -- Setup a single LOD level for this unit which is the same as the default skinned mesh renderer for the unit.
    table.insert(lodTemplates, EngineClasses.LODTemplate(TemplateHeadEntityName,
        {
            EngineClasses.LODLevelTemplate(meshPath,
                materialPath,
                renderDistance,
                ShadowCastingMode.On,
                0,
                0,
                0,
                0,
                0,
                false,
                false
            )
        },
        skeletonPath
    ))
    
    -- Create skinned mesh for the unit.
    local skinnedMeshTemplate = EngineClasses.SkinnedMeshTemplate(TemplateHeadEntityName,
        skeletonPath,
        meshPath,
        materialPath,
        ShadowCastingMode.On,
        EngineClasses.float4(1, 1, 1, 1), -- First instance data is the color of the unit.
        EngineClasses.float4(-1, 0, 0, 0), -- Second instanced data is the wreck data and stuff. Starts as a placementghost.
        true
    )

    -- Create skinned mesh renderer for placement ghost.
    table.insert(skinnedMeshTemplates, skinnedMeshTemplate)

    -- Create skinned mesh bones to tell the skinned mesh renderer which entities in the hierarchy are bones for our skinned mesh
    -- Iterate over the bones of our mesh and add a SkinnedMeshBoneTemplate for each one of them.
    for i, skeletonBone in ipairs(skeletonBones) do
        table.insert(skinnedMeshBoneTemplates, EngineClasses.SkinnedMeshBoneTemplate(skeletonBone.boneName,
            skinnedMeshTemplates[1].entityName,
            i - 1
        ))
    end

    SCO_SourceShellMeshes(tp, hierarchyEntities, skinnedMeshTemplates, skinnedMeshBoneTemplates,
        lodTemplates, cullingTemplates, skeletonBones, renderDistance)

    -- NOTE: As of 9/11/24, the following entity attachments are populated by Lua at runtime when creating a unit.
    -- TODO: This is not ideal as this creates overhead when units are created. Update such that the base values are present in the Loader.

    if tp.visuals.selection ~= nil then

        table.insert(hierarchyEntities, EngineClasses.EntityTemplate("Selection Collider",
            TemplateHeadEntityName,
            EngineClasses.float3(0, 0, 0),
            1.0,
            GetIdentityQuaternion(),
            false
        ))

        -- Supreme Commander Overhaul Structures Cache Patcher 1.6.1
        -- Imported models can opt into an exact click volume instead of the stock 30% padding.
        local selectionHit = tp.additions and tp.additions.selectionHit
        local selectionHitSize = selectionHit and selectionHit.size
        local x = (selectionHitSize and selectionHitSize.x) or math.round(tp.visuals.selection.size.x * 1.3, 3)
        local y = tp.collisionInfo.collisionSize.y
        local z = (selectionHitSize and selectionHitSize.y) or math.round(tp.visuals.selection.size.y * 1.3, 3)
        local selectionOffset = (selectionHit and selectionHit.offset) or tp.visuals.selection.offset or {}

        table.insert(localVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate("Selection Collider",
            EngineClasses.float3(x, y, z),
            EngineClasses.float3(selectionOffset.x or 0, selectionOffset.y or 0, selectionOffset.z or 0),
            ColliderType.Box,
            CollisionWorld.Selection,
            CollisionLayer.Units,
            CollisionLayer.None,
            ColliderFlags.EventsDisabled
        ))
    end

    local selectionSize
    if tp.visuals and tp.visuals.selection then
        selectionSize = tp.visuals.selection.size
    else
        Warn("Missing selection info in template.")
        selectionSize = tp.skirtSize or tp.footprint
    end

    local bracketMeshScale = EngineClasses.float3(selectionSize.x or 0, 1, selectionSize.y or 0)

    table.insert(hierarchyEntities, EngineClasses.EntityTemplate("Selection Bracket",
        TemplateHeadEntityName,
        EngineClasses.float3(0, 0, 0),
        1.0,
        GetIdentityQuaternion(),
        false
    ))

    table.insert(meshTemplates, EngineClasses.MeshTemplate("Selection Bracket",
        "VFX/Models/Static/Quad Up.sanmodel",
        "VFX/Objective Markers/Visual Marker_Unit Default_Flat_Brackets 08.sanmaterial",
        bracketMeshScale,
        ShadowCastingMode.Off,
        EngineClasses.float4(),
        EngineClasses.float4(),
        true -- Selection bracket is disabled by default.
    ))

    table.insert(hierarchyEntities, EngineClasses.EntityTemplate("Construction Bracket",
        TemplateHeadEntityName,
        EngineClasses.float3(0, 0, 0),
        1.0,
        GetIdentityQuaternion(),
        false
    ))

    table.insert(meshTemplates, EngineClasses.MeshTemplate("Construction Bracket",
        "VFX/Models/Static/Quad Up.sanmodel",
        "VFX/Objective Markers/Visual Marker_Building Footprint_01.sanmaterial",
        bracketMeshScale,
        ShadowCastingMode.Off,
        EngineClasses.float4(),
        EngineClasses.float4(),
        true
    ))

    if tp.visuals.holes ~= nil then

        local holeTemplates = {}
        for _, hole in ipairs(tp.visuals.holes) do
            table.insert(holeTemplates, EngineClasses.HoleTemplate(
                hole.holeSize or EngineClasses.float2(0, 0),
                hole.holeOffset or EngineClasses.float2(0, 0),
                0,
                renderDistance,
                true,
                hole.circle or false
            ))
        end
        
        -- NOTE: The difference between "Holes" and "Hole" here. The attachment is the HolesTemplate. 
        -- "Holes" is plural because this attachment contains an array of "HoleTemplate." Each of these "HoleTemplate" is what renders a hole.
        -- This allows us to render many holes per entity, instead of having an entity per hole.
        table.insert(holesTemplates, EngineClasses.HolesTemplate(TemplateHeadEntityName, holeTemplates, 1.0, true))
    end
    
    local runtimeIconInformation = {}
    local iconIndex = 0
    local icons = {}
    local iconTp = tp.general.icon
    tp.general.icon.runtimeInformation = runtimeIconInformation
    
    if iconTp then
        local imageName = string.format("%s_%s_%s_normal", iconTp.shape, iconTp.tech, iconTp.symbol)
        table.insert(icons, EngineClasses.IconTemplate(imageName, nil, nil, nil, 0.25, UnitIconHeightCutoff, IconTypes.Unit, 0, true, nil, 1.0, true))
        runtimeIconInformation["StrategicIcon"] = {
            index = iconIndex,
            name = imageName
        }
        iconIndex = iconIndex + 1

        -- Radar icon: By default disabled.
        imageName = string.format("%s_%s_%s_normal", iconTp.shape, iconTp.tech, "none")
        table.insert(icons, EngineClasses.IconTemplate(imageName, nil, EngineClasses.float4(1.0, 1.0, 1.0, 1.0), nil, 0.25, 0, IconTypes.Unit, 0, false, nil, 1.0, true))
        runtimeIconInformation["RadarIcon"] = {
            index = iconIndex,
            name = imageName
        }
        iconIndex = iconIndex + 1
    end

    if tp.construction then
        -- "strategic_icon_adornment_root" -- seems to be a crown for the king peice?
        local topPosition = EngineClasses.float2(0, 10)
        table.insert(icons, EngineClasses.IconTemplate("strategic_icon_adornment_idle", nil, nil, topPosition, 0.25, UnitIconHeightCutoff, IconTypes.Unit, 1, false))
        runtimeIconInformation["Idle"] = {
            index = iconIndex,
            name = "strategic_icon_adornment_idle"
        }
        iconIndex = iconIndex + 1
        table.insert(icons, EngineClasses.IconTemplate("strategic_icon_adornment_upgrade", nil, nil, topPosition, 0.25, UnitIconHeightCutoff, IconTypes.Unit, 1, false))
        runtimeIconInformation["Upgrade"] = {
            index = iconIndex,
            name = "strategic_icon_adornment_upgrade"
        }
        iconIndex = iconIndex + 1
        local bottomRightPosition = EngineClasses.float2(10, -8)
        table.insert(icons, EngineClasses.IconTemplate("strategic_icon_adornment_pause", nil, nil, bottomRightPosition, 0.25, UnitIconHeightCutoff, IconTypes.Unit, 1, false))
        runtimeIconInformation["Pause"] = {
            index = iconIndex,
            name = "strategic_icon_adornment_pause"
        }
        iconIndex = iconIndex + 1
        
        if tp.construction.range then
            table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
                "ConstructorCollider",
                TemplateHeadEntityName,
                EngineClasses.float3(0, 0, 0),
                1.0,
                GetIdentityQuaternion(),
                true
            ))
            
            table.insert(globalVolumeColliderTemplates, EngineClasses.VolumeColliderTemplate("ConstructorCollider",
                EngineClasses.float3(tp.construction.range, 0, 0),
                nil,
                ColliderType.Circle,
                CollisionWorld.Construction,
                CollisionLayer.None,
                CollisionLayer.Units,
                ColliderFlags.None
            ))
        end
    end
    
    -- TODO: Different starting sorting layers depending on the unit type.
    table.insert(iconsTemplates, EngineClasses.IconsTemplate(TemplateHeadEntityName, icons, 1.0, 0, false))

    local rangeRings = {}
    if tp.ranges then
        for material, ranges in pairs(tp.ranges) do
            table.insert(rangeRings, EngineClasses.RangeRingTemplate(material, ranges.outerRadius, ranges.innerRadius))
            ranges.ringIndex = #rangeRings - 1
        end
    end

    table.insert(rangeRingsTemplates, EngineClasses.RangeRingsTemplate(TemplateHeadEntityName, rangeRings, true))

    -- SCOM commander native progress descriptors 1.0.0
    if tp.general.tpId == "uel0000" or tp.general.tpId == "ucl0000"
        or tp.general.tpId == "ugl0000" or tp.general.tpId == "usl0000"
    then
        tp.scoNativeProgressBars = table.deepCopy(progressBarsList)
    end
    table.insert(progressBarsTemplates, EngineClasses.ProgressBarsTemplate(TemplateHeadEntityName, progressBarsList, 1.0, false))

    if tp.visuals.effectsPersistent ~= nil then
        local templates = ParticleTemplateLoader.CreateParticleTemplatesUnit("persistentEffect", tp.visuals.effectsPersistent, hierarchyEntities)
        for _, v in ipairs(templates) do
            table.insert(particleTemplates, v)
        end
    end

    if tp.visuals.effectsWhenActive ~= nil then
        local templates = ParticleTemplateLoader.CreateParticleTemplatesUnit("persistentEffectWhenActive", tp.visuals.effectsWhenActive, hierarchyEntities)
        for _, v in ipairs(templates) do
            table.insert(particleTemplates, v)
        end
    end

    if tp.visuals.animations then
        local animationClipTemplates = {}
        
        local sortedKeys = {}
        for key in pairs(tp.visuals.animations) do
            table.insert(sortedKeys, key)
        end
        table.sort(sortedKeys)
        
        for _, key in ipairs(sortedKeys) do
            local animationInfo = tp.visuals.animations[key]
            
            table.insert(animationClipTemplates, EngineClasses.AnimationClipTemplate(
                animationInfo.sanAnimationPath, 
                animationInfo.clipName, 
                animationInfo.authoredSpeed, 
                -- SCOM Field Fix: source animation playback mode 1.0.0
                animationInfo.playbackMode or AnimationPlaybackMode.Loop,
                animationInfo.authoredSpeed ~= nil
            ))
            
            animationInfo.id = #animationClipTemplates
        end
        
        -- FA constructs the Megalith in Awake frame zero. Use that pose for
        -- predicted client ghosts too, before the first host animation sample.
        local startingAnimation = tp.visuals.animations.walk
        if tp.general.tpId == "ugl4002" then
            startingAnimation = tp.visuals.animations.awake
            assert(startingAnimation and startingAnimation.clipName == "Awake",
                "Megalith construction pose requires its source Awake clip")
        end
        table.insert(animationTemplates, EngineClasses.AnimationTemplate(TemplateHeadEntityName,
             animationClipTemplates,
             startingAnimation.sanAnimationPath,
             startingAnimation.clipName,
             false
        ))
    end

    if tp.additions and tp.additions.rotators then
        for _, rotator in ipairs(tp.additions.rotators) do
            table.insert(rotatorTemplates, EngineClasses.RotatorTemplate(rotator.boneName, rotator.speed, false, rotator.isVelocityScalingEnabled))
        end
    end

    if IsClient and tp.audio and tp.audio.active and tp.audio.active.name then
        InsertAudioTemplate(audioTemplates, TemplateHeadEntityName, tp.audio.active, "unitActive", CreateUnitAudioRtpcs())
    end

    -- Plain lua array so iteration order is deterministic
    local PersistentAudioEntities = {
        { key = "engine", entityName = "EngineAudioEntity", categoryKey = "unitMotor" },
        { key = "production", entityName = "ProductionAudioEntity", categoryKey = "unitProduction" },
        { key = "gettingConstructed", entityName = "ConstructionProgressAudioEntity", categoryKey = "unitConstruction" },
    }
    for _, persistentAudio in ipairs(PersistentAudioEntities) do
        local audio = tp.audio and tp.audio[persistentAudio.key]
        if audio and audio.name then
            table.insert(hierarchyEntities, EngineClasses.EntityTemplate(
                persistentAudio.entityName,
                TemplateHeadEntityName,
                EngineClasses.float3(0, 0, 0),
                1.0,
                GetIdentityQuaternion(),
                false
            ))

            if IsClient then
                InsertAudioTemplate(audioTemplates, persistentAudio.entityName, audio, persistentAudio.categoryKey, CreateUnitAudioRtpcs())
            end
        end
    end

    if tp.audio and tp.audio.onDestroyed and tp.audio.onDestroyed.name then
        local audio = tp.audio.onDestroyed
        audio.prefabID = AudioPrefabLoader.CreateOneShotAudioPrefab(tp.general.tpId .. "_onDestroyedAudio", audio.name, "unitDestroyed", audio.basePriority)
    end

    if tp.weapons then
        for weaponIndex, weapon in ipairs(tp.weapons) do
            if weapon.audio and weapon.audio.onFire and weapon.audio.onFire.name then
                local audio = weapon.audio.onFire

                local muzzleBoneName = audio.looping and weapon.muzzleGroups and weapon.muzzleGroups[1].muzzles[1]

                if muzzleBoneName then
                    audio.muzzleBoneName = muzzleBoneName

                    if IsClient then
                        InsertAudioTemplate(audioTemplates, muzzleBoneName, audio, "weapons")
                    end
                else
                    audio.prefabID = AudioPrefabLoader.CreateOneShotAudioPrefab(tp.general.tpId .. "_weapon" .. weaponIndex .. "_onFireAudio", audio.name, "weapons", audio.basePriority)
                end
            end
        end
    end

    local prefabTemplate = EngineClasses.PrefabTemplate(tp.general.tpId,
        EngineClasses.HierarchyTemplate(hierarchyEntities),
        EngineClasses.GlobalTemplate(healthTemplates, aimControllerTemplates, nil, globalVolumeColliderTemplates, movementTemplates, nil, navmapModifierTemplates, globalGridModifierTemplates, animationTemplates, rotatorTemplates),
        EngineClasses.LocalTemplate(meshTemplates, skinnedMeshTemplates, skinnedMeshBoneTemplates, nil, lodTemplates, cullingTemplates, holesTemplates, iconsTemplates, rangeRingsTemplates, progressBarsTemplates, particleTemplates, nil, audioTemplates, localGridModifierTemplates, localVolumeColliderTemplates, nil)
    )

    SCO_SourceSecondaryVisuals(tp, prefabTemplate)
    SCO_SourceSniperPrefab(tp, prefabTemplate)
    SCO_SourceDynamicVisuals(tp, prefabTemplate)
    SCO_FactoryClearancePrefab(tp, prefabTemplate)
    SCO_SourcePodAttachments(tp, prefabTemplate)
    return Engine.CreatePrefab(prefabTemplate)
end

