local SCO_IdleResetDelayedDeathClips = {
    ["uel3001"] = { death01 = "AnimDeath01", death02 = "AnimDeath02" },
    ["ugl3001"] = { death01 = "AnimDeath01", death02 = "AnimDeath02", death03 = "AnimDeath03" },
}

local function SCO_IdleResetWarn(tpId, reason)
    if Warn then
        Warn("[SCOM Idle Reset] Skipped " .. tostring(tpId) .. "; " .. reason)
    end
end

local function SCO_IdleResetPrepareTurretRest(tp, tpId)
    local specs = SCO_IdleResetTurretRest[tpId]
    if not specs then return end
    local weapons = tp.weapons
    if type(weapons) ~= "table" then
        SCO_IdleResetWarn(tpId, "missing turret-rest weapon table")
        return
    end
    local additions
    if tpId == "ugl4001" then
        additions = tp.additions
        if additions == nil then
            additions = {}
        elseif type(additions) ~= "table" then
            SCO_IdleResetWarn(tpId, "invalid additions table for combined aim reset")
            return
        elseif additions.scoIdleResetAimPose ~= nil
            and additions.scoIdleResetAimPose ~= true
        then
            SCO_IdleResetWarn(tpId, "conflicting combined aim-reset marker")
            return
        end
    end
    local pending = {}
    local sourceCount = 0
    local restCount = 0
    local monkeylordAlreadyReset = tpId == "ugl4001"
        and additions.scoIdleResetAimPose == true
    local legacyMonkeylordPrimaryRest = false
    for _, spec in ipairs(specs) do
        local weapon = weapons[spec.weaponIndex]
        local controllers = weapon and weapon.aimControllers
        if type(controllers) ~= "table" or #controllers ~= #spec.controllers then
            SCO_IdleResetWarn(tpId, "weapon " .. spec.weaponIndex .. " turret-rest controller roster drifted")
            return
        end
        for controllerIndex, expected in ipairs(spec.controllers) do
            local controller = controllers[controllerIndex]
            if type(controller) ~= "table" or type(expected) ~= "table"
                or type(expected.expected) ~= "number" or type(expected.rest) ~= "number"
            then
                SCO_IdleResetWarn(tpId, "weapon " .. spec.weaponIndex .. " turret-rest manifest drifted")
                return
            end
            if controller.aimBone ~= expected.aimBone
                or controller.yawBone ~= expected.yawBone
                or controller.pitchBone ~= expected.pitchBone
            then
                SCO_IdleResetWarn(tpId, "weapon " .. spec.weaponIndex .. " controller " .. controllerIndex .. " identity drifted")
                return
            end
            local currentDefault = controller.defaultPitchAdjustment
            if currentDefault == expected.expected then
                sourceCount = sourceCount + 1
            elseif currentDefault == expected.rest then
                restCount = restCount + 1
                legacyMonkeylordPrimaryRest = tpId == "ugl4001"
                    and spec.weaponIndex == 1 and controllerIndex == 1
                    and monkeylordAlreadyReset
                    or legacyMonkeylordPrimaryRest
            else
                SCO_IdleResetWarn(tpId, "weapon " .. spec.weaponIndex .. " controller " .. controllerIndex .. " default pitch drifted")
                return
            end
            pending[#pending + 1] = { controller = controller, value = expected.rest }
        end
    end
    local legacyMonkeylordUpgrade = legacyMonkeylordPrimaryRest
        and sourceCount == 2 and restCount == 1
    if tpId == "ugl4001" and monkeylordAlreadyReset
        and sourceCount == #pending
    then
        SCO_IdleResetWarn(tpId, "marked combined aim-reset reverted to source values")
        return
    end
    if tpId == "ugl4001" and not monkeylordAlreadyReset
        and restCount == #pending
    then
        SCO_IdleResetWarn(tpId, "unmarked combined aim-reset already uses rest values")
        return
    end
    if sourceCount > 0 and restCount > 0 and not legacyMonkeylordUpgrade then
        SCO_IdleResetWarn(tpId, "partially applied turret-rest manifest")
        return
    end
    if sourceCount > 0 then
        for _, change in ipairs(pending) do
            change.controller.defaultPitchAdjustment = change.value
        end
    end
    if tpId == "ugl4001" then
        additions.scoIdleResetAimPose = true
        tp.additions = additions
    end
end

local function SCO_IdleResetFinalizeSourceTemplate(tp)
    local general = tp and tp.general
    local tpId = general and general.tpId
    SCO_IdleResetPrepareTurretRest(tp, tpId)
end

local function SCO_IdleResetPrepareDelayedDeathPlayback(tp, tpId)
    local expected = SCO_IdleResetDelayedDeathClips[tpId]
    if not expected then return end
    local animations = tp.visuals and tp.visuals.animations
    local expectedPath = "Units/" .. tpId .. "/LOD0/" .. tpId .. ".sananimation"
    if type(animations) ~= "table" then
        SCO_IdleResetWarn(tpId, "missing delayed-death animation table")
        return
    end
    for key, clipName in pairs(expected) do
        local clip = animations[key]
        if type(clip) ~= "table" or clip.clipName ~= clipName
            or clip.sanAnimationPath ~= expectedPath
            or (clip.playbackMode ~= nil
                and clip.playbackMode ~= AnimationPlaybackMode.Clamp)
        then
            SCO_IdleResetWarn(tpId, "delayed-death clip contract drifted for " .. key)
            return
        end
    end
    for key in pairs(expected) do
        animations[key].playbackMode = AnimationPlaybackMode.Clamp
    end
end

local SCO_IdleResetSummitMainTurrets = {
    { weaponIndex = 1, name = "FrontTurret01", bone = "Front_Turret01" },
    { weaponIndex = 2, name = "FrontTurret02", bone = "Front_Turret02" },
    { weaponIndex = 3, name = "BackTurret", bone = "Back_Turret" },
}
local SCO_IdleResetSummitAntiAir = {
    { weaponIndex = 4, name = "RightAAGun01", bone = "Right_Turret01" },
    { weaponIndex = 5, name = "RightAAGun02", bone = "Right_Turret03" },
    { weaponIndex = 6, name = "LeftAAGun01", bone = "Left_Turret01" },
    { weaponIndex = 7, name = "LeftAAGun02", bone = "Left_Turret03" },
}

local function SCO_IdleResetPrepareSummitAim(tp, alreadyReset)
    local weapons = tp.weapons
    local expectedDefault = alreadyReset and 0 or 10
    if type(weapons) ~= "table" or weapons[8] ~= nil then
        SCO_IdleResetWarn("uen3001", "weapon roster drifted")
        return false
    end
    for _, spec in ipairs(SCO_IdleResetSummitMainTurrets) do
        local weapon = weapons[spec.weaponIndex]
        local controllers = weapon and weapon.aimControllers
        local yawController = controllers and controllers[1]
        if not weapon or weapon.name ~= spec.name
            or weapon.projectileTemplate ~= "psu302g"
            or weapon.rangeMin ~= 0 or weapon.rangeMax ~= 150
            or type(controllers) ~= "table" or controllers[5] ~= nil
            or type(yawController) ~= "table"
            or yawController.aimBone ~= spec.bone
            or yawController.yawBone ~= spec.bone
            or yawController.pitchBone ~= nil
            or yawController.defaultYawAdjustment ~= 0
            or yawController.yawMin ~= -140 or yawController.yawMax ~= 140
            or yawController.yawSpeed ~= 25
        then
            SCO_IdleResetWarn("uen3001", spec.name .. " weapon contract drifted")
            return false
        end
        for barrelIndex = 1, 3 do
            local suffix = "0" .. barrelIndex
            local controller = controllers[barrelIndex + 1]
            if type(controller) ~= "table"
                or controller.aimBone ~= spec.bone .. "_Muzzle" .. suffix
                or controller.pitchBone ~= spec.bone .. "_Barrel" .. suffix
                or controller.yawBone ~= nil
                or controller.defaultPitchAdjustment ~= expectedDefault
                or controller.pitchMin ~= -20 or controller.pitchMax ~= 20
                or controller.pitchSpeed ~= 10
            then
                SCO_IdleResetWarn("uen3001", spec.name .. " barrel " .. barrelIndex .. " aim contract drifted")
                return false
            end
        end
    end
    for _, spec in ipairs(SCO_IdleResetSummitAntiAir) do
        local weapon = weapons[spec.weaponIndex]
        local controllers = weapon and weapon.aimControllers
        local controller = controllers and controllers[1]
        if not weapon or weapon.name ~= spec.name
            or weapon.projectileTemplate ~= "psu302a"
            or type(controllers) ~= "table" or controllers[2] ~= nil
            or type(controller) ~= "table"
            or controller.aimBone ~= spec.bone .. "_Muzzle01"
            or controller.pitchBone ~= spec.bone .. "_Barrel01"
            or controller.defaultPitchAdjustment ~= 45
            or controller.pitchMin ~= -40 or controller.pitchMax ~= 40
            or controller.pitchSpeed ~= 180
        then
            SCO_IdleResetWarn("uen3001", spec.name .. " anti-air contract drifted")
            return false
        end
    end
    if not alreadyReset then
        for _, spec in ipairs(SCO_IdleResetSummitMainTurrets) do
            local controllers = weapons[spec.weaponIndex].aimControllers
            for barrelIndex = 1, 3 do
                controllers[barrelIndex + 1].defaultPitchAdjustment = 0
            end
        end
    end
    return true
end

local function SCO_IdleResetPrepareAimPose(tp, tpId)
    if tpId ~= "uen3001" then
        return
    end
    local additions = tp.additions
    if additions == nil then
        additions = {}
    elseif type(additions) ~= "table" then
        SCO_IdleResetWarn(tpId, "invalid additions table for aim reset")
        return
    end
    local marker = additions.scoIdleResetAimPose
    if marker ~= nil and marker ~= true then
        SCO_IdleResetWarn(tpId, "conflicting aim-reset marker")
        return
    end
    local alreadyReset = marker == true
    local valid = SCO_IdleResetPrepareSummitAim(tp, alreadyReset)
    if valid and not alreadyReset then
        additions.scoIdleResetAimPose = true
        tp.additions = additions
    end
end

local function SCO_IdleResetPrepareTemplate(tp)
    local general = tp and tp.general
    local tpId = general and general.tpId
    SCO_IdleResetPrepareDelayedDeathPlayback(tp, tpId)
    SCO_IdleResetPrepareAimPose(tp, tpId)
    if SCO_SourceFinalizerOwnsIdleResetTurretRest ~= true then
        SCO_IdleResetFinalizeSourceTemplate(tp)
    end
    local expectedGait = tpId and SCO_IdleResetExpectedGaits[tpId]
    if not expectedGait then
        return
    end

    local animations = tp.visuals and tp.visuals.animations
    if type(animations) ~= "table" then
        SCO_IdleResetWarn(tpId, "missing audited SCOM animation table")
        return
    end

    local idle = animations.walk
    local gait = animations.run
    local needsPromotion = gait == nil
    if gait then
        if gait.clipName ~= expectedGait then
            SCO_IdleResetWarn(tpId, "unexpected SCOM run clip " .. tostring(gait.clipName))
            return
        end
        if type(idle) ~= "table" or idle.clipName == expectedGait then
            SCO_IdleResetWarn(tpId, "missing distinct stopped animation")
            return
        end
    else
        gait = idle
        if type(gait) ~= "table" or gait.clipName ~= expectedGait then
            SCO_IdleResetWarn(tpId, "unexpected SCOM locomotion binding " .. tostring(gait and gait.clipName))
            return
        end
        if type(gait.sanAnimationPath) ~= "string" or gait.sanAnimationPath == "" then
            SCO_IdleResetWarn(tpId, "missing SCOM locomotion animation path")
            return
        end
    end

    local authoredSpeed = gait.authoredSpeed
    if authoredSpeed == nil and tp.movement and tp.movement.walkAnimation then
        authoredSpeed = tp.movement.walkAnimation.authoredSpeed
    end
    if type(authoredSpeed) ~= "number" or authoredSpeed <= 0 then
        SCO_IdleResetWarn(tpId, "missing positive SCOM gait authored speed")
        return
    end
    local startSpeed = gait.startSpeed
    if startSpeed == nil then
        startSpeed = 0.05
    elseif type(startSpeed) ~= "number" or startSpeed <= 0 then
        SCO_IdleResetWarn(tpId, "invalid SCOM gait start speed")
        return
    end

    local additions = tp.additions
    if additions == nil then
        additions = {}
    elseif type(additions) ~= "table" then
        SCO_IdleResetWarn(tpId, "invalid additions table")
        return
    end
    if additions.scoIdleResetLocomotion ~= nil
        and additions.scoIdleResetLocomotion ~= true
    then
        SCO_IdleResetWarn(tpId, "conflicting idle-reset marker")
        return
    end

    if needsPromotion then
        animations.run = gait
        animations.walk = {
            clipName = "Rest",
            sanAnimationPath = gait.sanAnimationPath,
        }
    end
    gait.authoredSpeed = authoredSpeed
    gait.startSpeed = startSpeed
    additions.scoIdleResetLocomotion = true
    tp.additions = additions
end

local SCO_IdleResetCreateUnitPrefab = CreateUnitPrefab
function CreateUnitPrefab(tp)
    if not SCOM_EditableUnits.IsEditable(tp) then SCO_IdleResetPrepareTemplate(tp) end
    return SCO_IdleResetCreateUnitPrefab(tp)
end

