local function SCO_GameplayNearlyEqual(left, right)
    return type(left) == "number" and math.abs(left - right) <= 0.000001
end

local function SCO_GameplayWarn(tpId, reason)
    if Warn then
        Warn("[SCOM Gameplay Corrections] Skipped " .. tostring(tpId) .. "; " .. reason)
    end
end

local function SCO_GameplayPrepareT1ExtractorVision(tp, tpId)
    local additions = tp.additions
    local intel = tp.intel
    local ranges = tp.ranges
    local visionRange = ranges and ranges[RangeRingMaterial.Vision]
    local fogRange = ranges and ranges[RangeRingMaterial.FogOfWar]
    local marker = additions and additions.scoGameplayT1ExtractorVision
    if type(additions) ~= "table" or type(intel) ~= "table"
        or type(visionRange) ~= "table" or type(fogRange) ~= "table"
        or visionRange.innerRadius ~= 0 or fogRange.innerRadius ~= 0
    then
        SCO_GameplayWarn(tpId, "T1 extractor vision shape drifted")
        return
    end
    if marker == "1.1.0" then
        if intel.visionRadius ~= 15
            or visionRange.outerRadius ~= 15
            or fogRange.outerRadius ~= 15
        then
            SCO_GameplayWarn(tpId, "marked T1 extractor vision contract drifted")
        end
        return
    end
    if marker ~= nil then
        SCO_GameplayWarn(tpId, "unknown T1 extractor vision marker")
        return
    end
    local legacyMatches = intel.visionRadius == 0
        and visionRange.outerRadius == 0
        and fogRange.outerRadius == 0
    local correctedMatches = intel.visionRadius == 15
        and visionRange.outerRadius == 15
        and fogRange.outerRadius == 15
    if not legacyMatches and not correctedMatches then
        SCO_GameplayWarn(tpId, "unmarked T1 extractor vision contract drifted")
        return
    end
    intel.visionRadius = 15
    visionRange.outerRadius = 15
    fogRange.outerRadius = 15
    additions.scoGameplayT1ExtractorVision = "1.1.0"
end

local SCO_GameplayFactionTags = { "EDA", "CHOSEN", "GUARD", "SERAPHIM" }
local function SCO_GameplayHasOnlyFaction(tp, expected)
    local count = 0
    local found = false
    for _, factionTag in ipairs(SCO_GameplayFactionTags) do
        if table.find(tp.tags, factionTag) then
            count = count + 1
            if factionTag == expected then found = true end
        end
    end
    return count == 1 and found
end

local function SCO_GameplayCommanderBeamMatches(tp, boneName, shrink)
    local additions = tp.additions
    local construction = tp.construction
    local beam = construction and construction.beam
    local bones = additions and additions.buildBeamBones
    local offset = beam and beam.offset
    return type(bones) == "table" and #bones == 1 and bones[1] == boneName
        and type(beam) == "table" and beam.boneName == boneName
        and SCO_GameplayNearlyEqual(beam.shrink, shrink)
        and type(offset) == "table" and offset.x == 0 and offset.y == 0 and offset.z == 0
end

local function SCO_GameplayEngineerBeamMatches(tp, boneName, expectedBones, shrink)
    local additions = tp.additions
    local construction = tp.construction
    local beam = construction and construction.beam
    local bones = additions and additions.buildBeamBones
    local offset = beam and beam.offset
    if type(bones) ~= "table" or #bones ~= #expectedBones then return false end
    for index, bone in ipairs(expectedBones) do
        if bones[index] ~= bone then return false end
    end
    return type(beam) == "table" and beam.boneName == boneName
        and SCO_GameplayNearlyEqual(beam.shrink, shrink)
        and type(offset) == "table" and offset.x == 0 and offset.y == 0 and offset.z == 0
end

local function SCO_GameplayPrepareEngineerBeam(tp, tpId, spec)
    local additions = tp.additions
    local construction = tp.construction
    local marker = additions and additions.scoGameplayEngineerBeam
    if type(additions) ~= "table" or type(construction) ~= "table"
        or type(tp.tags) ~= "table" or not SCO_GameplayHasOnlyFaction(tp, spec.faction)
    then
        SCO_GameplayWarn(tpId, "engineer construction-beam faction/shape drifted")
        return
    end
    if marker == "1.0.0" then
        if not SCO_GameplayEngineerBeamMatches(tp, spec.bone, spec.bones, 0.05) then
            SCO_GameplayWarn(tpId, "marked engineer construction-beam contract drifted")
        end
        return
    end
    if marker ~= nil then
        SCO_GameplayWarn(tpId, "unknown engineer construction-beam marker")
        return
    end
    if not SCO_GameplayEngineerBeamMatches(tp, spec.oldBone, spec.oldBones, spec.oldShrink) then
        SCO_GameplayWarn(tpId, "unmarked engineer construction-beam contract drifted")
        return
    end
    construction.beam.boneName = spec.bone
    construction.beam.shrink = 0.05
    additions.buildBeamBones = spec.bones
    additions.scoGameplayEngineerBeam = "1.0.0"
end

local function SCO_GameplayPrepareCommanderBeam(tp, tpId, spec)
    local additions = tp.additions
    local construction = tp.construction
    local marker = additions and additions.scoGameplayCommanderBeam
    if type(additions) ~= "table" or type(construction) ~= "table"
        or type(tp.tags) ~= "table" or not SCO_GameplayHasOnlyFaction(tp, spec.faction)
    then
        SCO_GameplayWarn(tpId, "commander construction-beam faction/shape drifted")
        return
    end
    if marker == "1.3.0" then
        if not SCO_GameplayCommanderBeamMatches(tp, spec.bone, 0.05) then
            SCO_GameplayWarn(tpId, "marked commander construction-beam contract drifted")
        end
        return
    end
    if marker ~= nil then
        SCO_GameplayWarn(tpId, "unknown commander construction-beam marker")
        return
    end
    local oldMatches
    if spec.oldBone == false then
        oldMatches = additions.buildBeamBones == nil and construction.beam == nil
    else
        oldMatches = SCO_GameplayCommanderBeamMatches(tp, spec.oldBone, spec.oldShrink)
    end
    if not oldMatches then
        SCO_GameplayWarn(tpId, "unmarked commander construction-beam contract drifted")
        return
    end
    local beam = construction.beam or {}
    beam.boneName = spec.bone
    beam.offset = { x = 0, y = 0, z = 0 }
    beam.shrink = 0.05
    construction.beam = beam
    additions.buildBeamBones = { spec.bone }
    additions.scoGameplayCommanderBeam = "1.3.0"
end

local function SCO_GameplayPrepareEngineer(tp, tpId, spec)
    local additions = tp.additions
    local source = additions and additions.faSourceContract
    local water = additions and additions.faEngineerWaterAnimation
    local movement = tp.movement
    local animations = tp.visuals and tp.visuals.animations
    local marker = additions and additions.scoGameplayEngineerFloating
    local expectedMapping = spec.sourceId .. " -> " .. tpId
    local expectedAltitude = marker == true and "GroundOrWater" or "Ground"
    local waterIsValid = type(water) == "table"
        and water.mapping == expectedMapping and water.sourceRate == 1
        and type(animations) == "table"
        and type(animations.waterTransform) == "table"
        and animations.waterTransform.clipName == "AnimWater"
    if marker == true and spec.disableMalformedWaterAnimation then
        waterIsValid = water == nil and type(animations) == "table"
            and animations.waterTransform == nil
    end
    if type(additions) ~= "table"
        or type(source) ~= "table" or source.mapping ~= expectedMapping
        or not waterIsValid
        or type(movement) ~= "table" or movement.type ~= "TracksAmphibious"
        or movement.preferredAltitude ~= 0
        or movement.referenceAltitude ~= expectedAltitude
        or type(animations) ~= "table"
        or type(animations.walk) ~= "table" or animations.walk.clipName ~= "Rest"
        or (marker ~= nil and marker ~= true)
    then
        SCO_GameplayWarn(tpId, "engineer movement/water contract drifted")
        return
    end
    movement.referenceAltitude = "GroundOrWater"
    if spec.disableMalformedWaterAnimation then
        additions.faEngineerWaterAnimation = nil
        animations.waterTransform = nil
    end
    additions.scoGameplayEngineerFloating = true
end

local function SCO_GameplayPrepareArtillery(tp, tpId, spec)
    local additions = tp.additions
    local weapon = tp.weapons and tp.weapons[1]
    local controllers = weapon and weapon.aimControllers
    local aim = controllers and controllers[1]
    local marker = additions and additions.scoGameplayT1ArtilleryArc
    local gravity = aim and aim.aimGravity
    local gravityIsValid = gravity == nil
        or (type(gravity) == "table"
            and gravity.x == 0 and gravity.y == -4.9 and gravity.z == 0)
    local reduce = aim and aim.reduceMuzzleVelocityToTarget
    local reduceIsValid = marker == true and reduce == true
        or marker == nil and (reduce == nil or reduce == spec.reduce or reduce == true)
    local lifetimeIsValid = marker == true
        and SCO_GameplayNearlyEqual(weapon and weapon.projectileLifetime, 20)
        or marker == nil and (SCO_GameplayNearlyEqual(weapon and weapon.projectileLifetime, spec.lifetime)
            or SCO_GameplayNearlyEqual(weapon and weapon.projectileLifetime, 20))
    local yawIsValid = spec.yaw == nil
        or marker == true and aim and aim.yawBone == spec.yaw
        or marker == nil and aim and (aim.yawBone == spec.oldYaw or aim.yawBone == spec.yaw)
    local pitchIsValid = spec.pitch == nil
        or marker == true and aim and aim.pitchBone == spec.pitch
        or marker == nil and aim and (aim.pitchBone == spec.oldPitch or aim.pitchBone == spec.pitch)
    local lead = aim and aim.leadTarget
    local leadIsValid = marker == true and lead == false
        or marker == nil and (lead == nil or type(lead) == "boolean")
    local pitchAdjustment = aim and aim.defaultPitchAdjustment
    local pitchAdjustmentIsValid = spec.pitchAdjustment == nil
        or marker == true and pitchAdjustment == spec.pitchAdjustment
        or marker == nil and (pitchAdjustment == nil or pitchAdjustment == 0
            or pitchAdjustment == spec.pitchAdjustment)
    if type(additions) ~= "table"
        or type(weapon) ~= "table" or tp.weapons[2] ~= nil
        or weapon.projectileTemplate ~= spec.projectile
        or weapon.rangeMax ~= 30 or weapon.rangeMin ~= spec.rangeMin
        or not SCO_GameplayNearlyEqual(weapon.reloadTime, spec.reload)
        or not lifetimeIsValid
        or type(controllers) ~= "table" or controllers[2] ~= nil
        or type(aim) ~= "table" or aim.projectileSpeed ~= 14
        or aim.solverType ~= "HighArc"
        or not reduceIsValid
        or not gravityIsValid
        or not leadIsValid
        or not pitchAdjustmentIsValid
        or not pitchIsValid
        or (spec.yaw ~= nil and (aim.aimBone ~= spec.aim
            or not yawIsValid))
        or (marker ~= nil and marker ~= true)
    then
        SCO_GameplayWarn(tpId, "T1 artillery ballistic contract drifted")
        return
    end
    aim.aimGravity = { x = 0, y = -4.9, z = 0 }
    aim.leadTarget = false
    aim.reduceMuzzleVelocityToTarget = true
    if spec.yaw ~= nil then aim.yawBone = spec.yaw end
    if spec.pitch ~= nil then aim.pitchBone = spec.pitch end
    if spec.pitchAdjustment ~= nil then
        aim.defaultPitchAdjustment = spec.pitchAdjustment
    end
    weapon.projectileLifetime = 20
    additions.scoGameplayT1ArtilleryArc = true
end

local function SCO_GameplayPrepareTemplate(tp)
    local tpId = tp and tp.general and tp.general.tpId
    if tpId and SCO_GameplayT1ExtractorVisionIds[tpId] then
        SCO_GameplayPrepareT1ExtractorVision(tp, tpId)
    end
    local engineer = tpId and SCO_GameplayEngineerSpecs[tpId]
    if engineer then SCO_GameplayPrepareEngineer(tp, tpId, engineer) end
    local engineerBeam = tpId and SCO_GameplayEngineerBeamSpecs[tpId]
    if engineerBeam then SCO_GameplayPrepareEngineerBeam(tp, tpId, engineerBeam) end
    local commander = tpId and SCO_GameplayCommanderBeamSpecs[tpId]
    if commander then SCO_GameplayPrepareCommanderBeam(tp, tpId, commander) end
    local artillery = tpId and SCO_GameplayArtillerySpecs[tpId]
    if artillery then SCO_GameplayPrepareArtillery(tp, tpId, artillery) end
end

local SCO_GameplayCreateUnitPrefab = CreateUnitPrefab
function CreateUnitPrefab(tp)
    if not SCOM_EditableUnits.IsEditable(tp) then SCO_GameplayPrepareTemplate(tp) end
    return SCO_GameplayCreateUnitPrefab(tp)
end
-- SCOM Field Fix: isolated Galactic Colossus eye calibration 1.0.2
function SCO_FieldFixGalacticColossusEye(tp, tpId)
    local version = "1.0.1"
    local markerName = "scoFieldFixGalacticColossusEye"

    if tpId == nil and type(tp) == "table" and type(tp.general) == "table" then
        tpId = tp.general.tpId
    end
    if tpId ~= "ucl4004" then return end

    local function fail(message)
        error("SCOM Galactic Colossus eye calibration " .. version
            .. ": " .. message, 2)
    end
    local function needTable(value, path)
        if type(value) ~= "table" then fail(path .. " must be a table") end
        return value
    end
    local function needString(value, path)
        if type(value) ~= "string" or value == "" then
            fail(path .. " must be a non-empty string")
        end
        return value
    end
    local function needNumber(value, path)
        if type(value) ~= "number" then fail(path .. " must be a number") end
        return value
    end

    tp = needTable(tp, "template")
    local general = needTable(tp.general, "general")
    if general.tpId ~= tpId then fail("general.tpId identity mismatch") end
    local additions = needTable(tp.additions, "additions")
    local existingMarker = additions[markerName]
    local existingContract = additions.scoFieldFixColossusEye
    if existingMarker ~= nil and existingMarker ~= version then
        fail("unsupported existing " .. markerName .. " marker")
    end
    if existingMarker == nil and existingContract ~= nil then
        fail("unmarked source already owns a Galactic Colossus eye contract")
    end

    local weapons = needTable(tp.weapons, "weapons")
    local weapon = needTable(weapons[1], "weapons[1]")
    if weapon.scoSourceLabel ~= "EyeWeapon" or weapon.beamLifetime ~= -1 then
        fail("weapons[1] must remain the reviewed persistent EyeWeapon")
    end
    local weaponMarker = weapon.scoFieldFixGalacticColossusEye
    if weaponMarker ~= nil and weaponMarker ~= version then
        fail("unsupported eye weapon marker")
    end
    local controllers = needTable(weapon.aimControllers,
        "weapons[1].aimControllers")
    if #controllers ~= 1 then fail("eye must contain exactly one aim controller") end
    local aim = needTable(controllers[1], "weapons[1].aimControllers[1]")
    if aim.aimBone ~= "Head_Muzzle"
        or aim.yawBone ~= "Head"
        or (aim.pitchBone ~= "Head" and aim.pitchBone ~= "Head_Muzzle")
    then
        fail("eye aim hierarchy must use Head yaw and Head/Head_Muzzle pitch")
    end
    local defaultPitchAdjustment = needNumber(
        aim.defaultPitchAdjustment,
        "weapons[1].aimControllers[1].defaultPitchAdjustment")
    local reviewedIdlePitch = defaultPitchAdjustment == -20
        or (existingMarker == version and defaultPitchAdjustment == 0)
    if aim.solverType ~= "NoArc"
        or aim.leadTarget ~= false
        or needNumber(aim.projectileSpeed,
            "weapons[1].aimControllers[1].projectileSpeed") ~= 30
        or needNumber(aim.defaultYawAdjustment,
            "weapons[1].aimControllers[1].defaultYawAdjustment") ~= 0
        or not reviewedIdlePitch
        or needNumber(aim.yawMin,
            "weapons[1].aimControllers[1].yawMin") ~= -70
        or needNumber(aim.yawMax,
            "weapons[1].aimControllers[1].yawMax") ~= 70
        or needNumber(aim.yawSpeed,
            "weapons[1].aimControllers[1].yawSpeed") ~= 70
        or needNumber(aim.pitchMin,
            "weapons[1].aimControllers[1].pitchMin") ~= -90
        or needNumber(aim.pitchMax,
            "weapons[1].aimControllers[1].pitchMax") ~= 50
        or needNumber(aim.pitchSpeed,
            "weapons[1].aimControllers[1].pitchSpeed") ~= 60
    then
        fail("eye active-aim contract drifted from reviewed UAL0401 fields")
    end
    if needNumber(weapon.rangeMin, "weapons[1].rangeMin") ~= 2
        or needNumber(weapon.rangeMax, "weapons[1].rangeMax") ~= 40
    then
        fail("eye weapon range must remain 2 through 40")
    end
    local groups = needTable(weapon.muzzleGroups, "weapons[1].muzzleGroups")
    if #groups ~= 1 then fail("eye must contain exactly one muzzle group") end
    local group = needTable(groups[1], "weapons[1].muzzleGroups[1]")
    local groupMuzzles = needTable(group.muzzles,
        "weapons[1].muzzleGroups[1].muzzles")
    if #groupMuzzles ~= 1 then fail("eye muzzle group must contain one muzzle") end
    local oldBone = needString(groupMuzzles[1],
        "weapons[1].muzzleGroups[1].muzzles[1]")
    if oldBone ~= "Head" and oldBone ~= "Head_Muzzle" then
        fail("eye muzzle-group bone must be Head or Head_Muzzle")
    end

    local muzzles = needTable(weapon.muzzles, "weapons[1].muzzles")
    local sourceMuzzle = muzzles.Head
    local desiredMuzzle = muzzles.Head_Muzzle
    if sourceMuzzle ~= nil and type(sourceMuzzle) ~= "table" then
        fail("weapons[1].muzzles.Head must be nil or a table")
    end
    if desiredMuzzle ~= nil and type(desiredMuzzle) ~= "table" then
        fail("weapons[1].muzzles.Head_Muzzle must be nil or a table")
    end
    if sourceMuzzle ~= nil and desiredMuzzle ~= nil
        and sourceMuzzle ~= desiredMuzzle
    then
        fail("source and calibrated eye muzzles disagree")
    end
    local muzzle = sourceMuzzle or desiredMuzzle
    if muzzle == nil then fail("eye muzzle map is missing") end
    if muzzle.aimController ~= "Head_Muzzle" then
        fail("eye muzzle aim controller must be Head_Muzzle")
    end

    local beam = needTable(weapon.beam, "weapons[1].beam")
    local subMesh = needTable(beam.subMesh, "weapons[1].beam.subMesh")
    if #subMesh ~= 2 then
        fail("weapons[1].beam.subMesh must contain exactly two entries")
    end
    local eyeMaterials = {
        {
            model = "VFX/Models/Beams/BeamBasicLongSingle.sanmodel",
            source = "VFX/AeonProjectiles/Materials/GalacticColossus/galactic_colossus_eye_core.sanmaterial",
            desired = "VFX/SupremeCommanderOverhaul/FieldFixes/GalacticColossus/galactic_colossus_eye_core_low_bloom.sanmaterial",
        },
        {
            model = "VFX/Models/Beams/BeamBasicLongSingle_2X.sanmodel",
            source = "VFX/AeonProjectiles/Materials/GalacticColossus/galactic_colossus_eye_aura.sanmaterial",
            desired = "VFX/SupremeCommanderOverhaul/FieldFixes/GalacticColossus/galactic_colossus_eye_aura_low_bloom.sanmaterial",
        },
    }
    for index, expected in ipairs(eyeMaterials) do
        local entry = needTable(subMesh[index],
            "weapons[1].beam.subMesh[" .. index .. "]")
        if needString(entry.model,
            "weapons[1].beam.subMesh[" .. index .. "].model") ~= expected.model
        then
            fail("weapons[1].beam.subMesh[" .. index
                .. "].model does not match the Galactic Colossus eye")
        end
        local material = needString(entry.material,
            "weapons[1].beam.subMesh[" .. index .. "].material")
        if material ~= expected.source and material ~= expected.desired then
            fail("weapons[1].beam.subMesh[" .. index
                .. "].material is not an owned Galactic Colossus eye material")
        end
    end

    if existingMarker == version then
        if weaponMarker ~= version then fail("marked eye weapon contract drifted") end
        if oldBone ~= "Head_Muzzle" or sourceMuzzle ~= nil then
            fail("marked eye muzzle routing drifted")
        end
        if aim.pitchBone ~= "Head_Muzzle" or aim.aimTolerance ~= 0.05 then
            fail("marked eye aim hierarchy or tolerance drifted")
        end
        for index, expected in ipairs(eyeMaterials) do
            if subMesh[index].material ~= expected.desired then
                fail("marked eye material routing drifted")
            end
        end
        local contract = needTable(existingContract,
            "additions.scoFieldFixColossusEye")
        if contract.version ~= version
            or contract.muzzleBone ~= "Head_Muzzle"
            or contract.aimBone ~= "Head_Muzzle"
            or contract.yawBone ~= "Head"
            or contract.pitchBone ~= "Head_Muzzle"
            or contract.aimTolerance ~= 0.05
            or contract.beamWidthScale ~= 0.6
            or contract.coreIntensity ~= 2000
            or contract.auraIntensity ~= 250
            or contract.offTargetHostGateRequired ~= true
        then
            fail("marked eye client contract drifted")
        end
        return
    end

    if oldBone ~= "Head" or sourceMuzzle == nil or desiredMuzzle ~= nil
        or aim.pitchBone ~= "Head"
    then
        fail("unmarked eye muzzle routing does not match the reviewed source")
    end
    if weaponMarker ~= nil then fail("unmarked source already owns the eye weapon") end
    if aim.aimTolerance ~= 2 then
        fail("unmarked eye aim tolerance does not match the reviewed source")
    end
    for index, expected in ipairs(eyeMaterials) do
        if subMesh[index].material ~= expected.source then
            fail("unmarked eye material routing does not match the reviewed source")
        end
    end

    -- Validate every source field before committing this small in-place mutation.
    groupMuzzles[1] = "Head_Muzzle"
    muzzles.Head_Muzzle = muzzle
    muzzles.Head = nil
    -- Trebuchet stores yaw and pitch as separate rotation writers. Keeping both
    -- on Head aliases two equal-depth records and makes their composition
    -- order-dependent; the zero-offset child composes pitch after its parent yaw.
    aim.pitchBone = "Head_Muzzle"
    aim.aimTolerance = 0.05
    weapon.scoFieldFixGalacticColossusEye = version
    for index, expected in ipairs(eyeMaterials) do
        subMesh[index].material = expected.desired
    end
    additions.scoFieldFixColossusEye = {
        version = version,
        muzzleBone = "Head_Muzzle",
        aimBone = "Head_Muzzle",
        yawBone = "Head",
        pitchBone = "Head_Muzzle",
        aimTolerance = 0.05,
        beamWidthScale = 0.6,
        coreIntensity = 2000,
        auraIntensity = 250,
        beamMaterialPaths = {
            core = eyeMaterials[1].desired,
            aura = eyeMaterials[2].desired,
        },
        brightnessOwnedByMaterials = true,
        brightnessRuntimeConsumerRequired = false,
        runtimeBeamWidthConsumerRequired = true,
        offTargetHostGateRequired = true,
        authoredIdlePitchPreserved = true,
        sameBoneAimWritersRemoved = true,
    }
    additions[markerName] = version
end

local SCO_GalacticColossusPreviousCreateUnitPrefab = CreateUnitPrefab
function CreateUnitPrefab(tp)
    if type(tp) ~= "table" then
        error("SCOM Galactic Colossus calibration requires a unit template table.", 2)
    end
    local tpId = tp.general and tp.general.tpId
    if type(tpId) ~= "string" or tpId == "" then
        error("SCOM Galactic Colossus calibration requires UnitTemplate.general.tpId.", 2)
    end

    if not SCOM_EditableUnits.IsEditable(tp) then SCO_FieldFixGalacticColossusEye(tp, tpId) end
    return SCO_GalacticColossusPreviousCreateUnitPrefab(tp)
end
