            maxAmmo = 3, rangeMin = 128, rangeMax = 1024,
            alloys = 15000, energy = 1800000, innerDamage = 75000,
        },
    }

    local targeted = shieldSpecs[tpId] ~= nil
        or pgenIds[tpId]
        or tpId == "uea1201"
        or landFactorySpecs[tpId] ~= nil
        or airFactorySpecs[tpId] ~= nil
        or navalFactorySpecs[tpId] ~= nil
        or tpId == "uen4001"
        or engineerIds[tpId]
        or tpId == "uel4511"
        or mmlSpecs[tpId] ~= nil
        or artillerySpecs[tpId] ~= nil
        or faArtillerySpecs[tpId] ~= nil
        or strategicSpecs[tpId] ~= nil

    if not targeted then
        return tp
    end

    local function fail(message)
        error("SCO Universal/UEF field fix [" .. tpId .. "]: " .. message, 2)
    end

    local function requireTable(value, path)
        if type(value) ~= "table" then
            fail(path .. " must be a table")
        end
        return value
    end

    local function requireNumber(value, path)
        if type(value) ~= "number" then
            fail(path .. " must be a number")
        end
        return value
    end

    local function hasTag(tags, wanted)
        for _, tag in ipairs(tags) do
            if tag == wanted then
                return true
            end
        end
        return false
    end

    local function requireTag(tags, wanted)
        if not hasTag(tags, wanted) then
            fail("tags is missing required tag " .. wanted)
        end
    end

    local function addTag(tags, wanted)
        if not hasTag(tags, wanted) then
            table.insert(tags, wanted)
        end
    end

    local function removeTag(tags, unwanted)
        local index = #tags
        while index >= 1 do
            if tags[index] == unwanted then
                table.remove(tags, index)
            end
            index = index - 1
        end
    end

    local function projectileWeapons(projectileTemplate)
        local weapons = requireTable(tp.weapons, "weapons")
        local result = {}
        for index, weapon in ipairs(weapons) do
            requireTable(weapon, "weapons[" .. index .. "]")
            if weapon.projectileTemplate == projectileTemplate then
                table.insert(result, { weapon = weapon, index = index })
            end
        end
        if #result == 0 then
            fail("weapons has no " .. projectileTemplate .. " projectile weapon")
        end
        return result
    end

    local function validateControllers(entry)
        local weapon = entry.weapon
        local base = "weapons[" .. entry.index .. "]"
        local controllers = requireTable(weapon.aimControllers, base .. ".aimControllers")
        if #controllers == 0 then
            fail(base .. ".aimControllers must not be empty")
        end
        for index, controller in ipairs(controllers) do
            requireTable(controller, base .. ".aimControllers[" .. index .. "]")
            if controller.aimTolerance ~= nil then
                requireNumber(controller.aimTolerance, base .. ".aimControllers[" .. index .. "].aimTolerance")
            end
            if controller.projectileSpeed ~= nil then
                requireNumber(controller.projectileSpeed, base .. ".aimControllers[" .. index .. "].projectileSpeed")
            end
        end
        return controllers
    end

    if tp.additions == nil then
        if navalFactorySpecs[tpId] then
            fail("additions must contain the post-Sea-Parity factory contracts")
        end
        tp.additions = {}
    else
        requireTable(tp.additions, "additions")
    end
    local marker = tp.additions.scoFieldFixUniversalUef
    if marker == resourceVersion then
        return tp
    end
    if marker ~= nil then
        fail("unsupported additions.scoFieldFixUniversalUef marker " .. tostring(marker))
    end

    local shield = shieldSpecs[tpId]
    if shield then
        local tags = requireTable(tp.tags, "tags")
        requireTag(tags, shield.faction)
        requireTag(tags, "SHIELD")
        requireTag(tags, "STRUCTURE")
        if shield.upgrade then
            local construction = requireTable(tp.construction, "construction")
            local economy = requireTable(tp.economy, "economy")
            requireNumber(economy.buildTime, "economy.buildTime")
            if economy.buildTime <= 0 then
                fail("economy.buildTime must be positive")
            end
            if construction.canBuild ~= nil and type(construction.canBuild) ~= "string" then
                fail("construction.canBuild must be a string")
            end
            if construction.upgradesTo ~= nil and type(construction.upgradesTo) ~= "string" then
                fail("construction.upgradesTo must be a string")
            end
            if construction.buildPower ~= nil then
                requireNumber(construction.buildPower, "construction.buildPower")
            end
            construction.buildPower = shield.buildPower
            construction.canBuild = "Tags." .. shield.upgrade
            construction.upgradesTo = shield.upgrade
            addTag(tags, "CONSTRUCTION")
            addTag(tags, "BUILDABLE_BY_T3_ENGINEER")
        end
        removeTag(tags, "DEMO_UI_ONLY")
        addTag(tags, shield.builder)
        addTag(tags, shield.tech)

    elseif pgenIds[tpId] then
        local economy = requireTable(tp.economy, "economy")
        local production = requireTable(economy.production, "economy.production")
        requireNumber(production.energy, "economy.production.energy")
        production.energy = 25

    elseif tpId == "uea1201" then
        local weapons = projectileWeapons("pef102")
        if #weapons ~= 1 then
            fail("expected exactly one pef102 weapon")
        end
        local controllers = validateControllers(weapons[1])
        if #controllers ~= 1 then
            fail("pef102 weapon must have exactly one aim controller")
        end
        local controller = controllers[1]
        if controller.aimBone ~= "Muzzle" then
            fail("pef102 aim controller must use verified Muzzle bone")
        end
        local sourceContract = requireTable(
            tp.additions.faSourceContract, "additions.faSourceContract")
        if sourceContract.sourceId ~= "UEA0102"
            or sourceContract.targetId ~= "uea1201"
            or sourceContract.sourceArchiveSha256
                ~= "c23a48d6b47043144baafc4c7f47b5a470392264f1bbaf962896923d58899c26"
        then
            fail("additions.faSourceContract does not match the pinned UEA0102 source")
        end
        local visuals = requireTable(tp.visuals, "visuals")
        local effects = requireTable(visuals.effectsPersistent, "visuals.effectsPersistent")
        if #effects ~= 2 then
            fail("visuals.effectsPersistent must contain the two reviewed donor exhausts")
        end
        local particleName = "VFX/Unit/veu4101_exhaust_aircraft_small.sanvfx"
        local foundBones = {}
        for index, effect in ipairs(effects) do
            requireTable(effect, "visuals.effectsPersistent[" .. index .. "]")
            if effect.particleName ~= particleName then
                fail("visuals.effectsPersistent contains an unrelated effect")
            end
            if effect.boneName ~= "Exhaust_Right" and effect.boneName ~= "Exhaust_Right01" then
                fail("visuals.effectsPersistent contains an unverified exhaust bone")
            end
            if foundBones[effect.boneName] then
                fail("visuals.effectsPersistent contains a duplicate exhaust bone")
            end
            foundBones[effect.boneName] = true
        end
        if not foundBones.Exhaust_Right or not foundBones.Exhaust_Right01 then
            fail("visuals.effectsPersistent is missing a reviewed exhaust bone")
        end
        controller.aimTolerance = 0.1
        sourceContract.exhaustVisual = {
            policyVersion = "1.0.1",
            sourceMode = "BeamExhaust",
            sourceBones = { "Exhaust_Right", "Exhaust_Right01" },
            sourceCruiseEmitter = "effects/emitters/air_move_trail_beam_03_emit.bp",
            sourceCruiseEmitterSha256 = "abaf5ebc736397f8580e17602d9f5b2b8eadb93418b2013a74e92f06ce9019ea",
            sourceCruise = { lifetime = 1, length = 0.6, thickness = 0.05, vShift = -0.65 },
            sourceIdleEmitter = "effects/emitters/air_idle_trail_beam_01_emit.bp",
            sourceIdleEmitterSha256 = "2c17ccb8da1e1f35b2abd82040e58eae559fc0f76e0a6c8304006e23b55c5e95",
            sourceIdle = { lifetime = 1, length = 0.18, thickness = 0.045, vShift = -0.45 },
            sourceContrailBones = { "Left_Contrail", "Right_Contrail" },
            sourceContrailEmitter = "effects/emitters/contrail_polytrail_01_emit.bp",
            sourceContrailEmitterSha256 = "8e05c7fb5c47ec34ddb432b3bdc4c481099b38281aaf4317365f9057445f1b7f",
            sourceEffectsArchiveSha256 = "f0dcbf76b2c3381e7d9ebbd7e09613e046875f6ba3a788406e5635768e28a300",
            runtimeStatus = "disabled-incompatible-world-space-particle-fallback",
            parityFollowUp = "dedicated-stateful-idle-cruise-contrail-vfx",
        }
        visuals.effectsPersistent = nil

    elseif landFactorySpecs[tpId] then
        local spec = landFactorySpecs[tpId]
        local tags = requireTable(tp.tags, "tags")
        local construction = requireTable(tp.construction, "construction")
        requireTag(tags, "EDA")
        requireTag(tags, "LAND_FACTORY")
        if type(construction.canBuild) ~= "string" then
            fail("construction.canBuild must be a string")
        end
        if construction.upgradesTo ~= nil and type(construction.upgradesTo) ~= "string" then
            fail("construction.upgradesTo must be a string or nil")
        end
        construction.canBuild = "Tags.EDA * Tags.BUILDABLE_BY_" .. spec.tech
            .. "_FACTORY * ((Tags.LAND * Tags.MOBILE) + Tags.LAND_FACTORY)"
        construction.upgradesTo = spec.upgrade

    elseif airFactorySpecs[tpId] then
        local spec = airFactorySpecs[tpId]
        local tags = requireTable(tp.tags, "tags")
        local construction = requireTable(tp.construction, "construction")
        requireTag(tags, "EDA")
        requireTag(tags, "AIR_FACTORY")
        if type(construction.canBuild) ~= "string" then
            fail("construction.canBuild must be a string")
        end
        if construction.upgradesTo ~= nil and type(construction.upgradesTo) ~= "string" then
            fail("construction.upgradesTo must be a string or nil")
        end
        construction.canBuild = "Tags.EDA * Tags.BUILDABLE_BY_" .. spec.tech
            .. "_FACTORY * ((Tags.AIR * Tags.MOBILE) + Tags.AIR_FACTORY + Tags.ENGINEER)"
        construction.upgradesTo = spec.upgrade

    elseif navalFactorySpecs[tpId] then
        local spec = navalFactorySpecs[tpId]
        requireTable(tp.tags, "tags")
        requireTag(tp.tags, "EDA")
        requireTag(tp.tags, "NAVAL_FACTORY")
        local general = requireTable(tp.general, "general")
        if general.requiresWaterPlacement ~= true then
            fail("general.requiresWaterPlacement must be true after Sea Parity")
        end
        if tp.additions.scoSeaParityMinimumWaterDepth ~= nil then
            fail("additions.scoSeaParityMinimumWaterDepth must be absent for a Sea-Parity factory")
        end
        local seaContract = requireTable(tp.additions.seaParitySourceContract,
            "additions.seaParitySourceContract")
        if seaContract.sourceId ~= spec.sourceId
            or seaContract.targetId ~= tpId
            or seaContract.sourceArchiveSha256
                ~= "C23A48D6B47043144BAAFC4C7F47B5A470392264F1BBAF962896923D58899C26"
        then
            fail("additions.seaParitySourceContract does not match the post-Sea-Parity source")
        end
        local contract = requireTable(tp.additions.faSourceContract,
            "additions.faSourceContract")
        if contract.sourceId ~= spec.sourceId or contract.targetId ~= tpId then
            fail("additions.faSourceContract source identity drifted")
        end
        requireNumber(contract.minimumWaterDepth,
            "additions.faSourceContract.minimumWaterDepth")
        if contract.minimumWaterDepth ~= 1.5 then
            fail("additions.faSourceContract.minimumWaterDepth must be the post-Sea-Parity value 1.5")
        end
        contract.minimumWaterDepth = 0.5

    elseif tpId == "uen4001" then
        local general = requireTable(tp.general, "general")
        local icon = requireTable(general.icon, "general.icon")
        local tags = requireTable(tp.tags, "tags")
        requireTag(tags, "EDA")
        requireTag(tags, "NAVAL")
        requireTag(tags, "CARRIER")
        requireTag(tags, "EXPERIMENTAL")
        if type(general.displayName) ~= "string" or type(general.iconUI) ~= "string" then
            fail("general displayName and iconUI must be strings")
        end
        removeTag(tags, "TECH1")
        removeTag(tags, "TECH2")
        removeTag(tags, "TECH3")
        addTag(tags, "TECH4")
        addTag(tags, "EXPERIMENTAL")
        general.displayName = "Tier 4: Atlantis"
        icon.shape = "experimental1"
        icon.symbol = "direct"
        icon.tech = "t1"
        general.iconUI = "tech1_experimental1_direct.png"

    elseif engineerIds[tpId] then
        local tags = requireTable(tp.tags, "tags")
        local movement = requireTable(tp.movement, "movement")
        requireTag(tags, "ENGINEER")
        requireTag(tags, "LAND")
        requireTag(tags, "MOBILE")
        if type(movement.referenceAltitude) ~= "string" then
            fail("movement.referenceAltitude must be a string")
        end
        movement.referenceAltitude = "GroundOrWater"

    elseif tpId == "uel4511" then
        local defence = requireTable(tp.defence, "defence")
        local shields = requireTable(defence.shields, "defence.shields")
        local primaryShield = requireTable(shields[1], "defence.shields[1]")
        local radii = requireTable(primaryShield.radii, "defence.shields[1].radii")
        requireNumber(radii.x, "defence.shields[1].radii.x")
        requireNumber(radii.y, "defence.shields[1].radii.y")
        requireNumber(radii.z, "defence.shields[1].radii.z")
        local gaussWeapons = projectileWeapons("psf401")
        if #gaussWeapons ~= 4 then
            fail("expected exactly four psf401 Gauss weapons")
        end
        for _, entry in ipairs(gaussWeapons) do
            local weapon = entry.weapon
            requireNumber(weapon.rangeMax, "weapons[" .. entry.index .. "].rangeMax")
            requireNumber(weapon.projectileLifetime, "weapons[" .. entry.index .. "].projectileLifetime")
            if weapon.rangeMax <= 0 then
                fail("Gauss rangeMax must be positive")
            end
            validateControllers(entry)
        end
        radii.x, radii.y, radii.z = 13, 13, 13
        for _, entry in ipairs(gaussWeapons) do
            local weapon = entry.weapon
            local minimumLifetime = 14
            if weapon.projectileLifetime < minimumLifetime then
                weapon.projectileLifetime = minimumLifetime
            end
            -- All four racks must resolve the same stable point. Random target
            -- bones can leave one rack's controller chain permanently off aim.
            weapon.scomAimAtTargetCollider = true
            weapon.firingRandomness = 0
            for _, controller in ipairs(weapon.aimControllers) do
                controller.aimTolerance = 2
                controller.projectileSpeed = 25
                controller.aimGravity = { x=0, y=-4.9, z=0 }
                controller.reduceMuzzleVelocityToTarget = true
                controller.solverType = "HighArc"
                if controller.pitchBone ~= nil then
                    controller.pitchMax = 80
                    controller.pitchAxis = {
                        x = 0,
                        y = 0,
                        z = entry.index <= 2 and -1 or 1,
                    }
                end
            end
        end

    elseif mmlSpecs[tpId] then
        local spec = mmlSpecs[tpId]
        local entries = projectileWeapons(spec.projectile)
        if #entries ~= 1 then
            fail("expected exactly one " .. spec.projectile .. " weapon")
        end
        local entry = entries[1]
        local weapon = entry.weapon
        requireNumber(weapon.rangeMax, "weapons[" .. entry.index .. "].rangeMax")
        if weapon.rangeMax <= 0 then
            fail("MML rangeMax must be positive")
        end
        if weapon.projectileLifetime ~= nil then
            requireNumber(weapon.projectileLifetime, "weapons[" .. entry.index .. "].projectileLifetime")
        end
        local controllers = validateControllers(entry)
        local minimumLifetime = 0
        for _, controller in ipairs(controllers) do
            if controller.aimTolerance == nil or controller.aimTolerance <= 0 then
                controller.aimTolerance = 0.1
            end
            if controller.projectileSpeed == nil or controller.projectileSpeed <= 0 then
                controller.projectileSpeed = spec.speed
            end
            local controllerLifetime = weapon.rangeMax / controller.projectileSpeed
            if controllerLifetime > minimumLifetime then
                minimumLifetime = controllerLifetime
            end
        end
        if weapon.projectileLifetime == nil or weapon.projectileLifetime < minimumLifetime then
            weapon.projectileLifetime = minimumLifetime
        end

    elseif faArtillerySpecs[tpId] then
        local spec = faArtillerySpecs[tpId]
        spec.version = version
        spec.targetId = tpId
        local tags = requireTable(tp.tags, "tags")
        local general = requireTable(tp.general, "general")
        local oldVisuals = requireTable(tp.visuals, "visuals")
        local display = requireTable(oldVisuals.display, "visuals.display")

        removeTag(tags, "DEMO_UI_ONLY")
        removeTag(tags, "TECH1")
        removeTag(tags, "TECH2")
        removeTag(tags, "TECH3")
        removeTag(tags, "TECH4")
        addTag(tags, "ARTILLERY")
        addTag(tags, "BUILDABLE_BY_T3_ENGINEER")
        addTag(tags, "EDA")
        addTag(tags, "INDIRECT_FIRE")
        addTag(tags, "STRATEGIC")
        addTag(tags, "STRUCTURE")
        if tpId == "ues2101" then
            addTag(tags, "BUILDABLE_BY_T2_ENGINEER")
            addTag(tags, "TECH2")
        else
            addTag(tags, "EXPERIMENTAL")
            addTag(tags, "TECH4")
        end

        tp.audio = {
            onDestroyed = { looping = false, name = spec.deathAudio },
        }
        tp.collisionInfo = {
            centerOffset = spec.collisionOffset,
            collisionSize = spec.collisionSize,
            targetBones = spec.targetBones,
        }
        tp.defence = {
            health = { max = spec.health, value = spec.health, regen = 0 },
        }
        tp.economy = {
            buildTime = spec.buildTime,
            cost = { alloys = spec.alloys, energy = spec.energy },
        }
        tp.footprint = spec.footprint
        tp.intel = { visionRadius = spec.vision }
        tp.skirtSize = { x = spec.skirt.x, y = spec.skirt.y }

        general.displayName = spec.displayName
        general.icon = { shape = "structure1", symbol = "indirect", tech = spec.iconTech }
        general.iconUI = "tech" .. string.sub(spec.iconTech, 2)
            .. "_structure1_indirect.png"
        general.iconUIBuildSortPriority = spec.buildSortPriority
        general.iconUIType = "land"
        general.name = spec.name
        general.orders = { Attack = true, Stop = true }
        general.threat = spec.threat.surface
        general.unitTypeName = tpId == "ues2101" and "UEFT2Artillery"
            or "UEFExperimentalArtillery"

        local animations = nil
        if spec.openingAnimation then
            local animationPath = "Units/" .. tpId .. "/LOD0/" .. tpId .. ".sananimation"
            animations = {
                walk = {
                    clipName = "Rest", sanAnimationPath = animationPath,
                    playbackMode = 0,
                },
                [spec.openingAnimation] = {
                    clipName = "AnimOpen", sanAnimationPath = animationPath,
                    playbackMode = 0,
                },
            }
        end
        tp.visuals = {
            animations = animations,
            display = display,
            effectsInstant = {
                onDeath = {
                    { boneName = "Root", particleName = spec.deathEffect },
                },
            },
            mesh = { lod0distance = spec.meshLod0Distance },
            selection = {
                offset = spec.selectionOffset,
                size = spec.selectionSize,
                thickness = spec.selectionThickness,
            },
        }

        local recoilBones = {}
        for _, recoil in ipairs(spec.recoil) do
            recoilBones[recoil.bone] = recoil.distance
        end
        tp.weapons = {
            {
                name = "MainGun",
                aimControllers = {
                    {
                        aimBone = spec.muzzle,
                        aimGravity = { x = 0, y = -4.9, z = 0 },
                        aimTolerance = spec.aimTolerance,
                        defaultPitchAdjustment = 0,
                        defaultYawAdjustment = 0,
                        leadTarget = false,
                        pitchBone = spec.pitchBone,
                        pitchMax = spec.pitchRange,
                        pitchMin = -spec.pitchRange,
                        pitchSpeed = spec.pitchSpeed,
                        poseResetTime = -1,
                        projectileSpeed = spec.projectileSpeed,
                        reduceMuzzleVelocityToTarget = spec.reduceMuzzleVelocityToTarget,
                        solverType = spec.solverType,
                        yawBone = spec.yawBone,
                        yawMax = spec.yawRange,
                        yawMin = -spec.yawRange,
                        yawSpeed = spec.yawSpeed,
                    },
                },
                audio = {
                    onFire = { looping = false, name = spec.fireAudio },
                },
                collideFriendly = spec.collideFriendly,
                damage = spec.damage,
                damageFriendly = spec.damageFriendly,
                damageRadius = spec.damageRadius,
                damageType = "Normal",
                effects = { onFire = spec.muzzleEffect },
                firingRandomness = spec.firingRandomness,
                layerTargetLimits = { "Land", "WaterSurface" },
                layerWeaponLimits = { "Land" },
                muzzleGroupChargeDelay = 0,
                muzzleGroupTimeOut = -1,
                muzzleGroups = {
                    { muzzles = { spec.muzzle }, recoilBones = recoilBones },
                },
                muzzleSalvoDelay = 0,
                muzzleSalvoSize = 1,
                muzzles = {
                    [spec.muzzle] = { aimController = spec.muzzle },
                },
                projectileLifetime = spec.projectileLifetime,
                projectileTemplate = spec.projectile,
                rangeMax = spec.rangeMax,
                rangeMin = spec.rangeMin,
                rangeRingType = "IndirectFire",
                rangeTracking = 1.1,
                recoilTime = spec.recoilTime,
                reloadTime = spec.reloadTime,
                targetWaterLimits = "Above",
            },
        }

        tp.additions.faSourceContract = {
            sourceId = spec.sourceId,
            targetId = tpId,
            sourceArchiveSha256 = "c23a48d6b47043144baafc4c7f47b5a470392264f1bbaf962896923d58899c26",
            sourceProjectilesArchiveSha256 = "60d2732597cde9ef046a663c8d439e60844f967147e14737c7ad5a08c641be12",
            sourceBlueprintSha256 = spec.sourceBlueprintSha256,
            sourceScriptSha256 = spec.sourceScriptSha256,
            sourceModelSha256 = spec.sourceModelSha256,
            sourceAnimationSha256 = spec.sourceAnimationSha256,
            sourceProjectile = spec.sourceProjectile,
            sourceProjectileSha256 = spec.sourceProjectileSha256,
            sourceUniformScale = spec.sourceUniformScale,
            textureResolution = 2048,
            basisYawDegrees = 180,
            footprint = spec.footprint,
            skirt = spec.skirt,
        }
        tp.additions.scoFaArtillery = spec

    elseif artillerySpecs[tpId] then
        local spec = artillerySpecs[tpId]
        local entries = projectileWeapons(spec.projectile)
        if #entries ~= 1 then
            fail("expected exactly one " .. spec.projectile .. " weapon")
        end
        local entry = entries[1]
        local weapon = entry.weapon
        requireNumber(weapon.rangeMax, "weapons[" .. entry.index .. "].rangeMax")
        if weapon.rangeMax <= 0 then
            fail("artillery rangeMax must be positive")
        end
        if weapon.projectileLifetime ~= nil then
            requireNumber(weapon.projectileLifetime, "weapons[" .. entry.index .. "].projectileLifetime")
        end
        local controllers = validateControllers(entry)
        local minimumLifetime = 0
        for _, controller in ipairs(controllers) do
            if controller.aimTolerance == nil or controller.aimTolerance <= 0 then
                controller.aimTolerance = 0.05
            end
            if controller.projectileSpeed == nil or controller.projectileSpeed <= 0 then
                controller.projectileSpeed = spec.speed
            end
            controller.solverType = "HighArc"
            controller.reduceMuzzleVelocityToTarget = true
            local controllerLifetime = weapon.rangeMax / controller.projectileSpeed * 1.25
            if controllerLifetime > minimumLifetime then
                minimumLifetime = controllerLifetime
            end
        end
        if weapon.projectileLifetime == nil or weapon.projectileLifetime < minimumLifetime then
            weapon.projectileLifetime = minimumLifetime
        end

    elseif strategicSpecs[tpId] then
        local spec = strategicSpecs[tpId]
        local general = requireTable(tp.general, "general")
        local tags = requireTable(tp.tags, "tags")
        general.orders = general.orders or {}
        requireTable(general.orders, "general.orders")
        general.toggles = general.toggles or {}
        requireTable(general.toggles, "general.toggles")
        general.orders.ManualFire1 = true
        general.orders.ManualFire2 = true
        general.orders.Stop = true
        general.toggles.Pause = false
        if tpId ~= "ucl4001" then
            general.orders.Attack = nil
            general.orders.AttackMove = nil
            general.orders.StrategicManualLaunch = nil
        end
        removeTag(tags, "DEMO_UI_ONLY")
        addTag(tags, "NUKE")
        addTag(tags, "SILO")
        addTag(tags, "INDIRECT_FIRE")

        tp.construction = tp.construction or {}
        requireTable(tp.construction, "construction")
        tp.construction.buildPower = 1080

        local expectedStrategicWeapons = 0
        if tpId == "ucs3102" or tpId == "uss3102" then
            expectedStrategicWeapons = 1
        end
        local strategicWeapons = 0
        local cruiseWeapons = 0
        local retainedWeapons = {}
        if tp.weapons ~= nil then
            local weapons = requireTable(tp.weapons, "weapons")
            for index, weapon in ipairs(weapons) do
                requireTable(weapon, "weapons[" .. index .. "]")
                local isStrategic = tpId == "ucs3102"
                        and weapon.scoSourceLabel == "QuantumMissiles"
                    or tpId == "uss3102"
                        and weapon.projectileTemplate == "pci211"
                    or tpId == "ucl4001"
                        and weapon.scoSourceLabel == "NukeMissiles"
                if isStrategic then
                    strategicWeapons = strategicWeapons + 1
                else
                    if weapon.projectileTemplate ~= nil then
                        if tpId == "ucl4001"
                            and weapon.scoSourceLabel == "CruiseMissiles"
                        then
                            cruiseWeapons = cruiseWeapons + 1
                        else
                            fail("unexpected non-silo projectile weapon")
                        end
                    end
                    table.insert(retainedWeapons, weapon)
                end
            end
            tp.weapons = retainedWeapons
        end

        if tpId == "ucl4001" then
            local unsupported = requireTable(tp.additions.seaParityUnsupported,
                "additions.seaParityUnsupported")
            if unsupported.nukeSilo ~= true then
                fail("SeaParity nuke-silo gate must be present")
            end
            if cruiseWeapons ~= 1 or strategicWeapons ~= 0 then
                fail("Silencer must retain exactly one CruiseMissiles weapon and no live nuke weapon")
            end
            unsupported.nukeSilo = nil
        end
        if strategicWeapons ~= expectedStrategicWeapons then
            fail("strategic source weapon count mismatch")
        end

        tp.additions.scoStrategicSilo = {
            version = version,
            initialAmmo = 0,
            creativeSpawnAmmo = spec.creativeSpawnAmmo,
            maxAmmo = spec.maxAmmo,
            defaultAutoBuild = true,
            buildPower = 1080,
            buildTime = 324000,
            cost = { alloys = spec.alloys, energy = spec.energy },
            muzzle = spec.muzzle,
            projectileTemplate = spec.projectile,
            projectileLifetime = 600,
            initialProjectileSpeed = 1,
            terrainClearance = 0.05,
            rangeMin = spec.rangeMin,
            rangeMax = spec.rangeMax,
            damageFriendly = true,
            innerDamage = {
                amount = spec.innerDamage,
                radius = spec.innerRadius or 30,
                ticks = 24,
                totalTime = 0,
            },
            outerDamage = {
                amount = spec.outerDamage or 500,
                radius = spec.outerRadius or 40,
                ticks = 20,
                totalTime = 0,
            },
            apocalypseFlight = spec.apocalypseFlight,
            buildOrder = "ManualFire1",
            launchOrder = "ManualFire2",
            launchAnimation = spec.launchAnimation,
        }
    end

    tp.additions.scoFieldFixUniversalUef = resourceVersion
    return tp
end

-- Strategic launchers deliberately remove their automatic nuke weapon before
-- prefab creation. Sanctuary normally marks muzzle bones as host-simulated
-- while walking live weapons, so the manual silo path must preserve that one
-- prefab invariant explicitly.
function SCO_FieldFixStrategicSiloMuzzleHierarchy(
    tp, entityNameToHierarchyIndex, hierarchyEntities)
    if type(tp) ~= "table"
        or type(entityNameToHierarchyIndex) ~= "table"
        or type(hierarchyEntities) ~= "table"
    then
        error("SCOM strategic silo muzzle hierarchy requires prefab tables.", 2)
    end

    local additions = tp.additions
    local contract = type(additions) == "table"
        and additions.scoStrategicSilo or nil
    if contract == nil then
        return hierarchyEntities
    end
    if type(contract) ~= "table" or contract.version ~= "1.0.0" then
        error("SCOM strategic silo muzzle hierarchy has an unsupported contract.", 2)
    end
    if type(contract.muzzle) ~= "string" or contract.muzzle == "" then
        error("SCOM strategic silo muzzle hierarchy has no muzzle name.", 2)
    end

    local hierarchyIndex = entityNameToHierarchyIndex[contract.muzzle]
    local muzzleEntity = hierarchyIndex and hierarchyEntities[hierarchyIndex]
    if muzzleEntity == nil then
        local tpId = tp.general and tp.general.tpId or "unknown"
        error("SCOM strategic silo [" .. tostring(tpId)
            .. "] skeleton is missing muzzle " .. contract.muzzle .. ".", 2)
    end
    muzzleEntity.forceSimulated = true
    return hierarchyEntities
end

function SCO_FieldFixCybran(tp, tpId)
    local version = "1.0.4"

    if type(tp) ~= "table" then
        error("SCO Cybran field fix requires a template table.", 2)
    end
    if tpId == nil and type(tp.general) == "table" then
        tpId = tp.general.tpId
    end
    if type(tpId) ~= "string" or tpId == "" then
        error("SCO Cybran field fix requires a non-empty template id.", 2)
    end

    local factoryTiers = { ugs1511 = 1, ugs2511 = 2, ugs3511 = 3 }
    local targeted = factoryTiers[tpId] ~= nil
        or tpId == "ugs3101"
        or tpId == "ugl4011"
        or tpId == "ugl2101"
        or tpId == "pgh204"
        or tpId == "ugs2001"
        or tpId == "ugn3001"
        or tpId == "ugl1101"
        or tpId == "ugl3002"
        or tpId == "pgr303d"
        or tpId == "pgr303b"
        or tpId == "ugs2501"
        or tpId == "ugs3501"

    -- UGL4001 remains owned by the installed Monkeylord final-owner pack.
    if not targeted then
        return tp
    end

    local function fail(message)
        error("SCO Cybran field fix [" .. tpId .. "]: " .. message, 2)
    end

    local function requireTable(value, path)
        if type(value) ~= "table" then
            fail(path .. " must be a table")
        end
        return value
    end

    local function requireNumber(value, path)
        if type(value) ~= "number" then
            fail(path .. " must be a number")
        end
        return value
    end

    local function requireExact(value, expected, path)
        if value ~= expected then
            fail(path .. " must be " .. tostring(expected) .. ", found " .. tostring(value))
        end
    end

    local function isAllowed(value, allowed)
        for _, candidate in ipairs(allowed) do
            if value == candidate then
                return true
            end
        end
        return false
    end

    local function requireAllowed(value, allowed, path)
        if not isAllowed(value, allowed) then
            fail(path .. " has an unowned value " .. tostring(value))
        end
    end

    local function countKeys(value)
        local count = 0
        for _ in pairs(value) do
            count = count + 1
        end
        return count
    end

    local function weaponByProjectile(projectileId)
        local weapons = requireTable(tp.weapons, "weapons")
        local found = nil
        local foundIndex = nil
        for index, weapon in ipairs(weapons) do
            requireTable(weapon, "weapons[" .. index .. "]")
            if weapon.projectileTemplate == projectileId then
                if found ~= nil then
                    fail("weapons contains more than one " .. projectileId .. " weapon")
                end
                found = weapon
                foundIndex = index
            end
        end
        if found == nil then
            fail("weapons is missing the verified " .. projectileId .. " weapon")
        end
        return found, foundIndex
    end

    if tp.additions == nil then
        tp.additions = {}
    else
        requireTable(tp.additions, "additions")
    end
    local marker = tp.additions.scoFieldFixCybran
    if marker == version then
        return tp
    end
    if marker ~= nil then
        fail("unsupported additions.scoFieldFixCybran marker " .. tostring(marker))
    end

    if factoryTiers[tpId] then
        local tier = factoryTiers[tpId]
        local construction = requireTable(tp.construction, "construction")
        local broken = "Tags.GUARD * Tags.BUILDABLE_BY_T" .. tier .. "_FACTORY * Tags.LAND"
        local legacyRepaired = "Tags.GUARD * Tags.BUILDABLE_BY_T" .. tier
            .. "_FACTORY * ((Tags.LAND * Tags.MOBILE) + Tags.LAND_FACTORY)"
        -- Salem must carry LAND for TracksAmphibious validation, while its FA
        -- production ownership remains NAVAL. Keep naval mobiles out of the
        -- land branch instead of weakening Salem's movement or naval tags.
        local repaired = "Tags.GUARD * Tags.BUILDABLE_BY_T" .. tier
            .. "_FACTORY * (((Tags.LAND * Tags.MOBILE) - Tags.NAVAL) + Tags.LAND_FACTORY)"
        requireAllowed(construction.canBuild,
            { broken, legacyRepaired, repaired }, "construction.canBuild")
        construction.canBuild = repaired

        -- Material schemas vary between generated and loose templates. Only
        -- update a NormalScale key already present in a material-owned subtree.
        if tier > 1 then
            local visited = {}
            local function repairNormalScale(value, path)
                if type(value) ~= "table" or visited[value] then
                    return
                end
                visited[value] = true
                for _, field in ipairs({ "NormalScale", "_NormalScale", "normalScale" }) do
                    if value[field] ~= nil then
                        requireNumber(value[field], path .. "." .. field)
                        value[field] = 1.25
                    end
                end
                for key, child in pairs(value) do
                    if type(child) == "table" then
                        repairNormalScale(child, path .. "." .. tostring(key))
                    end
                end
            end
            if tp.materials ~= nil then repairNormalScale(tp.materials, "materials") end
            if type(tp.visuals) == "table" then
                if tp.visuals.materials ~= nil then
                    repairNormalScale(tp.visuals.materials, "visuals.materials")
                end
                if tp.visuals.material ~= nil then
                    repairNormalScale(tp.visuals.material, "visuals.material")
                end
            end
            if tp.additions.materials ~= nil then
                repairNormalScale(tp.additions.materials, "additions.materials")
            end
        end

    elseif tpId == "ugs3101" then
        local weapon, weaponIndex = weaponByProjectile("pcg312")
        requireExact(weapon.rangeMin, 150, "Disruptor rangeMin")
        requireExact(weapon.rangeMax, 700, "Disruptor rangeMax")
        requireExact(weapon.projectileLifetime, 120,
            "Disruptor projectileLifetime")
        local controllers = requireTable(weapon.aimControllers, "weapons[" .. weaponIndex .. "].aimControllers")
        if #controllers ~= 1 then
            fail("Disruptor must have exactly one verified aim controller")
        end
        local controller = requireTable(controllers[1], "weapons[" .. weaponIndex .. "].aimControllers[1]")
        requireExact(controller.aimBone, "Turret_Muzzle", "Disruptor aimBone")
        requireExact(controller.yawBone, "Turret", "Disruptor yawBone")
        requireExact(controller.pitchBone, "Turret_Barrel", "Disruptor pitchBone")
        requireExact(controller.defaultYawAdjustment, 0,
            "Disruptor defaultYawAdjustment")
        requireExact(controller.yawMin, -180, "Disruptor yawMin")
        requireExact(controller.yawMax, 180, "Disruptor yawMax")
        requireAllowed(controller.yawSpeed, { 3, 5 }, "Disruptor yawSpeed")
        requireExact(controller.leadTarget, false, "Disruptor leadTarget")
        if controller.aimGravity ~= nil then
            local gravity = requireTable(controller.aimGravity,
                "Disruptor aimGravity")
            requireExact(gravity.x, 0, "Disruptor aimGravity.x")
            requireExact(gravity.y, -1, "Disruptor aimGravity.y")
            requireExact(gravity.z, 0, "Disruptor aimGravity.z")
        end
