        local footprint = requireTable(tp.footprint, "footprint")
        local skirt = requireTable(tp.skirtSize, "skirtSize")
        local source = requireTable(tp.additions.faSourceContract, "additions.faSourceContract")
        local expectedMapping = tpId == "ugs2501" and "XRB0104 -> ugs2501" or "XRB0304 -> ugs3501"
        requireExact(source.mapping, expectedMapping, "Hive source mapping")
        local sourceOffset = requireTable(source.sourceSkirtOffset, "additions.faSourceContract.sourceSkirtOffset")
        requireExact(sourceOffset.x, -0.5, "Hive sourceSkirtOffset.x")
        requireExact(sourceOffset.z, -0.5, "Hive sourceSkirtOffset.z")
        requireAllowed(source.sanctuarySkirtOffsetSupported, { false, true },
            "Hive sanctuarySkirtOffsetSupported")
        requireExact(footprint.x, 1, "Hive footprint.x")
        requireExact(footprint.y, 1, "Hive footprint.y")
        requireExact(skirt.x, 2, "Hive skirtSize.x")
        requireExact(skirt.y, 2, "Hive skirtSize.y")
        if tp.additions.scoFieldFixHivePlacement ~= nil then
            fail("additions.scoFieldFixHivePlacement is already owned without this module marker")
        end
        tp.additions.scoFieldFixHivePlacement = {
            version = "1.0.0",
            owner = "SCO_FieldFixHivePlacementRuntime",
            offset = { x = -0.5, z = -0.5 },
        }
        source.sanctuarySkirtOffsetSupported = true
    end

    tp.additions.scoFieldFixCybran = version
    return tp
end

-- SCOM Field Fixes 1.0.0 - Aeon and Seraphim template layer.
-- Runtime lifecycle consumers are deliberately represented as additions contracts.
function SCO_FieldFixAeonSeraphim(tp, tpId)
    local version = "1.0.0"
    local markerName = "scoFieldFixAeonSeraphim"

    if tpId == nil and type(tp) == "table" and type(tp.general) == "table" then
        tpId = tp.general.tpId
    end

    local factorySpecs = {
        ucs1511 = { tech = 1, domain = "LAND", role = "LAND_FACTORY", upgrade = "ucs2511" },
        ucs2511 = { tech = 2, domain = "LAND", role = "LAND_FACTORY", upgrade = "ucs3511", directT3EngineerBuild = true },
        ucs3511 = { tech = 3, domain = "LAND", role = "LAND_FACTORY", directT3EngineerBuild = true },
        ucs1512 = { tech = 1, domain = "AIR", role = "AIR_FACTORY", upgrade = "ucs2512" },
        ucs2512 = { tech = 2, domain = "AIR", role = "AIR_FACTORY", upgrade = "ucs3512", directT3EngineerBuild = true },
        ucs3512 = { tech = 3, domain = "AIR", role = "AIR_FACTORY", directT3EngineerBuild = true },
        ucs1513 = { tech = 1, domain = "NAVAL", role = "NAVAL_FACTORY", upgrade = "ucs2513" },
        ucs2513 = { tech = 2, domain = "NAVAL", role = "NAVAL_FACTORY", upgrade = "ucs3513", directT3EngineerBuild = true },
        ucs3513 = { tech = 3, domain = "NAVAL", role = "NAVAL_FACTORY", directT3EngineerBuild = true },
    }
    local structureUpgrades = {
        ucs1601 = "ucs2601",
        ucs2601 = "ucs3601",
        ucs3601 = false,
        ucs1701 = "ucs2701",
        ucs2701 = "ucs3701",
        ucs3701 = false,
        ucs1702 = "ucs2702",
        ucs2702 = "ucl3701",
    }

    local targets = {
        ucs3001 = true, ucs3101 = true, ucl4005 = true, ucs4102 = true,
        ucl4003 = true, ucl4004 = true, ucl1701 = true, ucl1001 = true,
        ucl2201 = true, ucl2806 = true, ucs2510 = true, ucs2101 = true,
        ucs2001 = true, ucs3201 = true, ucl2002 = true, ucs1201 = true,
        ucs2401 = true, ucs3401 = true,
        usl0000 = true, usa4011 = true, usl4004 = true,
        uss2510 = true, uss2401 = true, uss3401 = true, uss1513 = true,
        uss2513 = true, uss3513 = true, uss1602 = true, uss1612 = true,
    }
    for id in pairs(factorySpecs) do targets[id] = true end
    for id in pairs(structureUpgrades) do targets[id] = true end
    if not targets[tpId] then return end

    local function fail(message)
        error("SCOM Field Fixes " .. version .. " " .. tostring(tpId)
            .. ": " .. message, 2)
    end

    local function needTable(value, path)
        if type(value) ~= "table" then fail(path .. " must be a table") end
        return value
    end

    local function needString(value, path)
        if type(value) ~= "string" or value == "" then
            fail(path .. " must be a non-empty string")
        end
        return value
    end

    local function needNumber(value, path)
        if type(value) ~= "number" then fail(path .. " must be a number") end
        return value
    end

    local function hasTag(tags, wanted)
        for _, tag in ipairs(tags) do
            if tag == wanted then return true end
        end
        return false
    end

    local function requireTag(tags, wanted)
        if not hasTag(tags, wanted) then
            fail("tags is missing required tag " .. wanted)
        end
    end

    local function addTag(tags, wanted)
        if not hasTag(tags, wanted) then table.insert(tags, wanted) end
    end

    local function getWeapon(index)
        local weapons = needTable(tp.weapons, "weapons")
        return needTable(weapons[index], "weapons[" .. index .. "]")
    end

    local function getRig(index)
        local path = "weapons[" .. index .. "]"
        local weapon = getWeapon(index)
        local controllers = needTable(weapon.aimControllers,
            path .. ".aimControllers")
        local aim = needTable(controllers[1], path .. ".aimControllers[1]")
        needString(aim.aimBone, path .. ".aimControllers[1].aimBone")
        needString(aim.yawBone, path .. ".aimControllers[1].yawBone")
        needString(aim.pitchBone, path .. ".aimControllers[1].pitchBone")

        local groups = needTable(weapon.muzzleGroups, path .. ".muzzleGroups")
        if #groups == 0 then fail(path .. ".muzzleGroups is empty") end
        for groupIndex, group in ipairs(groups) do
            group = needTable(group, path .. ".muzzleGroups[" .. groupIndex .. "]")
            local bones = needTable(group.muzzles,
                path .. ".muzzleGroups[" .. groupIndex .. "].muzzles")
            if #bones == 0 then
                fail(path .. ".muzzleGroups[" .. groupIndex .. "].muzzles is empty")
            end
            for muzzleIndex, bone in ipairs(bones) do
                needString(bone, path .. ".muzzleGroups[" .. groupIndex
                    .. "].muzzles[" .. muzzleIndex .. "]")
            end
        end
        local muzzles = needTable(weapon.muzzles, path .. ".muzzles")
        for groupIndex, group in ipairs(groups) do
            for muzzleIndex, bone in ipairs(group.muzzles) do
                local muzzle = muzzles[bone]
                if muzzle ~= nil and type(muzzle) ~= "table" then
                    fail(path .. ".muzzles[" .. bone .. "] for group "
                        .. groupIndex .. ", muzzle " .. muzzleIndex
                        .. " must be nil or a table")
                end
            end
        end
        return {
            weapon = weapon,
            aim = aim,
            groups = groups,
            muzzles = muzzles,
            path = path,
        }
    end

    local function normalizeRig(rig)
        for _, group in ipairs(rig.groups) do
            for _, bone in ipairs(group.muzzles) do
                local muzzle = rig.muzzles[bone]
                if muzzle == nil then
                    muzzle = {}
                    rig.muzzles[bone] = muzzle
                elseif type(muzzle) ~= "table" then
                    fail(rig.path .. ".muzzles[" .. bone .. "] must be a table")
                end
                muzzle.aimController = rig.aim.aimBone
            end
        end
    end

    local function requireAnimation(key, clipName)
        local visuals = needTable(tp.visuals, "visuals")
        local animations = needTable(visuals.animations, "visuals.animations")
        local animation = needTable(animations[key],
            "visuals.animations." .. key)
        if clipName and animation.clipName ~= clipName then
            fail("visuals.animations." .. key .. ".clipName must be " .. clipName)
        end
        return animations, animation
    end

    local function moveLoopAnimation(sourceClip, destinationKey)
        local animations, active = requireAnimation("walk", sourceClip)
        local rest = needTable(animations.source_rest,
            "visuals.animations.source_rest")
        if rest.clipName ~= "Rest" then
            fail("visuals.animations.source_rest.clipName must be Rest")
        end
        if animations[destinationKey] ~= nil then
            fail("visuals.animations." .. destinationKey .. " is already owned")
        end
        active.playbackMode = 0
        animations[destinationKey] = active
        animations.walk = rest
        animations.source_rest = nil
        return active, rest
    end

    local general = needTable(tp, "template")
    general = needTable(general.general, "general")
    if general.tpId ~= tpId then
        fail("general.tpId identity mismatch")
    end
    local additions = needTable(tp.additions, "additions")
    local existingMarker = additions[markerName]
    if existingMarker == version then return end
    if existingMarker ~= nil then
        fail("unsupported existing " .. markerName .. " marker")
    end

    local function getShieldGeneratorCore(faction)
        local defence = needTable(tp.defence, "defence")
        local shields = needTable(defence.shields, "defence.shields")
        if #shields ~= 1 then
            fail("defence.shields must contain exactly one shield")
        end
        local shield = needTable(shields[1], "defence.shields[1]")
        local effects = needTable(shield.effectsPersistent,
            "defence.shields[1].effectsPersistent")
        if #effects ~= 1 then
            fail("shield effectsPersistent must contain exactly one effect")
        end
        local effect = needTable(effects[1],
            "defence.shields[1].effectsPersistent[1]")
        if effect.boneName ~= "Root" then
            fail("shield generator effect bone must be Root")
        end
        if effect.positionOffset ~= nil then
            fail("shield generator effect position offset preimage drifted")
        end
        local tier = (tpId == "ucs2401" or tpId == "uss2401") and 2 or 3
        local source = tier == 2
            and "VFX/Unit/vcu1222_active_shield_generator.sanvfx"
            or "VFX/Unit/vcu1221_active_shield_generator.sanvfx"
        if effect.particleName ~= source then
            fail("shield generator effect preimage drifted")
        end
        local replacement = "VFX/SCOM/FieldFixes/Shields/" .. faction
            .. "_core_t" .. tier .. ".sanvfx"
        return effect, source, replacement, tier
    end

    local function routeShieldGeneratorCore(
        faction, effect, source, replacement, tier, positionOffset)
        effect.particleName = replacement
        if positionOffset then
            effect.positionOffset = {
                x = positionOffset.x,
                y = positionOffset.y,
                z = positionOffset.z,
            }
        end
        additions.scoFieldFixShieldGeneratorPalette = {
            version = version,
            faction = faction,
            tier = tier,
            sourceEffect = source,
            effect = replacement,
            positionOffset = positionOffset and {
                x = positionOffset.x,
                y = positionOffset.y,
                z = positionOffset.z,
            } or nil,
        }
    end

    if tpId == "ucs3001" or tpId == "ucs3101" then
        local rig = getRig(1)
        if rig.aim.solverType ~= "HighArc" then
            fail(rig.path .. ".aimControllers[1].solverType must be HighArc")
        end
        if tpId == "ucs3101" then
            local weapon = rig.weapon
            local aim = rig.aim
            if weapon.projectileTemplate ~= "pai311"
                or needNumber(weapon.rangeMin, rig.path .. ".rangeMin") ~= 150
                or needNumber(weapon.rangeMax, rig.path .. ".rangeMax") ~= 900
                or needNumber(weapon.reloadTime, rig.path .. ".reloadTime") ~= 20
                or needNumber(aim.defaultPitchAdjustment,
                    rig.path .. ".aimControllers[1].defaultPitchAdjustment") ~= 30
                or needNumber(aim.pitchMin,
                    rig.path .. ".aimControllers[1].pitchMin") ~= -15
                or needNumber(aim.pitchMax,
                    rig.path .. ".aimControllers[1].pitchMax") ~= 75
                or needNumber(aim.projectileSpeed,
                    rig.path .. ".aimControllers[1].projectileSpeed") ~= 65
            then
                fail("Emissary artillery source contract drifted")
            end
        end

        rig.aim.aimGravity = { x = 0, y = -4.9, z = 0 }
        rig.aim.reduceMuzzleVelocityToTarget = true
        if tpId == "ucs3101" then
            local aim = rig.aim
            aim.pitchMax = 85
            aim.projectileSpeed = 67
            additions.scoFieldFixEmissaryArtillery = {
                version = version,
                rangeMin = 150,
                rangeMax = 900,
                pitchMax = 85,
                projectileSpeed = 67,
                creativeSpawnStartsReady = true,
            }
        end

    elseif tpId == "ucl4005" then
        local weapons = needTable(tp.weapons, "weapons")
        if #weapons ~= 2 or weapons[3] ~= nil then
            fail("weapons must contain exactly the two supported Torrent rigs")
        end
        local unsupported = needTable(additions.seaParityUnsupported,
            "additions.seaParityUnsupported")
        if unsupported.projectileInterception ~= true then
            fail("Sea Parity projectile-interception removal is missing")
        end
        local front = getRig(1)
        local back = getRig(2)
        if front.weapon.scoSourceLabel ~= "MissileRackFront"
            or back.weapon.scoSourceLabel ~= "MissileRackBack"
        then
            fail("supported Torrent weapon labels drifted")
        end
        needString(front.weapon.projectileTemplate,
            front.path .. ".projectileTemplate")
        needString(back.weapon.projectileTemplate,
            back.path .. ".projectileTemplate")
        if front.aim.aimBone ~= "Turret_Front_Muzzle02"
            or back.aim.aimBone ~= "Turret_Back_Muzzle02"
        then
            fail("missile aim-bone layout drifted")
        end
        for _, rig in ipairs({ front, back }) do
            normalizeRig(rig)
            rig.weapon.projectileTemplate = "paa341"
            rig.aim.solverType = "NoArc"
            rig.aim.leadTarget = true
            rig.aim.projectileSpeed = 25
            rig.aim.aimGravity = { x = 0, y = 0, z = 0 }
            rig.aim.reduceMuzzleVelocityToTarget = false
        end
        additions.scoFieldFixTorrentMissiles = {
            version = version,
            projectileTemplate = "paa341",
            isolatedExistingProjectile = true,
            homing = true,
            colour = "Aeon green",
            combatWeaponCount = 2,
        }

    elseif tpId == "ucs4102" then
        local economy = needTable(tp.economy, "economy")
        local production = economy.production
        if production ~= nil and type(production) ~= "table" then
            fail("economy.production must be nil or a table")
        end
        production = production or {}
        if production.alloys ~= nil and type(production.alloys) ~= "number" then
            fail("economy.production.alloys must be nil or a number")
        end
        if production.energy ~= nil and type(production.energy) ~= "number" then
            fail("economy.production.energy must be nil or a number")
        end
        economy.production = production
        -- XAB1401 begins at its source baseline. The host updates this
        -- generation entity from actual army demand every half second.
        if production.alloys ~= nil and production.alloys ~= 20
            and production.alloys ~= 10000 then
            fail("Paragon alloy generation contract changed")
        end
        if production.energy ~= nil and production.energy ~= 1000
            and production.energy ~= 1000000 then
            fail("Paragon energy generation contract changed")
        end
        production.alloys = 20
        production.energy = 1000
        additions.scoFieldFixParagonEconomy = {
            version = version,
            sourceId = "XAB1401",
            sampleSeconds = 0.5,
            baselineAlloysPerSecond = 20,
            baselineEnergyPerSecond = 1000,
            maxAlloysPerSecond = 10000,
            maxEnergyPerSecond = 1000000,
        }
        -- XAB1401's zero direct damage is carried by AIFQuantumWarhead02's
        -- two immediate nuclear rings, not by an ordinary death projectile.
        additions.scoFieldFixParagonDeath = {
            sourceId = "XAB1401",
            sourceBlueprintSha256 = "8002739b4c792f498d8dc4ed779f26bfdffe2c748e629163170158d0a66222b9",
            damageFriendly = true,
            rings = {
                { damage = 35000, radius = 25 },
                { damage = 35000, radius = 25 },
            },
        }

    elseif tpId == "ucl4003" then
        local weapons = needTable(tp.weapons, "weapons")
        if #weapons ~= 2 or weapons[3] ~= nil then
            fail("weapons must contain exactly the two supported Tempest rigs")
        end
        local unsupported = needTable(additions.seaParityUnsupported,
            "additions.seaParityUnsupported")
        if unsupported.projectileInterception ~= true then
            fail("Sea Parity projectile-interception removal is missing")
        end
        local rigs = { getRig(1), getRig(2) }
        if rigs[1].weapon.scoSourceLabel ~= "MainGun"
            or rigs[2].weapon.scoSourceLabel ~= "Torpedo01"
        then
            fail("supported Tempest weapon labels drifted")
        end
        local _, open = requireAnimation("source_animaopen01", "AnimAopen01")
        for _, rig in ipairs(rigs) do normalizeRig(rig) end
        open.playbackMode = 0
        additions.scoFieldFixTempest = {
            version = version,
            openAnimationKey = "source_animaopen01",
            restAnimationKey = "walk",
            combatWeaponCount = 2,
            runtimeLifecycleRequired = true,
        }

    elseif tpId == "ucl4004" then
        local _, death = requireAnimation(
            "source_animadeath01",
            "AnimAdeath01")
        if type(SCO_FieldFixGalacticColossusEye) ~= "function" then
            fail("isolated Galactic Colossus eye policy is unavailable")
        end
        SCO_FieldFixGalacticColossusEye(tp, tpId)
        death.playbackMode = 0
        additions.scoFieldFixColossusDeath = {
            version = version,
            animationKey = "source_animadeath01",
            playbackMode = "Clamp",
            cosmeticBoneFailureIsNonFatal = true,
        }

    elseif tpId == "ucl1701" or tpId == "ucl1001"
        or tpId == "ucl2201" or tpId == "ucl2806"
    then
        local movement = needTable(tp.movement, "movement")
        local speed = needNumber(movement.speed, "movement.speed")
        if speed <= 0 then fail("movement.speed must be positive") end
        local weapon = getWeapon(1)
        local range = needNumber(weapon.rangeMax, "weapons[1].rangeMax")
        if range <= 1 then fail("weapons[1].rangeMax must exceed one") end
        local orbitRange = math.min(range * 0.7, range - 1)
        local usesNativeBodyFacing = tpId == "ucl1001" or tpId == "ucl2806"
        if tpId == "ucl1001" then
            local rig = getRig(1)
            local controllers = rig.weapon.aimControllers
            local group = rig.groups[1]
            local sourceMuzzle = rig.muzzles.Turret_Barrel
            if #tp.weapons ~= 1 or tp.weapons[2] ~= nil
                or #controllers ~= 1 or controllers[2] ~= nil
                or #rig.groups ~= 1 or rig.groups[2] ~= nil
                or #group.muzzles ~= 1
                or group.muzzles[1] ~= "Turret_Barrel"
                or type(sourceMuzzle) ~= "table"
                or sourceMuzzle.aimController ~= "Turret_Barrel"
                or rig.muzzles.Turret_Muzzle ~= nil
                or rig.aim.aimBone ~= "Turret_Barrel"
                or rig.aim.yawBone ~= "Turret"
                or rig.aim.pitchBone ~= "Turret_Barrel"
                or needNumber(rig.aim.yawMin,
                    rig.path .. ".aimControllers[1].yawMin") ~= -10
                or needNumber(rig.aim.yawMax,
                    rig.path .. ".aimControllers[1].yawMax") ~= 10
                or needNumber(rig.aim.yawSpeed,
                    rig.path .. ".aimControllers[1].yawSpeed") ~= 60
                or needNumber(rig.aim.pitchMin,
                    rig.path .. ".aimControllers[1].pitchMin") ~= -20
                or needNumber(rig.aim.pitchMax,
                    rig.path .. ".aimControllers[1].pitchMax") ~= 20
                or needNumber(rig.aim.pitchSpeed,
                    rig.path .. ".aimControllers[1].pitchSpeed") ~= 60
            then
                fail("Aurora turret and muzzle source contract drifted")
            end
            rig.aim.aimBone = "Turret_Muzzle"
            rig.aim.yawMin = -180
            rig.aim.yawMax = 180
            group.muzzles[1] = "Turret_Muzzle"
            rig.muzzles.Turret_Barrel = nil
            rig.muzzles.Turret_Muzzle = sourceMuzzle
            sourceMuzzle.aimController = "Turret_Muzzle"
            additions.scoFieldFixAuroraTurret = {
                version = version,
                aimBone = "Turret_Muzzle",
                yawBone = "Turret",
                pitchBone = "Turret_Barrel",
                yawMin = -180,
                yawMax = 180,
                muzzleBone = "Turret_Muzzle",
                independentTargetTracking = true,
            }
        end
        movement.orbitRange = orbitRange
        movement.orbitSpeed = speed
        -- Circle preserves the predecessor's fixed tangent and continuous speed.
        -- Only Aurora/Blaze use the scoped native center-facing extension.
        movement.patterns = movement.patterns or {}
        movement.patterns.scomHoverOrbit = {
            mode = "Circle",
            circle = { radius = orbitRange, speed = speed },
            orbit = {
                facing = usesNativeBodyFacing and "center" or "travel",
                maxSpeed = speed,
            },
        }
        movement.patternBySituation = movement.patternBySituation or {}
        movement.patternBySituation.attack = "scomHoverOrbit"
        additions.scoFieldFixHoverStrafe = {
            version = version,
            orbitRange = orbitRange,
            orbitSpeed = speed,
            preserveWeaponAimWhileMoving = true,
            runtimeGroundHoverOrderConsumerRequired = true,
            targetBodyFacingWhileOrbiting = usesNativeBodyFacing,
            nativeFacingMarkerMask = usesNativeBodyFacing and 1073741824 or nil,
            faceTurnRateMultiplier = usesNativeBodyFacing and (4 / 3) or nil,
            runtimeNativeStrafeChassisPatchRequired = usesNativeBodyFacing,
        }

    elseif tpId == "ucs2510" then
        local construction = needTable(tp.construction, "construction")
        local points = needTable(construction.rollOffPoints,
            "construction.rollOffPoints")
        local front = needTable(points[1], "construction.rollOffPoints[1]")
        local back = needTable(points[2], "construction.rollOffPoints[2]")
        local frontOffset = needTable(front.offset,
            "construction.rollOffPoints[1].offset")
        local backOffset = needTable(back.offset,
            "construction.rollOffPoints[2].offset")
        frontOffset.x, frontOffset.y, frontOffset.z = 0, 0, 3
        backOffset.x, backOffset.y, backOffset.z = 0, 0, -3
        front.unitSpin, back.unitSpin = 0, 180

    elseif tpId == "ucs2101" or tpId == "ucs2001" then
        local rig = getRig(1)
        local aim = rig.aim
        local pitch = needNumber(aim.defaultPitchAdjustment,
            rig.path .. ".aimControllers[1].defaultPitchAdjustment")
        local pitchMin = needNumber(aim.pitchMin,
            rig.path .. ".aimControllers[1].pitchMin")
        local pitchMax = needNumber(aim.pitchMax,
            rig.path .. ".aimControllers[1].pitchMax")
        local halfRange = (pitchMax - pitchMin) / 2
        if halfRange <= 0 then fail("idle pitch range is invalid") end
        local correctedPitch = -math.abs(pitch)
        if correctedPitch == 0 then correctedPitch = tpId == "ucs2101" and -30 or -10 end
        aim.defaultPitchAdjustment = correctedPitch
        aim.pitchMin = correctedPitch - halfRange
        aim.pitchMax = correctedPitch + halfRange
        aim.poseResetTime = 3
        additions.scoFieldFixIdlePitch = {
            version = version,
            defaultPitchAdjustment = correctedPitch,
            poseResetTime = 3,
        }

    elseif tpId == "ucs3201" then
        local rig = getRig(1)
        if rig.aim.aimBone ~= "Turret_Muzzle01" then
            fail("anti-air aim bone must be Turret_Muzzle01")
        end
        normalizeRig(rig)
        rig.weapon.projectileTemplate = "paa341"
        rig.aim.solverType = "NoArc"
        rig.aim.leadTarget = true
        rig.aim.projectileSpeed = 30
        rig.aim.aimGravity = { x = 0, y = 0, z = 0 }
        rig.aim.reduceMuzzleVelocityToTarget = false
        additions.scoFieldFixTranscender = {
            version = version,
            projectileTemplate = "paa341",
            isolatedExistingProjectile = true,
            homing = true,
        }

    elseif tpId == "ucl2002" then
        local defence = needTable(tp.defence, "defence")
        local shields = needTable(defence.shields, "defence.shields")
        local shield = needTable(shields[1], "defence.shields[1]")
        local radii = needTable(shield.radii, "defence.shields[1].radii")
        local x = needNumber(radii.x, "defence.shields[1].radii.x")
        local y = needNumber(radii.y, "defence.shields[1].radii.y")
        local z = needNumber(radii.z, "defence.shields[1].radii.z")
        local economy = needTable(tp.economy, "economy")
        local maintenance = economy.maintenanceConsumption
        if maintenance ~= nil and type(maintenance) ~= "table" then
            fail("economy.maintenanceConsumption must be nil or a table")
        end
        maintenance = maintenance or {}
        if maintenance.energy ~= nil and type(maintenance.energy) ~= "number" then
            fail("economy.maintenanceConsumption.energy must be nil or a number")
        end
        local radius = math.min(x, y, z, 1.25)
        radii.x, radii.y, radii.z = radius, radius, radius
        economy.maintenanceConsumption = maintenance
        maintenance.energy = math.max(maintenance.energy or 0, 10)
        additions.scoFieldFixObsidianShield = {
            version = version,
            radius = radius,
