            or aim.yawBone ~= "Turret"
            or aim.pitchBone ~= "Turret_Barrel"
        then
            fail("Seeker aim-bone layout drifted")
        end
        normalizeRig(rig)
        local pitch = needNumber(aim.defaultPitchAdjustment,
            rig.path .. ".aimControllers[1].defaultPitchAdjustment")
        local pitchMin = needNumber(aim.pitchMin,
            rig.path .. ".aimControllers[1].pitchMin")
        local pitchMax = needNumber(aim.pitchMax,
            rig.path .. ".aimControllers[1].pitchMax")
        local halfRange = (pitchMax - pitchMin) / 2
        if halfRange <= 0 then fail("Seeker idle pitch range is invalid") end
        local correctedPitch = -math.abs(pitch)
        if correctedPitch == 0 then correctedPitch = -45 end
        aim.defaultPitchAdjustment = correctedPitch
        aim.pitchMin = correctedPitch - halfRange
        aim.pitchMax = correctedPitch + halfRange
        aim.poseResetTime = 3
        aim.solverType = "NoArc"
        aim.leadTarget = true
        aim.aimGravity = { x = 0, y = 0, z = 0 }
        aim.reduceMuzzleVelocityToTarget = false
        additions.scoFieldFixIdlePitch = {
            version = version,
            defaultPitchAdjustment = correctedPitch,
            poseResetTime = 3,
        }

