        local spec = factorySpecs[tpId]
        local tags = needTable(tp.tags, "tags")
        local construction = needTable(tp.construction, "construction")
        requireTag(tags, "CHOSEN")
        requireTag(tags, "FACTORY")
        requireTag(tags, "STRUCTURE")
        requireTag(tags, "TECH" .. spec.tech)
        requireTag(tags, spec.domain)

        local broken = "Tags.CHOSEN * Tags.BUILDABLE_BY_T" .. spec.tech
            .. "_FACTORY * Tags." .. spec.domain
        local domainFilter
        if spec.domain == "AIR" then
            domainFilter = "((Tags.AIR * Tags.MOBILE) + Tags.AIR_FACTORY + Tags.ENGINEER)"
        elseif spec.domain == "NAVAL" then
            domainFilter = "((Tags.NAVAL * Tags.MOBILE) + Tags.NAVAL_FACTORY)"
        else
            domainFilter = "((Tags.LAND * Tags.MOBILE) + Tags.LAND_FACTORY)"
        end
        local repaired = "Tags.CHOSEN * Tags.BUILDABLE_BY_T" .. spec.tech
            .. "_FACTORY * " .. domainFilter
        if construction.canBuild ~= broken and construction.canBuild ~= repaired then
            fail("construction.canBuild drifted from the reviewed Aeon factory domain")
        end
        if construction.upgradesTo ~= spec.upgrade then
            fail("construction.upgradesTo drifted from the reviewed Aeon factory chain")
        end

        addTag(tags, spec.role)
        if spec.directT3EngineerBuild then
            addTag(tags, "BUILDABLE_BY_T3_ENGINEER")
        end
        construction.canBuild = repaired
        construction.upgradesTo = spec.upgrade
        additions.scoFieldFixAeonFactoryRouting = {
            version = version,
            role = spec.role,
            upgrade = spec.upgrade,
