        for index, rotator in ipairs(rotators) do
            rotator = needTable(rotator, "additions.rotators[" .. index .. "]")
            local bone = needString(rotator.boneName,
                "additions.rotators[" .. index .. "].boneName")
            if bone == upperBone or bone == lowerBone then
                if clawRotators[bone] then
