        end
        if animations.source_animopen ~= nil then
            fail("visuals.animations.source_animopen is already owned")
        end
        if animations.source_animstoragelevel ~= nil then
            fail("visuals.animations.source_animstoragelevel is already owned")
        end
        local _, rest = moveLoopAnimation("AnimOpen", "source_animopen")
        if rest ~= sourceRest then
            fail("Rest animation identity changed during storage routing")
        end
        animations.source_animstoragelevel = {
            clipName = "AnimStorageLevel",
            sanAnimationPath = animationPath,
            playbackMode = 0,
        }
        local resource = tpId == "uss1602" and "alloys" or "energy"
        local sourceMinimumZ = tpId == "uss1602" and -0.75 or -0.7
        local emptyLocalZ = tpId == "uss1602"
            and -0.2193426 or -0.0461830707
        local fullLocalZ = tpId == "uss1602"
            and -0.1818426 or -0.0006830707
        additions.scoFieldFixStorageRatio = {
            version = version,
            animationKey = "source_animstoragelevel",
            restAnimationKey = "walk",
            resource = resource,
            durationSeconds = 1,
            emptySampleSeconds = 0,
            fullSampleSeconds = 1,
            sourceMinimumZ = sourceMinimumZ,
            sourceMaximumZ = 0,
            emptyLocalZ = emptyLocalZ,
            fullLocalZ = fullLocalZ,
            runtimeStorageRatioConsumerRequired = false,
        }
    else
        fail("target dispatch is incomplete")
    end

    additions[markerName] = version
end

-- SCOM Field Fix: exact prefab-validation completion 1.0.1
-- uen2001 front yaw migration: 1.0.2
--
-- This policy is intentionally narrow. Every owned template is checked against
-- its reviewed, fully composed input shape before any field is changed.

local SCO_PREFAB_COMPLETION_VERSION = "1.0.1"
local SCO_PREFAB_COMPLETION_MARKER = "scoFieldFixPrefabCompletion"

local SCO_PREFAB_COMPLETION_TARGETS = {
    uca1201 = true,
    uca3201 = true,
    uca4011 = true,
    uea4001 = true,
    uen1001 = true,
    uen1002 = true,
    uen2001 = true,
    uen2002 = true,
    uen3004 = true,
    uga4001 = true,
    uga4801 = true,
    ugn3004 = true,
    ugs2807 = true,
    ups2001 = true,
}

local function completionVersion(tpId)
    return tpId == "uen2001" and "1.0.2" or SCO_PREFAB_COMPLETION_VERSION
end

local function fail(tpId, message)
    error("SCOM prefab completion " .. completionVersion(tpId)
        .. ": " .. tpId .. ": " .. message, 3)
end

local function needTable(tpId, value, path)
    if type(value) ~= "table" then fail(tpId, path .. " must be a table") end
    return value
end

local function needArray(tpId, value, path, length)
    value = needTable(tpId, value, path)
    if #value ~= length then
        fail(tpId, path .. " must contain exactly " .. length .. " entries")
    end
    return value
end

local function expect(tpId, actual, expected, path)
    if actual ~= expected then
        fail(tpId, path .. " drifted from the reviewed composed template")
    end
end

local function countKeys(value)
    local count = 0
    for _ in pairs(value) do count = count + 1 end
    return count
end

local function hasExactTags(tags, expected)
    if type(tags) ~= "table" or #tags ~= #expected then return false end
    for index, tag in ipairs(expected) do
        if tags[index] ~= tag then return false end
    end
    return true
end

