local function seaPlan(tp, tpId, state)
    local spec = SEA_SPECS[tpId]
    local weapons = needArray(tpId, tp.weapons, "weapons", #spec)
    local changes = {}
    for weaponIndex, weaponSpec in ipairs(spec) do
        local weaponPath = "weapons[" .. weaponIndex .. "]"
        local weapon = needTable(tpId, weapons[weaponIndex], weaponPath)
        expect(tpId, weapon.name, weaponSpec[1], weaponPath .. ".name")
        local controllerSpecs = weaponSpec[2]
        local controllers = needArray(tpId, weapon.aimControllers,
            weaponPath .. ".aimControllers", #controllerSpecs)
        for controllerIndex, controllerSpec in ipairs(controllerSpecs) do
            local path = weaponPath .. ".aimControllers[" .. controllerIndex .. "]"
            local controller = needTable(tpId, controllers[controllerIndex], path)
            -- false is an explicit request to leave shared yaw to one controller.
            local desiredYaw = controllerSpec[4]
            if desiredYaw == nil then
                desiredYaw = controllerSpec[2]
            elseif desiredYaw == false then
                desiredYaw = nil
            end
            local desiredPitch = controllerSpec[5] or controllerSpec[3]
            local expectedYaw = controllerSpec[2]
            local expectedPitch = controllerSpec[3]
            if state ~= "source" then
                expectedYaw = desiredYaw
                expectedPitch = desiredPitch
                if state == "legacy" and controllerSpec[4] == false then
                    expectedYaw = controllerSpec[2]
                end
            end
            expect(tpId, controller.aimBone, controllerSpec[1], path .. ".aimBone")
            expect(tpId, controller.yawBone, expectedYaw, path .. ".yawBone")
            expect(tpId, controller.pitchBone, expectedPitch, path .. ".pitchBone")
            if controllerSpec[4] ~= nil or controllerSpec[5] ~= nil then
                changes[#changes + 1] = {
                    controller = controller,
                    yawBone = desiredYaw,
                    pitchBone = desiredPitch,
                }
            end
        end
    end
    return function()
        for _, change in ipairs(changes) do
            change.controller.yawBone = change.yawBone
            change.controller.pitchBone = change.pitchBone
        end
    end
end

local function tolerancePlan(tp, tpId, applied)
    local specs = tpId == "uca1201"
        and {
            { "SonicPulseBattery1", "Turret_Muzzle_Right" },
            { "SonicPulseBattery2", "Turret_Muzzle_Left" },
        }
        or { { "AutoCannon1", "Muzzle" } }
    local weapons = needArray(tpId, tp.weapons, "weapons", #specs + 1)
    local projectile = tpId == "uca1201" and "paa111" or "paa311"
    local changes = {}
    for index, spec in ipairs(specs) do
        local path = "weapons[" .. index .. "]"
        local weapon = needTable(tpId, weapons[index], path)
        expect(tpId, weapon.scoSourceLabel, spec[1], path .. ".scoSourceLabel")
        expect(tpId, weapon.projectileTemplate, projectile, path .. ".projectileTemplate")
        local controllers = needArray(tpId, weapon.aimControllers,
            path .. ".aimControllers", 1)
        local controller = needTable(tpId, controllers[1], path .. ".aimControllers[1]")
        expect(tpId, controller.aimBone, spec[2], path .. ".aimControllers[1].aimBone")
        expect(tpId, controller.yawBone, spec[2], path .. ".aimControllers[1].yawBone")
        expect(tpId, controller.pitchBone, spec[2], path .. ".aimControllers[1].pitchBone")
        expect(tpId, controller.projectileSpeed, 120,
            path .. ".aimControllers[1].projectileSpeed")
        expect(tpId, controller.aimTolerance, applied and 0.1 or 0,
            path .. ".aimControllers[1].aimTolerance")
        changes[#changes + 1] = controller
    end
    local death = needTable(tpId, weapons[#weapons],
        "weapons[" .. #weapons .. "]")
    expect(tpId, death.category, "DeathExplosion",
        "weapons[" .. #weapons .. "].category")
    expect(tpId, death.damageFriendly, true,
        "weapons[" .. #weapons .. "].damageFriendly")
    return function()
        for _, controller in ipairs(changes) do controller.aimTolerance = 0.1 end
    end
end

