local function zeroSpeedPlan(tp, tpId, applied)
    local spec = ZERO_SPEED_SPECS[tpId]
    local weapons = needArray(tpId, tp.weapons, "weapons", spec.weaponCount)
    local changes = {}
    for _, controllerSpec in ipairs(spec.controllers) do
        local weaponIndex = controllerSpec[1]
        local weaponPath = "weapons[" .. weaponIndex .. "]"
        local weapon = needTable(tpId, weapons[weaponIndex], weaponPath)
        expect(tpId, weapon.scoSourceLabel, controllerSpec[2],
            weaponPath .. ".scoSourceLabel")
        expect(tpId, weapon.projectileTemplate, controllerSpec[3],
            weaponPath .. ".projectileTemplate")
        local controllers = needArray(tpId, weapon.aimControllers,
            weaponPath .. ".aimControllers", 1)
        local controllerPath = weaponPath .. ".aimControllers[1]"
        local controller = needTable(tpId, controllers[1], controllerPath)
        expect(tpId, controller.aimBone, controllerSpec[4],
            controllerPath .. ".aimBone")
        expect(tpId, controller.yawBone, controllerSpec[4],
            controllerPath .. ".yawBone")
        expect(tpId, controller.pitchBone, controllerSpec[4],
            controllerPath .. ".pitchBone")
        expect(tpId, controller.solverType, controllerSpec[5],
            controllerPath .. ".solverType")
        expect(tpId, controller.projectileSpeed,
            applied and controllerSpec[6] or controllerSpec[9],
            controllerPath .. ".projectileSpeed")
        local expectedLeadTarget = controllerSpec[10]
        if applied then expectedLeadTarget = controllerSpec[7] end
        expect(tpId, controller.leadTarget, expectedLeadTarget,
            controllerPath .. ".leadTarget")
        expect(tpId, controller.aimTolerance, controllerSpec[8],
            controllerPath .. ".aimTolerance")
        changes[#changes + 1] = {
            controller = controller,
            projectileSpeed = controllerSpec[6],
            leadTarget = controllerSpec[7],
        }
    end
    local death = needTable(tpId, weapons[#weapons],
        "weapons[" .. #weapons .. "]")
    expect(tpId, death.category, "DeathExplosion",
        "weapons[" .. #weapons .. "].category")
    return function()
        for _, change in ipairs(changes) do
            change.controller.projectileSpeed = change.projectileSpeed
            change.controller.leadTarget = change.leadTarget
        end
    end
end

