local function persistentRemovalPlan(tp, tpId, applied)
    local visuals = needTable(tpId, tp.visuals, "visuals")
    local source = tpId == "uga4001" and UGA4001_EFFECTS or {
        { "Effect01", "VFX/Unit/vcu4252_exhaust_hover_titan02.sanvfx" },
        { "Effect02", "VFX/Unit/vcu4252_exhaust_hover_titan02.sanvfx" },
        { "Effect03", "VFX/Unit/vcu4252_exhaust_hover_titan02.sanvfx" },
        { "Effect04", "VFX/Unit/vcu4252_exhaust_hover_titan02.sanvfx" },
    }
    local desiredStart = tpId == "uga4001" and 5 or (#source + 1)
    local desiredLength = #source - desiredStart + 1
    local expectedLength = applied and desiredLength or #source
    local effects = needArray(tpId, visuals.effectsPersistent,
        "visuals.effectsPersistent", expectedLength)
    local sourceOffset = applied and (desiredStart - 1) or 0
    for index, effect in ipairs(effects) do
        local expected = source[index + sourceOffset]
        local path = "visuals.effectsPersistent[" .. index .. "]"
        effect = needTable(tpId, effect, path)
        expect(tpId, effect.boneName, expected[1], path .. ".boneName")
        expect(tpId, effect.particleName, expected[2], path .. ".particleName")
    end
    return function()
        local retained = {}
        for sourceIndex = desiredStart, #source do
            retained[#retained + 1] = effects[sourceIndex]
        end
        visuals.effectsPersistent = retained
    end
end

local function ugs2807Plan(tp, tpId, applied)
    local expectedTags = {
        "BUILDABLE_BY_T2_ENGINEER", "BUILDABLE_BY_T3_ENGINEER", "DEMO_UI_ONLY",
        "GUARD", "STRUCTURE", "TECH2", "TRANSMITTER",
    }
    if not hasExactTags(tp.tags, expectedTags) then fail(tpId, "tags drifted") end
    local additions = needTable(tpId, tp.additions, "additions")
    local visuals = needTable(tpId, tp.visuals, "visuals")
    if applied then
        needArray(tpId, additions.rotators, "additions.rotators", 0)
        needArray(tpId, visuals.effectsPersistent, "visuals.effectsPersistent", 0)
    else
        local rotators = needArray(tpId, additions.rotators, "additions.rotators", 2)
        local rotatorSpecs = {
            { "Main_Rotator", 20 }, { "T1_Seperate_Rotator", -50 },
        }
        for index, spec in ipairs(rotatorSpecs) do
            local path = "additions.rotators[" .. index .. "]"
            local rotator = needTable(tpId, rotators[index], path)
            local speed = needTable(tpId, rotator.speed, path .. ".speed")
            expect(tpId, rotator.boneName, spec[1], path .. ".boneName")
            expect(tpId, speed.x, 0, path .. ".speed.x")
            expect(tpId, speed.y, spec[2], path .. ".speed.y")
            expect(tpId, speed.z, 0, path .. ".speed.z")
        end
        local effects = needArray(tpId, visuals.effectsPersistent,
            "visuals.effectsPersistent", 2)
        local effectSpecs = {
            { "T1_Seperate_Rotator", "VFX/Unit/vgu8022_active_transmitter.sanvfx" },
            { "T2_Seperate_Rotator", "VFX/Unit/vgu8024_active_transmitter.sanvfx" },
        }
        for index, spec in ipairs(effectSpecs) do
            local path = "visuals.effectsPersistent[" .. index .. "]"
            local effect = needTable(tpId, effects[index], path)
            expect(tpId, effect.boneName, spec[1], path .. ".boneName")
            expect(tpId, effect.particleName, spec[2], path .. ".particleName")
        end
    end
    return function()
        additions.rotators = {}
        visuals.effectsPersistent = {}
    end
end

