    local weapons = needArray(tpId, tp.weapons, "weapons", 1)
    local weapon = needTable(tpId, weapons[1], "weapons[1]")
    expect(tpId, weapon.projectileTemplate, "pcg201", "weapons[1].projectileTemplate")
    expect(tpId, weapon.beamLifetime, 6, "weapons[1].beamLifetime")
    local controllers = needArray(tpId, weapon.aimControllers,
        "weapons[1].aimControllers", 1)
    local controller = needTable(tpId, controllers[1], "weapons[1].aimControllers[1]")
    expect(tpId, controller.aimBone, "Turret01_Muzzle01", "weapons[1].aimControllers[1].aimBone")
    expect(tpId, controller.yawBone, "Turret01", "weapons[1].aimControllers[1].yawBone")
    expect(tpId, controller.pitchBone, "Turret01_Pitch01", "weapons[1].aimControllers[1].pitchBone")
    local beam = needTable(tpId, weapon.beam, "weapons[1].beam")
    local subMesh = needArray(tpId, beam.subMesh, "weapons[1].beam.subMesh", 2)
    for index, expected in ipairs(UPS_BEAM_SUBMESH) do
        local path = "weapons[1].beam.subMesh[" .. index .. "]"
        local entry = needTable(tpId, subMesh[index], path)
        expect(tpId, entry.model, expected[1], path .. ".model")
        expect(tpId, entry.material, expected[2], path .. ".material")
    end
    local groups = needArray(tpId, weapon.muzzleGroups,
        "weapons[1].muzzleGroups", applied and 1 or 3)
    local sourceGroups = { "Turret01_Muzzle01", "Turret_Muzzle02", "Turret_Muzzle03" }
    local sourceMuzzles = { "Turret_Muzzle01", "Turret_Muzzle02", "Turret_Muzzle03" }
    for index, group in ipairs(groups) do
        local path = "weapons[1].muzzleGroups[" .. index .. "].muzzles"
        local muzzles = needArray(tpId, needTable(tpId, group,
            "weapons[1].muzzleGroups[" .. index .. "]").muzzles, path, 1)
        expect(tpId, muzzles[1], applied and "Turret01_Muzzle01" or sourceGroups[index], path .. "[1]")
    end
    local muzzles = needTable(tpId, weapon.muzzles, "weapons[1].muzzles")
    expect(tpId, countKeys(muzzles), applied and 1 or 3, "weapons[1].muzzles key count")
    if applied then
        local muzzle = needTable(tpId, muzzles.Turret01_Muzzle01,
            "weapons[1].muzzles.Turret01_Muzzle01")
        expect(tpId, muzzle.aimController, "Turret01_Muzzle01",
            "weapons[1].muzzles.Turret01_Muzzle01.aimController")
    else
        for _, muzzleName in ipairs(sourceMuzzles) do
            local muzzle = needTable(tpId, muzzles[muzzleName],
                "weapons[1].muzzles." .. muzzleName)
            expect(tpId, muzzle.aimController, "Turret_Muzzle01",
                "weapons[1].muzzles." .. muzzleName .. ".aimController")
        end
    end
    return function()
        weapon.muzzleGroups = { { muzzles = { "Turret01_Muzzle01" } } }
        weapon.muzzles = {
            Turret01_Muzzle01 = { aimController = "Turret01_Muzzle01" },
        }
    end
end

local function ups2001Plan(tp, tpId, applied)
    local weapons = needArray(tpId, tp.weapons, "weapons", 1)
    local weapon = needTable(tpId, weapons[1], "weapons[1]")
    if weapon.projectileTemplate == "ppd211" then
        return ups2001PrometheanPlan(tp, tpId)
    end
    return ups2001LegacyScomPlan(tp, tpId, applied)
end

function SCO_FieldFixPrefabCompletion(tp, tpId)
    if tpId == nil and type(tp) == "table" and type(tp.general) == "table" then
        tpId = tp.general.tpId
    end
    if not SCO_PREFAB_COMPLETION_TARGETS[tpId] then return tp end

    tp = needTable(tpId, tp, "template")
    local general = needTable(tpId, tp.general, "general")
    expect(tpId, general.tpId, tpId, "general.tpId")
    if tp.additions ~= nil and type(tp.additions) ~= "table" then
        fail(tpId, "additions must be nil or a table")
    end
    local marker = tp.additions and tp.additions[SCO_PREFAB_COMPLETION_MARKER]
    local expectedVersion = completionVersion(tpId)
    if marker ~= nil and marker ~= expectedVersion
        and not (tpId == "uen2001" and marker == SCO_PREFAB_COMPLETION_VERSION)
    then
        fail(tpId, "unsupported existing completion marker")
    end
    local state = "source"
    if marker == expectedVersion then
        state = "final"
    elseif marker ~= nil then
        state = "legacy"
    end
    local applied = state ~= "source"
    local commit
    if SEA_SPECS[tpId] then
        commit = seaPlan(tp, tpId, state)
    elseif ZERO_SPEED_SPECS[tpId] then
        commit = zeroSpeedPlan(tp, tpId, applied)
    elseif tpId == "uca1201" or tpId == "uca3201" then
        commit = tolerancePlan(tp, tpId, applied)
    elseif tpId == "uea4001" then
        commit = uea4001Plan(tp, tpId, applied)
    elseif tpId == "uga4001" or tpId == "uga4801" then
        commit = persistentRemovalPlan(tp, tpId, applied)
    elseif tpId == "ugs2807" then
        commit = ugs2807Plan(tp, tpId, applied)
    elseif tpId == "ups2001" then
        commit = ups2001Plan(tp, tpId, applied)
    end

    if state == "final" then return tp end
    commit()
    tp.additions = tp.additions or {}
    tp.additions[SCO_PREFAB_COMPLETION_MARKER] = expectedVersion
    return tp
end

-- SCOM naval engineer buildability 1.0.0
-- Sea Parity supplies these factories; land and air factories already expose the same builder tiers.
local SCO_NavalEngineerBuildability = {
    ues3513 = { "EDA", "TECH3", "BUILDABLE_BY_T2_FACTORY", "UEB0303", "BUILDABLE_BY_T3_ENGINEER" },
    ugs3513 = { "GUARD", "TECH3", "BUILDABLE_BY_T2_FACTORY", "URB0303", "BUILDABLE_BY_T3_ENGINEER" },
}
local function SCO_GrantNavalEngineerBuildability(tp, tpId)
    local spec = SCO_NavalEngineerBuildability[tpId]
    if not spec then return false end
    local tags = assert(tp.tags, "SCOM naval factory tags missing: " .. tpId)
    local source = tp.additions and tp.additions.faSourceContract
    assert(type(tags) == "table" and source
        and source.sourceId == spec[4] and source.targetId == tpId
        and table.find(tags, spec[1]) and table.find(tags, spec[2])
        and table.find(tags, spec[3]) and table.find(tags, "NAVAL_FACTORY")
        and table.find(tags, "STRUCTURE"),
        "SCOM naval factory builder contract changed: " .. tpId)
    local added = false
    for index = 5, #spec do
        local tag = spec[index]
        if not table.find(tags, tag) then
            table.insert(tags, tag)
            added = true
        end
    end
    return added
end

-- The FA quantum gates supply roll-off points in Physics. Their ported
-- construction tables need those points for HostFactory's spawn and exit path.
local SCO_GatewayProduction = {
    ues5014 = {source = "UEB0304", hash = "d312a74e9a6bb153922726e4995e28aa8cd43a031569661ce740e7847d1f25df",
        class = "EDALandFactory", buildTag = "Tags.SCFA_BUILTBYQUANTUMGATE", exits = {3, -3}},
    ugs5002 = {source = "URB0304", hash = "47eaa42c5914f06f5121d0638bf83d4fcbfe6f4b44d8f043180bfa89dd5aeded",
        class = "GuardLandFactory", buildTag = "Tags.SCFA_BUILTBYQUANTUMGATE", exits = {-3, 3}},
    uss2510 = {class = "SeraphimLandFactory", buildTag = "Tags.usl4002", exits = {3}},
}

local function SCO_RestoreGatewayProduction(tp, tpId)
    local spec = SCO_GatewayProduction[tpId]
    if not spec then return end
    local construction = assert(tp.construction, "SCOM gateway construction missing: " .. tpId)
    local class = tp.general and tp.general.class
    local tags = assert(tp.tags, "SCOM gateway tags missing: " .. tpId)
    assert(class and class[2] == spec.class and table.find(tags, "SCFA_GATE")
        and type(construction.canBuild) == "string"
        and construction.canBuild:find(spec.buildTag, 1, true)
        and construction.platformBoneName == nil and construction.rollOffPoints == nil,
        "SCOM gateway factory contract changed: " .. tpId)

    if spec.hash then
        local source = tp.additions and tp.additions.faSourceContract
        assert(source and source.sourceId == spec.source and source.targetId == tpId
            and type(source.sourceBlueprintSha256) == "string"
            and string.lower(source.sourceBlueprintSha256) == spec.hash,
            "SCOM gateway FA source changed: " .. tpId)
    else
        local marker = tp.additions and tp.additions.scoFieldFixSeraphimGateway
        assert(marker and marker.factoryClass == spec.class
            and marker.canBuild == spec.buildTag,
            "SCOM Seraphim gateway class fix missing")
    end

    local points = {}
    for index, z in ipairs(spec.exits) do
        points[index] = {
            offset = {x = 0, y = 0, z = z},
            platformOffset = {x = 0, y = 0, z = 0},
            unitSpin = (index - 1) * 180,
            rollOffTime = 2,
        }
    end
    construction.rollOffPoints = points

    if tpId == "uss2510" then
        assert(not table.find(tags, "FACTORY"), "SCOM Seraphim gate tag already changed")
        table.insert(tags, "FACTORY")
        Tags(tp) -- Native template import indexed tags before this prefab hook.
    else
        assert(table.find(tags, "FACTORY"), "SCOM gateway lacks native FACTORY tag: " .. tpId)
    end
end

-- These imported structures use water-only FA footprints. Without NAVAL the
-- native client and host both validate them against land placement cells.
local SCO_WaterDefenceSources = {
    ues5017 = { "UEB2109", "SCFA_ANTINAVY" },
    ues5018 = { "UEB2205", "SCFA_ANTINAVY" },
    ues5020 = { "UEB3102", "SCFA_SONAR" },
    ues5021 = { "UEB3202", "SCFA_SONAR" },
    ugs5005 = { "URB2109", "SCFA_ANTINAVY" },
    ugs5006 = { "URB2205", "SCFA_ANTINAVY" },
    ugs5008 = { "URB3102", "SCFA_SONAR" },
    ugs5010 = { "URB3202", "SCFA_SONAR" },
    ugs5027 = { "XRB2308", "SCFA_ANTINAVY" },
    ucs1301 = { "UAB2109", "SCFA_ANTINAVY" },
    ucs2301 = { "UAB2205", "SCFA_ANTINAVY" },
    ucs1702 = { "UAB3102", "SCFA_SONAR" },
    ucs2702 = { "UAB3202", "SCFA_SONAR" },
}
local function SCO_RestoreWaterDefencePlacement(tp, tpId)
    local spec = SCO_WaterDefenceSources[tpId]
    if not spec then return end
    local source = tp.additions and tp.additions.faSourceContract
    local tags = assert(tp.tags, "SCOM water defence tags missing: " .. tpId)
    assert(source and source.sourceId == spec[1] and source.targetId == tpId
        and table.find(tags, spec[2]) and table.find(tags, "SCFA_ALLUNITS")
        and table.find(tags, "STRUCTURE")
        and not table.find(tags, "NAVAL") and not table.find(tags, "LAND")
        and tp.general.iconUIType == "land",
        "SCOM water defence source or placement changed: " .. tpId)
    local caps = source.sourceMovement and source.sourceMovement.BuildOnLayerCaps
    if caps then
        assert(caps.LAYER_Land == false
            and (caps.LAYER_Water == true or (tpId == "ugs5027" and caps.LAYER_Sub == true)),
            "SCOM water defence source layer changed: " .. tpId)
    end
    table.insert(tags, "NAVAL")
    tp.general.iconUIType = "water"
    Tags(tp) -- ReadUnitTemplate indexed tags before the source finalizer.
end

-- The ported torpedo weapons inherited Land-only firing gates even though
-- their source structures are water-only. An absent gate is the native naval
-- torpedo-tower policy and permits firing from the unit's actual layer.
local SCO_WaterTorpedoWeapons = {
    ucs1301 = { "psf0053" },
    ucs2301 = { "psf0054" },
    uss1301 = { "psf0120" },
    uss2301 = { "psf0117", "psf0114" },
}
local function SCO_RestoreWaterTorpedoFiring(tp, tpId)
    local spec = SCO_WaterTorpedoWeapons[tpId]
    if not spec then return end
    local weapons = assert(tp.weapons, "SCOM torpedo weapons missing: " .. tpId)
    assert(#weapons == #spec, "SCOM torpedo weapon count changed: " .. tpId)
    for index, projectile in ipairs(spec) do
        local weapon = weapons[index]
        local limits = weapon and weapon.layerWeaponLimits
        assert(weapon and weapon.projectileTemplate == projectile
            and type(limits) == "table" and #limits == 1 and limits[1] == "Land",
            "SCOM torpedo firing layer changed: " .. tpId .. " weapon " .. index)
        weapon.layerWeaponLimits = nil
    end
end

-- Unlike Guard T1/T2 sonar (which have SCOM source replacements), the native
-- T3 sonar has complete assets and no stationary source replacement.
local function SCO_ExposeGuardT3Sonar(tp, tpId)
    if tpId ~= "ugs3702" then return end
    local tags = assert(tp.tags, "Guard T3 sonar tags missing")
    local unitClass = tp.general.class
    assert(unitClass and unitClass[2] == "GuardNavalStructure"
        and table.find(tags, "GUARD") and table.find(tags, "TECH3")
        and table.find(tags, "STRUCTURE") and table.find(tags, "NAVAL")
        and table.find(tags, "SONAR") and not table.find(tags, "SCFA_ALLUNITS")
        and tp.general.iconUIType == "water"
        and Import('common/units/availableUnits.lua').AvailableUnits[tpId] == true,
        "Guard T3 sonar roster contract changed")
    table.insert(tags, "SCFA_ALLUNITS")
    Tags(tp) -- Must precede the source roster's availability filter.
end

