function SCO_ApplyMeasuredGroundTrails(tp, profile)
    if not profile then return false end
    assert(tp.general.tpId == profile.unit and tp.visuals,
        "SCOM ground-track profile identity mismatch")
    local modelId = tp.general.modelTpId or tp.general.tpId
    local modelPath = "Units/" .. modelId .. "/LOD0/" .. modelId .. "_lod0.sanmodel"
    if SCO_SourceBodyModel then modelPath = SCO_SourceBodyModel(tp, modelPath) end
    assert(profile.modelPath == modelPath and profile.boneName == "Root",
        "SCOM ground-track model identity mismatch: " .. tp.general.tpId)
    -- Terrain projectors replace the flat particle ribbons. Keep unrelated effects.
    local effects = {}
    for _, effect in ipairs(tp.visuals.effectsPersistent or {}) do
        local private = type(effect.particleName) == "string"
            and effect.particleName:match("^VFX/SCOM/GroundTracks/[%w_]+%.sanvfx$")
        if not SCO_KnownGroundTrails[effect.particleName] and not private then
            effects[#effects + 1] = effect
        end
    end
    tp.visuals.effectsPersistent = #effects > 0 and effects or nil
    tp.additions = tp.additions or {}
    tp.additions.scoGroundTracks = #profile.trails > 0 and profile or nil
    return true
end

