function SCO_FieldFixPostSourceUnitCorrections(tp)
    local id = tp.general.tpId
    SCO_ApplyMeasuredGroundTrails(tp, SCO_GroundTrailProfiles[id])
    local footfalls = SCO_GroundFootfallProfiles[id]
    if footfalls then
        tp.additions = tp.additions or {}
        tp.additions.scoGroundFootfalls = footfalls
    end
    if id == "usl4004" then
        local engineAudio = tp.audio and tp.audio.engine
        assert(footfalls and tp.audio and ((engineAudio and engineAudio.name == "aclu1346"
                and engineAudio.looping == true)
            or (tp.additions.scoYthothaContactAudio == true and engineAudio == nil)),
            "Ythotha movement audio contract changed")
        tp.additions.scoYthothaContactAudio = true
        tp.audio.engine = nil
    end
    SCO_RestoreWaterDefencePlacement(tp, id)
    SCO_RestoreWaterTorpedoFiring(tp, id)
    if id == "uel3001" then
        local body = assert(tp.collisionInfo)
        local shield = assert(tp.defence.shields and tp.defence.shields[1])
        assert(body.collisionSize.x == 0.9 and body.collisionSize.y == 1.2
            and shield.scoFaTitanPersonalShield == true
            and shield.collisionSize.x == 0.675 and shield.collisionSize.y == 0.9
            and shield.radii.x == 1.25, "Titan personal shield geometry drifted")
        -- The special source box is smaller than the unit's body collider.
        -- Use the visible sphere as the collision volume while retaining the
        -- personal-shield marker used by Titan's recharge policy.
        shield.scoFaTitanSphereCollider = true
    elseif id == "uel0000" then
        local shields = assert(tp.defence.shields)
        assert(#shields == 2
            and shields[1].scoCommanderEnhancementShieldId == "uefPersonal"
            and shields[2].scoCommanderEnhancementShieldId == "uefField"
            and shields[1].offset.y == 0.97 and shields[2].offset.y == 1
            and tp.collisionInfo.centerOffset.y == 0.97,
            "UEF ACU shield anchors drifted")
        local rootY = 1.1217918395996094
        shields[1].offset.y = tp.collisionInfo.centerOffset.y - rootY
        shields[2].offset.y = -3 - rootY
    elseif id == "ues3401" then
        local shield = assert(tp.defence.shields and tp.defence.shields[1])
        local source = tp.additions and tp.additions.faSourceContract
        assert(source and source.sourceShieldVerticalOffset == -6
            and shield.boneName == "Root"
            and shield.offset.y == 2.0057951
            and shield.offset.z == 0.0040371
            and shield.radii.x == 22,
            "UEF T3 shield anchor drifted")
        -- The imported Root is rotated: its local Z points upward in world
        -- space. Preserve the current horizontal anchor while lowering the
        -- dome by the source's six-unit vertical offset.
        shield.offset.z = shield.offset.z + source.sourceShieldVerticalOffset
    end

    -- Sanctuary treats this field as a maximum cone angle in degrees. The
    -- imported FA values make blast-radius hits almost certain at max range.
    -- Twice the source angles yields meaningful long-range dispersion.
    local artillery = {
        ues5019 = {old = 0.5, new = 1.0, damage = 5500, range = 750},
        ugs3101 = {old = 0.75, new = 1.5, damage = 4600, range = 700},
        ucs3101 = {old = 0, new = 0.75, damage = 6000, range = 900},
    }
    local spec = artillery[id]
    if spec then
        local found
        for _, weapon in ipairs(tp.weapons or {}) do
            if weapon.damage == spec.damage and weapon.rangeMax == spec.range then
                assert(not found, "Ambiguous T3 artillery weapon: " .. id)
                found = weapon
            end
        end
        assert(found and found.firingRandomness == spec.old,
            "T3 artillery dispersion drifted: " .. id)
        found.firingRandomness = spec.new
    end
    SCO_ConfigureDamageSmoke(tp)
end

local function SCO_MigrateMovementAuthoring(tp)
    local movement = tp.movement
    if not movement then return end
    if movement.bankFactor == nil and movement.orbitRange == nil
        and movement.altitudeJitterFactor == nil then return end

    -- The previous native job banked at 30 degrees times bankFactor, retaining
    -- 40% of the preceding roll each 0.1-second tick.
    if movement.bankFactor ~= nil then
        movement.maxBankDegrees = 30 * movement.bankFactor
        movement.bankHalfLife = 0.075647079736603
    end
    if not movement.air then return end

    -- Imported templates still contain the previous engine's movement fields.
    -- Use this build's native role profiles when they have no authored patterns.
    -- Importing a template here does not create its prefab or share mutable tables.
    local holdName = movement.patternBySituation and movement.patternBySituation.hold
    local holdPattern = movement.patterns and movement.patterns[holdName]
    local sourcePlaneNeedsCircle = movement.airHover == false
        and movement.orbitRange and movement.orbitRange > 0
        and (not holdPattern or holdPattern.mode ~= "Circle")
    if not movement.patterns or sourcePlaneNeedsCircle then
        local bomber = false
        for _, tag in pairs(tp.tags or {}) do
            if tag == "BOMBER" then bomber = true end
        end
        local donorID
        if movement.airHover then
            donorID = tp.weapons and #tp.weapons > 0 and "uea3011" or "uea1502"
        else
            donorID = bomber and "uea1001" or "uea1201"
        end
        local donor = Import("common/units/unitsTemplates/" .. donorID .. "/" .. donorID .. ".santp").UnitTemplate.movement
        assert(donor.patterns and donor.patternBySituation,
            "SCOM movement donor has no native patterns: " .. donorID)
        local function copy(value)
            if type(value) ~= "table" then return value end
            local result = {}
            for key, item in pairs(value) do result[key] = copy(item) end
            return result
        end
        movement.patterns = copy(donor.patterns)
        movement.patternBySituation = copy(donor.patternBySituation)
    end

    -- Retain the updated engine's authored movement roles and vertical phases.
    -- SCOM's source-backed aircraft speed/radius edits must reach Circle too.
    for _, pattern in pairs(movement.patterns) do
        if pattern.mode == "Circle" and pattern.circle then
            if movement.orbitRange and movement.orbitRange >= 0 then
                pattern.circle.radius = movement.orbitRange
            end
            if movement.orbitSpeed ~= nil then
                pattern.circle.speed = movement.orbitSpeed
            elseif movement.minSpeed ~= nil then
                pattern.circle.speed = movement.minSpeed
            end
        end
        if movement.altitudeJitterFactor == 0 then pattern.vertical = nil end
    end
end


local SCO_FieldFixPreviousCreateUnitPrefab = CreateUnitPrefab
local SCO_FieldFixShieldCorePaths = {
    ucs2401 = "VFX/SCOM/FieldFixes/Shields/aeon_core_t2.sanvfx",
    ucs3401 = "VFX/SCOM/FieldFixes/Shields/aeon_core_t3.sanvfx",
    uss2401 = "VFX/SCOM/FieldFixes/Shields/seraphim_core_t2.sanvfx",
    uss3401 = "VFX/SCOM/FieldFixes/Shields/seraphim_core_t3.sanvfx",
}
local SCO_FieldFixLoadedShieldCores = {}
local SCO_FieldFixDisabledHydroIds = {
    ucs1614 = "UAB1102", ues5015 = "UEB1102",
    ugs5003 = "URB1102", uss1614 = "XSB1102",
}
-- A later source stage installs a mock land Hydro provider. Keep the original
-- disabled-deposit policy for these four units in every consumer of that module.
local SCO_DisabledHydro = Import("common/systems/scoSourceHydroPlacement.lua")
local SCO_PreviousHydroPolicy = SCO_DisabledHydro.GetPolicy
local SCO_PreviousHydroBuildable = SCO_DisabledHydro.CanBuildNormally
local SCO_PreviousHydroPrepare = SCO_DisabledHydro.PrepareTemplate
local function SCO_DisabledHydroId(value)
    if type(value) == "table" then
        return value.general and value.general.tpId or value.tpId
    end
    return value
end
local SCO_DisabledHydroReason =
    "Requires a hydrocarbon deposit; this native runtime has no supported hydrocarbon resource type."
function SCO_DisabledHydro.GetPolicy(value)
    local id = SCO_DisabledHydroId(value)
    local policy = SCO_PreviousHydroPolicy(value)
    if not SCO_FieldFixDisabledHydroIds[id] then return policy end
    assert(type(policy) == "table", "SCOM disabled Hydro policy missing: " .. id)
    local disabled = {}
    for key, item in pairs(policy) do disabled[key] = item end
    disabled.normalConstructionSupported = false
    disabled.fallback = "blocked_normal_construction"
    disabled.reason = SCO_DisabledHydroReason
    disabled.mock = nil
    disabled.mockPlacementVersion = nil
    disabled.nativePlacementValidation = nil
    return disabled
end
function SCO_DisabledHydro.CanBuildNormally(value)
    if SCO_FieldFixDisabledHydroIds[SCO_DisabledHydroId(value)] then
        return false, SCO_DisabledHydroReason
    end
    return SCO_PreviousHydroBuildable(value)
end
function SCO_DisabledHydro.PrepareTemplate(tp)
    local id = SCO_DisabledHydroId(tp)
    local sourceId = SCO_FieldFixDisabledHydroIds[id]
    if not sourceId then return SCO_PreviousHydroPrepare(tp) end
    local additions = assert(tp.additions, "SCOM disabled Hydro additions missing: " .. id)
    local source = assert(additions.scoHydroPlacement,
        "SCOM disabled Hydro source policy missing: " .. id)
    local fa = assert(additions.faHydrocarbonPlacement,
        "SCOM disabled Hydro placement policy missing: " .. id)
    assert(source.sourceId == sourceId and source.targetId == id
        and source.sourceRequirement == "RULEUBR_OnHydrocarbonDeposit"
        and fa.sourceRequirement == "hydrocarbon_deposit",
        "SCOM disabled Hydro source identity changed: " .. id)
    source.normalConstructionSupported = false
    source.reason = SCO_DisabledHydroReason
    source.fallback = "blocked_normal_construction"
    source.nativeResourceSupported = false
    source.mock = nil
    source.mockPlacementVersion = nil
    source.nativePlacementValidation = nil
    fa.supported = false
    fa.fallback = "blocked_normal_construction"
    fa.nativeResourceSupported = false
    fa.mock = nil
    for index = #(tp.tags or {}), 1, -1 do
        local tag = tp.tags[index]
        if tag:match("^BUILDABLE_") or tag:match("^SCFA_BUILTBY") then
            table.remove(tp.tags, index)
        end
    end
end
function CreateUnitPrefab(tp)
    if type(tp) ~= "table" then
        error("SCOM field-fix dispatcher requires a unit template table.", 2)
    end
    local tpId = tp.general and tp.general.tpId
    if type(tpId) ~= "string" or tpId == "" then
        error("SCOM field-fix dispatcher requires UnitTemplate.general.tpId.", 2)
    end

    -- SCOM does not own the optional Promethean faction.  Its templates
    -- reference Prometheans/... assets supplied by that separate mod; do
    -- not route them through SCOM's prefab fixes or the native prefab loader.
    if type(tp.tags) == "table" and table.find(tp.tags, "PROMETHEAN") then
        return EngineErrorCode.InvalidGlobalID, nil
    end

    local editable = SCOM_EditableUnits.IsEditable(tp)
    local navalEngineerTagsAdded = false
    if not editable then
    SCO_FieldFixUniversalUef(tp, tpId)
    -- The native loader indexes tags before CreateUnitPrefab. These two source
    -- artillery templates shed DEMO_UI_ONLY here, so remove their stale index.
    if tpId == "ues2101" or tpId == "ues4101" then
        assert(not table.find(tp.tags, "DEMO_UI_ONLY"),
            "SCOM UEF artillery still has the demo-only tag")
        Tags.DEMO_UI_ONLY[tpId] = nil
        Tags(tp)
    end
    SCO_FieldFixCybran(tp, tpId)
    SCO_FieldFixAeonSeraphim(tp, tpId)
    SCO_RestoreGatewayProduction(tp, tpId)
    navalEngineerTagsAdded = SCO_GrantNavalEngineerBuildability(tp, tpId)
    local shieldCorePath = SCO_FieldFixShieldCorePaths[tpId]
    if IsClient and shieldCorePath then
        local shield = tp.defence and tp.defence.shields and tp.defence.shields[1]
        local effect = shield and shield.effectsPersistent and shield.effectsPersistent[1]
        assert(effect and effect.particleName == shieldCorePath,
            "SCOM shield core route drifted for " .. tpId)
        if not SCO_FieldFixLoadedShieldCores[shieldCorePath] then
            assert(Engine.LoadEffect(shieldCorePath),
                "SCOM shield core failed to load for " .. tpId)
            SCO_FieldFixLoadedShieldCores[shieldCorePath] = true
        end
    end
    SCO_FieldFixPrefabCompletion(tp, tpId)

    SCO_ExposeGuardT3Sonar(tp, tpId)

    SCO_MigrateMovementAuthoring(tp)
    end
    local errorCode, unitPrefabId = SCO_FieldFixPreviousCreateUnitPrefab(tp)
    -- SCOM Field Fix: fail-closed prefab result validation 1.0.0
    if errorCode ~= EngineErrorCode.Success or unitPrefabId == nil then
        error("SCOM field-fix prefab creation failed for " .. tpId
            .. ": errorCode=" .. tostring(errorCode)
            .. ", prefabId=" .. tostring(unitPrefabId), 2)
    end

    -- The native loader indexed the original builder tags before the hydro
    -- policy removed them. Clear those stale entries for the four disabled
    -- hydro templates, then reindex only their final tags.
    if not editable then
    if SCO_FieldFixDisabledHydroIds[tpId] then
        for _, tag in ipairs(tp.tags) do
            assert(not tag:match("^BUILDABLE_")
                and not tag:match("^SCFA_BUILTBY"),
                "SCOM hydro builder tag survived placement policy: " .. tpId)
        end
        for tag, ids in pairs(Tags) do
            if type(tag) == "string"
                and (tag:match("^BUILDABLE_") or tag:match("^SCFA_BUILTBY"))
            then
                ids[tpId] = nil
            end
        end
        Tags(tp)
    end

    -- SCOM Field Fix: Aeon AI factory tag-index synchronization 1.0.0
    local routing = tp.additions and tp.additions.scoFieldFixAeonFactoryRouting
    if type(routing) == "table" and routing.aiVisible == true then
        Tags(tp)
    end
    if navalEngineerTagsAdded then Tags(tp) end
    if tpId == "uel5010" then
        assert(table.find(tp.tags, "CONSTRUCTION"),
            "SCOM Sparky lacks the native construction tag")
        Tags(tp)
    end
    end
    return errorCode, unitPrefabId
end

-- Shared SCOM tree motion. Unit modules opt in; map setup owns registration.
do
    local CellSize, MaximumFalls = 16, 128
    local SweepingUnits = {uel4511 = true, ugl4001 = true, ucl4004 = true,
        usl4004 = true, ugl4002 = true, ugl4011 = true}
    local MaximumImpactRadius = 64
    local MaximumNukeImpactRadius = 192
    local cells, falls, fallThread = {}, {}, nil
    local impactQueue, impactHead, impactTail = {}, 1, 0
    local SinkStart, FadeStart, CleanupTime = 420, 465, 480
    local pending, pendingHead, pendingTail = {}, 1, 0
    local sinking, cleanupThread = {}, nil
    local clientFades, clientFadeThread = {}, nil
    local installed, generation = false, 0
    local registered, reported = 0, {}

    local function reportOnce(key, message)
        if reported[key] then return end
        reported[key] = true
        Engine.Warn("[SCOM trees] " .. message)
    end

    local function finite(value)
        return type(value) == "number" and value == value and math.abs(value) < math.huge
    end

    local function cellKey(x, z)
        return math.floor(x / CellSize) .. ":" .. math.floor(z / CellSize)
    end

    local function treeDefinition(tp)
        local tagged = false
        for _, tag in ipairs(tp.tags or {}) do
            if tag == "KNOCKDOWNABLE" then tagged = true end
        end
        if not tp.collider or not tp.collider.size then return end
        for _, effect in ipairs(tp.effects or {}) do
            if effect.type == "KnockdownEffect" and (tagged or effect.tag == "KNOCKDOWNABLE")
                and finite(effect.maxRotation)
                and effect.maxRotation >= 30 then
                local size = tp.collider.size
                local width = math.max(finite(size.x) and math.abs(size.x) or 0,
                    finite(size.z) and math.abs(size.z) or 0)
                return {height = size.y, width = width, angle = math.rad(math.min(88, effect.maxRotation)),
                    duration = effect.duration}
            end
        end
    end

    local function register(definition, id, position, scale, rotation)
        if not definition or not id or not id.index or id.index <= 0 then return end
        local q = rotation.value
        -- Already fallen scenery must retain its authored pose.
        if 1 - 2 * (q.x * q.x + q.z * q.z) < 0.8 then return end
        local height = definition.height * scale.y
        if not finite(height) or height <= 0 then return end
        local duration = definition.duration or {x = 1, y = 2}
        local low = finite(duration.x) and math.max(0.5, math.min(3, duration.x)) or 1
        local high = finite(duration.y) and math.max(low, math.min(3, duration.y)) or low
        local tree = {id = {index = id.index, version = id.version},
            x = position.x, y = position.y, z = position.z, height = height,
            crownRadius = math.max(definition.width * math.max(math.abs(scale.x), math.abs(scale.z)) / 2,
                height * 0.25),
            rotation = {value = {x = q.x, y = q.y, z = q.z, w = q.w}},
            angle = definition.angle, duration = low + (high - low) * (id.index % 97) / 96}
        local key = cellKey(tree.x, tree.z)
        local bucket = cells[key] or {}
        cells[key] = bucket
        bucket[#bucket + 1] = tree
        registered = registered + 1
    end

    local function reset()
        if fallThread then KillThread(fallThread); fallThread = nil end
        if cleanupThread then KillThread(cleanupThread); cleanupThread = nil end
        if clientFadeThread then KillThread(clientFadeThread); clientFadeThread = nil end
        cells, falls = {}, {}
        impactQueue, impactHead, impactTail = {}, 1, 0
        pending, pendingHead, pendingTail, sinking = {}, 1, 0, {}
        clientFades = {}
        registered, reported = 0, {}
        generation = generation + 1
    end

    local function updateClientFades()
        while next(clientFades) ~= nil do
            local now = Engine.GetSimulationTime()
            for key, fade in pairs(clientFades) do
                if now >= fade.expires or not Engine.IsValidGlobalID(fade.id) then
                    clientFades[key] = nil
                else
                    local code, localId = Engine.GetGlobalEntityPairedLocalID(fade.id)
                    if code == EngineErrorCode.Success and Engine.IsValidLocalID(localId) then
                        local progress = math.max(0, math.min(1,
                            (now - fade.started) / (fade.expires - fade.started)))
                        -- The scoped renderer helper dissolves only these marked foliage instances.
                        Engine.SetRendererInstanceData1(localId,
                            EngineClasses.float4(0, 0, 58413, 1 - progress))
                    end
                end
            end
            WaitTicks(1)
        end
        clientFadeThread = nil
    end

    local function receiveFade(data)
        if type(data) ~= "table" or type(data.id) ~= "table"
            or not finite(data.id.index) or not finite(data.id.version)
            or not finite(data.started) or not finite(data.expires)
            or data.expires <= data.started or data.expires - data.started > 15.01 then return end
        local key = data.id.index .. ":" .. data.id.version
        if clientFades[key] then return end
        clientFades[key] = {id = {index = data.id.index, version = data.id.version},
            started = data.started, expires = data.expires}
        if not clientFadeThread then clientFadeThread = NewThread(updateClientFades) end
    end

    local function install()
        if installed then return end
        installed = true
        local map = Import("common/mapUtils.lua")
        if IsClient then
            RegisterListener("client_SCOMFallenTreeFade", receiveFade)
            local setup = map.RunMapSetup
            map.RunMapSetup = function(...)
                reset()
                return setup(...)
            end
            return
        end
        if not IsHost then return end
        local loader = Import("common/loading/propTemplateLoader.lua")
        local setup = map.RunMapSetup
        map.RunMapSetup = function(instantiate, ...)
            if not instantiate then return setup(instantiate, ...) end
            reset()
            local definitions = {}
            local create, spawn = loader.CreatePropPrefab, Engine.InstantiatePrefab
            loader.CreatePropPrefab = function(tp)
                local code, prefab = create(tp)
                if code == EngineErrorCode.Success then definitions[prefab.Value] = treeDefinition(tp) end
                return code, prefab
            end
            Engine.InstantiatePrefab = function(prefab, position, scale, rotation, output)
                local code, id = spawn(prefab, position, scale, rotation, output)
                if code == EngineErrorCode.Success then
                    register(definitions[prefab.Value], id, position, scale, rotation)
                end
                return code, id
            end
            -- Native setup is synchronous. Never leave the temporary capture hooks installed.
            local result = {pcall(setup, instantiate, ...)}
            loader.CreatePropPrefab, Engine.InstantiatePrefab = create, spawn
            if not result[1] then reset(); error(result[2], 0) end
            reportOnce("map", "Registered " .. registered .. " standing trees for Fatboy contact.")
            return unpack(result, 2)
        end
    end

    local function cleanupFallenTrees()
        while pendingHead <= pendingTail or #sinking > 0 do
            local now = Engine.GetSimulationTime()
            while pendingHead <= pendingTail and pending[pendingHead].started + SinkStart <= now do
                local tree = pending[pendingHead]
                pending[pendingHead] = nil
                pendingHead = pendingHead + 1
                if Engine.IsValidGlobalID(tree.id) then sinking[#sinking + 1] = tree end
            end
            if pendingHead > pendingTail then pending, pendingHead, pendingTail = {}, 1, 0 end
            for index = #sinking, 1, -1 do
                local tree = sinking[index]
                local elapsed = now - tree.started
                if not Engine.IsValidGlobalID(tree.id) then
                    table.remove(sinking, index)
                elseif elapsed >= CleanupTime then
                    local code = Engine.DeletePrefabInstance(tree.id, false)
                    tree.deleteAttempts = (tree.deleteAttempts or 0) + 1
                    if code == EngineErrorCode.Success or tree.deleteAttempts >= 5 then
                        if code ~= EngineErrorCode.Success then
                            reportOnce("deleteError", "Fallen-tree cleanup rejected: " .. tostring(code))
                        end
                        table.remove(sinking, index)
                    end
                else
                    local progress = math.max(0, math.min(1, (elapsed - SinkStart) / (CleanupTime - SinkStart)))
                    local eased = progress * progress * (3 - 2 * progress)
                    local code = Engine.SetGlobalEntityPosition(tree.id, {
                        x = tree.rest.x, y = tree.rest.y - tree.sinkDepth * eased, z = tree.rest.z})
                    if code ~= EngineErrorCode.Success then
                        reportOnce("sinkError", "Fallen-tree sinking rejected: " .. tostring(code))
                    end
                    if elapsed >= FadeStart and not tree.fadeSent then
                        SendToAllClients({id = tree.id,
                            started = tree.started + FadeStart, expires = tree.started + CleanupTime},
                            "SCOMFallenTreeFade")
                        tree.fadeSent = true
                    end
                end
            end
            if #sinking > 0 then
                WaitTicks(1)
            elseif pendingHead <= pendingTail then
                WaitSeconds(math.max(Constants.TickTimeStep,
                    math.min(1, pending[pendingHead].started + SinkStart - now)))
            end
        end
        cleanupThread = nil
    end

    local function scheduleCleanup(tree)
        local offset = tree.pivotOffset * math.sin(tree.angle)
        tree.rest = {x = tree.x + tree.dx * offset,
            y = tree.pivotY + tree.pivotOffset * math.cos(tree.angle), z = tree.z + tree.dz * offset}
        tree.sinkDepth = math.max(1, tree.height * math.max(0, math.cos(tree.angle)) + tree.crownRadius + 0.25)
        -- Falls can finish out of order; keep the waiting queue ordered without polling every tree each tick.
        local position = pendingTail + 1
        while position > pendingHead and pending[position - 1].started > tree.started do
            pending[position] = pending[position - 1]
            position = position - 1
        end
        pending[position] = tree
        pendingTail = pendingTail + 1
        if not cleanupThread then cleanupThread = NewThread(cleanupFallenTrees) end
    end

    local topple
    local function drainImpactQueue()
        while impactHead <= impactTail and #falls < MaximumFalls do
            local entry = impactQueue[impactHead]
            impactQueue[impactHead] = nil
            impactHead = impactHead + 1
            local tree = entry.tree
            if Engine.IsValidGlobalID(tree.id) then
                local originalAngle = tree.angle
                if not topple(tree, entry.dx, entry.dz) then
                    tree.angle = originalAngle
                    local key = cellKey(tree.x, tree.z)
                    local bucket = cells[key] or {}
                    cells[key] = bucket
                    bucket[#bucket + 1] = tree
                end
            end
        end
        if impactHead > impactTail then impactQueue, impactHead, impactTail = {}, 1, 0 end
    end

    local function animateFalls()
        while #falls > 0 or impactHead <= impactTail do
            WaitTicks(1)
            drainImpactQueue()
            local now = Engine.GetSimulationTime()
            for index = #falls, 1, -1 do
                local tree = falls[index]
                local elapsed = math.max(0, now - tree.started)
                if not Engine.IsValidGlobalID(tree.id) then
                    table.remove(falls, index)
                else
                    local progress = math.min(1, elapsed / tree.duration)
                    local angle = tree.angle * progress * progress
                    if elapsed > tree.duration then
                        local settle = math.min(1, (elapsed - tree.duration) / 0.25)
                        angle = tree.angle - math.rad(2) * math.sin(settle * math.pi) * (1 - settle)
                    end
                    local rotation = Engine.QuaternionMultiply(
                        Engine.QuaternionAxisAngle(tree.axis, angle), tree.rotation)
                    local code = EngineErrorCode.Success
                    if tree.pivotOffset < 0 then
                        -- Rotate the buried root around ground contact, keeping the
                        -- visible trunk's hinge fixed instead of sinking the whole tree.
                        local offset = tree.pivotOffset * math.sin(angle)
                        code = Engine.SetGlobalEntityPosition(tree.id, {
                            x = tree.x + tree.dx * offset,
                            y = tree.pivotY + tree.pivotOffset * math.cos(angle),
                            z = tree.z + tree.dz * offset})
                    end
                    if code == EngineErrorCode.Success then
                        code = Engine.SetGlobalEntityLocalRotation(tree.id, rotation)
                    end
                    if code ~= EngineErrorCode.Success then
                        reportOnce("rotationError", "Tree rotation rejected: " .. tostring(code))
                    elseif elapsed > 0 then
                        reportOnce("fall", "First tree fall reached the native rotation setter.")
                    end
                    if code ~= EngineErrorCode.Success or elapsed >= tree.duration + 0.25 then
                        if code == EngineErrorCode.Success then scheduleCleanup(tree) end
                        table.remove(falls, index)
                    end
                end
            end
        end
        fallThread = nil
    end

    topple = function(tree, dx, dz)
        if #falls >= MaximumFalls then return false end
        local length = math.sqrt(dx * dx + dz * dz)
        if length < 0.0001 then return false end
        dx, dz = dx / length, dz / length
        local baseCode, ground = Engine.SampleTerrainHeight({x = tree.x, y = tree.y, z = tree.z})
        if baseCode ~= EngineErrorCode.Success or not finite(ground) then return false end
        tree.pivotY = math.max(tree.y, ground)
        tree.pivotOffset = tree.y - tree.pivotY
        local visibleHeight = tree.height + tree.pivotOffset
        if visibleHeight <= 0 then return false end
        -- Limit the resting angle on rising ground so the trunk does not bury itself.
        for _, fraction in ipairs({0.5, 1}) do
            local reach = visibleHeight * fraction
            local code, height = Engine.SampleTerrainHeight({x = tree.x + dx * reach, y = tree.y, z = tree.z + dz * reach})
            if code == EngineErrorCode.Success and finite(height) then
                local rise = math.max(-1, math.min(1, (height - tree.pivotY) / reach))
                tree.angle = math.min(tree.angle, math.acos(rise))
            end
        end
        if tree.angle < math.rad(5) then return false end
        tree.dx, tree.dz = dx, dz
        tree.axis = EngineClasses.float3(dz, 0, -dx)
        tree.started = Engine.GetSimulationTime()
        falls[#falls + 1] = tree
        if not fallThread then fallThread = NewThread(animateFalls) end
        return true
    end

    local function localPoint(tree, pose)
        local dx, dz = tree.x - pose.x, tree.z - pose.z
        local c, s = math.cos(pose.yaw), math.sin(pose.yaw)
        return (dx * c - dz * s) / pose.scale, (dx * s + dz * c) / pose.scale
    end

    local function intersects(x0, z0, x1, z1, bounds)
        local enter, leave = 0, 1
        for _, axis in ipairs({{x0, x1 - x0, bounds.left, bounds.right},
                              {z0, z1 - z0, bounds.rear, bounds.front}}) do
            if math.abs(axis[2]) < 0.000001 then
                if axis[1] < axis[3] or axis[1] > axis[4] then return false end
            else
                local a, b = (axis[3] - axis[1]) / axis[2], (axis[4] - axis[1]) / axis[2]
                enter, leave = math.max(enter, math.min(a, b)), math.min(leave, math.max(a, b))
                if enter > leave then return false end
            end
        end
        return true
    end

    local function sweep(tree, previous, current, turn, bounds)
        local steps = math.max(1, math.ceil(math.abs(turn) / math.rad(5)))
        local x, z = localPoint(tree, previous)
        for step = 1, steps do
            local t = step / steps
            local pose = {x = previous.x + (current.x - previous.x) * t,
                z = previous.z + (current.z - previous.z) * t,
                yaw = previous.yaw + turn * t, scale = current.scale}
            local nx, nz = localPoint(tree, pose)
            if intersects(x, z, nx, nz, bounds) then return true end
            x, z = nx, nz
        end
        return false
    end

    local function update(unit, bounds)
        reportOnce("update", "Experimental footprint update reached; registered trees=" .. registered .. ".")
        if not SweepingUnits[unit.tpId] or unit.dead or unit.deleted or unit.fatboyMovementLocked
            or unit.scoCargoCarrierID or not unit:IsCompleted() or unit:IsPlacementGhost() then
            unit.scoTreeSweep = nil
            return
        end
        local bone = unit:GetBoneId("Root")
        if not bone or not Engine.IsValidGlobalID(bone) then
            reportOnce("root", "Experimental Root has no valid simulation ID.")
            unit.scoTreeSweep = nil; return
        end
        local code, matrix = Engine.GetGlobalEntityWorldMatrix(bone)
        if code ~= EngineErrorCode.Success then unit.scoTreeSweep = nil; return end
        local scale = math.sqrt(matrix.c0.x ^ 2 + matrix.c0.y ^ 2 + matrix.c0.z ^ 2)
        if not finite(scale) or scale <= 0 then unit.scoTreeSweep = nil; return end
        local now = Engine.GetSimulationTime()
        local current = {x = matrix.c3.x, y = matrix.c3.y - bounds.rootHeight * scale,
            z = matrix.c3.z, yaw = math.atan2(matrix.c2.x, matrix.c2.z),
            scale = scale, time = now, generation = generation}
        local previous = unit.scoTreeSweep
        unit.scoTreeSweep = current
        if not previous or previous.generation ~= generation then return end
        local elapsed = now - previous.time
        local dx, dz = current.x - previous.x, current.z - previous.z
        local distance = math.sqrt(dx * dx + dz * dz)
        local turn = (current.yaw - previous.yaw + math.pi) % (2 * math.pi) - math.pi
        local speedCode, speed = Engine.GetMovementCurrentSpeed(unit.id)
        if elapsed <= 0 or elapsed > 0.5 or speedCode ~= EngineErrorCode.Success or not finite(speed)
            or math.abs(scale - previous.scale) > 0.001
            or distance > math.max(2, math.abs(speed) * elapsed * 4 + 1)
            or math.abs(turn) > math.rad(60) then return end
        if distance < 0.001 and math.abs(turn) < 0.001 then return end
        reportOnce("motion", "Experimental motion detected; hull base=" .. string.format("%.2f", current.y)
            .. ", scale=" .. string.format("%.3f", scale) .. ".")
        local waterCode, water = Engine.HasWater()
        if waterCode ~= EngineErrorCode.Success then return end
        if water then
            local levelCode, level = Engine.GetWaterLevel()
            if levelCode ~= EngineErrorCode.Success or current.y < level - 0.1 then return end
        end
        local radius = math.sqrt(math.max(bounds.left ^ 2, bounds.right ^ 2)
            + math.max(bounds.front ^ 2, bounds.rear ^ 2)) * scale
        for cx = math.floor((math.min(previous.x, current.x) - radius) / CellSize),
                 math.floor((math.max(previous.x, current.x) + radius) / CellSize) do
            for cz = math.floor((math.min(previous.z, current.z) - radius) / CellSize),
                     math.floor((math.max(previous.z, current.z) + radius) / CellSize) do
                local bucket = cells[cx .. ":" .. cz]
                if bucket then
                    for index = #bucket, 1, -1 do
                        local tree = bucket[index]
                        if not Engine.IsValidGlobalID(tree.id) then
                            table.remove(bucket, index)
                        -- Map authors often bury trunk roots or place trees on slopes.
                        -- Contact needs vertical trunk/hull overlap, not equal base heights.
                        elseif tree.y <= math.max(previous.y, current.y) + bounds.top * scale
                            and tree.y + tree.height >= math.min(previous.y, current.y) + bounds.bottom * scale
                            and sweep(tree, previous, current, turn, bounds)
                            and topple(tree, dx + turn * (tree.z - current.z), dz - turn * (tree.x - current.x)) then
                            table.remove(bucket, index)
                        end
                    end
                end
            end
        end
    end

    -- Host impacts query standing trunks inside a bounded sphere. Overflow
    -- shares the existing fall worker and its 128-tree budget.
    local function impact(position, radius, maximumRadius, nearestFirst)
        if not IsHost or type(position) ~= "table" or not finite(position.x)
            or not finite(position.y) or not finite(position.z)
            or not finite(radius) or radius <= 0 then return 0 end
        radius = math.min(radius, maximumRadius)
        local radiusSquared, accepted = radius * radius, 0
        local selected = nearestFirst and {} or nil
        local firstX, lastX = math.floor((position.x - radius) / CellSize), math.floor((position.x + radius) / CellSize)
        local firstZ, lastZ = math.floor((position.z - radius) / CellSize), math.floor((position.z + radius) / CellSize)
        local maximumSpan = maximumRadius * 2 / CellSize
        -- Small integer offsets also terminate for finite positions beyond the
        -- range where adding one to an absolute cell coordinate changes it.
        for offsetX = 0, math.min(maximumSpan, lastX - firstX) do
            local cx = firstX + offsetX
            for offsetZ = 0, math.min(maximumSpan, lastZ - firstZ) do
                local cz = firstZ + offsetZ
                local bucket = cells[cx .. ":" .. cz]
                if bucket then
                    for index = #bucket, 1, -1 do
                        local tree = bucket[index]
                        if not Engine.IsValidGlobalID(tree.id) then
                            table.remove(bucket, index)
                        else
                            local dx, dz = tree.x - position.x, tree.z - position.z
                            local distanceSquared = dx * dx + dz * dz
                            if distanceSquared <= radiusSquared then
                                local code, ground = Engine.SampleTerrainHeight({x = tree.x, y = tree.y, z = tree.z})
                                if code == EngineErrorCode.Success and finite(ground) then
                                    local base, top = math.max(tree.y, ground), tree.y + tree.height
                                    local closestY = math.max(base, math.min(top, position.y))
                                    if top > base and distanceSquared + (closestY - position.y) ^ 2 <= radiusSquared then
                                        if distanceSquared < 0.00000001 then
                                            local angle = (tree.id.index % 360) * math.pi / 180
                                            dx, dz = math.cos(angle), math.sin(angle)
                                        end
                                        local entry = {tree = tree, dx = dx, dz = dz}
                                        if selected then
                                            entry.distanceSquared = distanceSquared
                                            selected[#selected + 1] = entry
                                        else
                                            impactTail = impactTail + 1
                                            impactQueue[impactTail] = entry
                                        end
                                        table.remove(bucket, index)
                                        accepted = accepted + 1
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
        if selected then
            table.sort(selected, function(a, b)
                if a.distanceSquared ~= b.distanceSquared then return a.distanceSquared < b.distanceSquared end
                return a.tree.id.index < b.tree.id.index
            end)
            for _, entry in ipairs(selected) do
                impactTail = impactTail + 1
                impactQueue[impactTail] = entry
            end
        end
        if accepted > 0 and not fallThread then fallThread = NewThread(animateFalls) end
        return accepted
    end

    local function ordinaryImpact(position, radius)
        return impact(position, radius, MaximumImpactRadius, false)
    end

    -- Nuclear batches begin at the center without changing older queued work.
    local function nukeImpact(position, radius)
        return impact(position, radius, MaximumNukeImpactRadius, true)
    end

    SCOMTreeKnockdown = {Update = update, Impact = ordinaryImpact, NukeImpact = nukeImpact}
    install()
end

-- SCOM Fatboy unit module bridge 1.0.0. Loaded once in the shared loader module.
do
    local unitRoot = "scom/units/uel4511/"
    local loaded, warnings, derived = {}, {}, {}
    local numeric = {
        health = {max = {1, 100000000}, regen = {0, 1000000}},
        shield = {
            max = {1, 100000000}, regen = {0, 1000000},
            rechargeTime = {0.01, 86400}, regenDelay = {0, 86400},
            energyDrainRechargeTime = {0.01, 86400},
        },
        economy = {
            buildTime = {0.01, 100000000}, alloys = {0, 100000000},
            energy = {0, 100000000}, maintenanceEnergy = {0, 1000000},
            storageAlloys = {0, 100000000}, storageEnergy = {0, 100000000},
        },
        movement = {
            speed = {0.01, 100}, acceleration = {0.01, 100},
            deceleration = {0.01, 100}, rotationSpeed = {0.01, 360},
        },
        production = {buildPower = {0.01, 1000000}},
        weapons = {damage = {0, 100000000}, damageRadius = {0, 1000}, reloadTime = {0.01, 86400}},
    }

    local function clone(value, seen)
        if type(value) ~= "table" then return value end
        assert(getmetatable(value) == nil, "library table with a metatable cannot be privately copied")
        seen = seen or {}
        if seen[value] then return seen[value] end
        local copy = {}
        seen[value] = copy
        for key, child in pairs(value) do copy[key] = clone(child, seen) end
        return copy
    end

    local function readOnly(source, seen)
        if type(source) ~= "table" then return source end
        seen = seen or {}
        if seen[source] then return seen[source] end
        local proxy = {}
        seen[source] = proxy
        return setmetatable(proxy, {
            __index = function(_, key) return readOnly(source[key], seen) end,
            __newindex = function() error("library values are read-only", 2) end,
            __metatable = false,
        })
    end

    local function warnOnce(path, detail)
        local key = tostring(path)
        if warnings[key] then return end
        warnings[key] = true
        Warn("SCOM uel4511: " .. tostring(path) .. ": "
            .. tostring(detail):sub(1, 700) .. "; shared DLL defaults retained")
    end

    local safe = {
        assert = assert, error = error, ipairs = ipairs, pairs = pairs, next = next,
        tonumber = tonumber, tostring = tostring, type = type, select = select, unpack = unpack,
        math = readOnly({abs = math.abs, ceil = math.ceil, floor = math.floor,
            max = math.max, min = math.min, sqrt = math.sqrt, pi = math.pi}),
        string = readOnly({format = string.format, sub = string.sub, match = string.match,
            find = string.find, lower = string.lower, upper = string.upper, len = string.len}),
        table = readOnly({insert = table.insert, remove = table.remove, concat = table.concat,
            sort = table.sort}),
    }

    local function readModule(path, kind)
        assert(path == unitRoot .. kind .. ".lua", "unexpected unit module path")
        local cached = loaded[path]
        if cached then
            assert(cached.ok, cached.error)
            return cached.module
        end
        local ok, module = pcall(function()
            local source = Engine.GetFileContent(libPath .. "/" .. path)
            assert(type(source) == "string", "unit module is missing")
            assert(#source <= 131072, "unit module exceeds 128 KiB")
            local env = setmetatable({}, {__index = safe})
            local chunk, failure = load(source, "@" .. path, "t", env)
            assert(chunk, failure)
            chunk()
            local export = kind == "template" and "Settings" or "Methods"
            for key in pairs(env) do
                assert(key == export or key == "UseLibraryDefaults", "unexpected export: " .. tostring(key))
            end
            assert(env.UseLibraryDefaults == true, "UseLibraryDefaults must be true")
            assert(type(rawget(env, export)) == "table", export .. " must be a table")
            return env
        end)
        loaded[path] = ok and {ok = true, module = module} or {ok = false, error = module}
        assert(ok, module)
        return module
    end

    local function plainTable(value, name)
        assert(type(value) == "table" and getmetatable(value) == nil, name .. " must be a plain table")
    end

    local function checkNumber(value, rule, name)
        assert(type(value) == "number" and value == value
            and value >= rule[1] and value <= rule[2], name .. " is outside its numeric limits")
    end

    local function applyFields(target, values, rules, name)
        plainTable(values, name)
        assert(type(target) == "table", name .. " is absent from the library template")
        for key, value in pairs(values) do
            local rule = rules[key]
            assert(rule, "unsupported setting: " .. name .. "." .. tostring(key))
            checkNumber(value, rule, name .. "." .. key)
            assert(type(target[key]) == "number", name .. "." .. key .. " has no numeric library default")
            target[key] = value
        end
    end

    local function configureTemplate(tp, path)
        if not (type(tp) == "table" and type(tp.general) == "table" and tp.general.tpId == "uel4511") then
            return tp, false
        end
        local ok, candidate = pcall(function()
            local settings = readModule(path, "template").Settings
            plainTable(settings, "Settings")
            for key, value in pairs(settings) do
                assert(numeric[key], "unsupported settings group: " .. tostring(key))
                plainTable(value, tostring(key))
            end
            local copy = clone(tp)
            if settings.health then
                applyFields(copy.defence and copy.defence.health, settings.health, numeric.health, "health")
                if settings.health.max then copy.defence.health.value = copy.defence.health.max end
            end
            if settings.shield then
                local shield = copy.defence and copy.defence.shields and copy.defence.shields[1]
                applyFields(shield, settings.shield, numeric.shield, "shield")
                if settings.shield.max then shield.value = shield.max end
            end
            if settings.economy then
                plainTable(settings.economy, "economy")
                local economy = assert(copy.economy, "economy is absent from the library template")
                local targets = {
                    buildTime = {economy, "buildTime"},
                    alloys = {economy.cost, "alloys"}, energy = {economy.cost, "energy"},
                    maintenanceEnergy = {economy.maintenanceConsumption, "energy"},
                    storageAlloys = {economy.storage, "alloys"}, storageEnergy = {economy.storage, "energy"},
                }
                for key, value in pairs(settings.economy) do
                    local rule = numeric.economy[key]
                    assert(rule, "unsupported setting: economy." .. tostring(key))
                    checkNumber(value, rule, "economy." .. key)
                    local target = targets[key]
                    assert(type(target[1]) == "table" and type(target[1][target[2]]) == "number",
                        "economy." .. key .. " has no numeric library default")
                    target[1][target[2]] = value
                end
            end
            if settings.movement then applyFields(copy.movement, settings.movement, numeric.movement, "movement") end
            if settings.production then applyFields(copy.construction, settings.production, numeric.production, "production") end
            if settings.weapons then
                plainTable(settings.weapons, "weapons")
                assert(type(copy.weapons) == "table", "weapons are absent from the library template")
                for index, values in pairs(settings.weapons) do
                    assert(type(index) == "number" and index % 1 == 0 and index >= 1
                        and index <= #copy.weapons, "weapon index is outside the library template")
                    applyFields(copy.weapons[index], values, numeric.weapons, "weapons[" .. index .. "]")
                end
            end
            return copy
        end)
        if not ok then warnOnce(path, candidate); return tp, false end
        return candidate, true
    end

    local function deriveClass(base, path, realm)
        local ok, child = pcall(function()
            assert(realm == "host" or realm == "client", "unknown class realm")
            local env = readModule(path, realm)
            local cached = derived[path]
            if cached then
                assert(cached.base == base or cached.class == base, "class library changed after unit module preparation")
                return cached.class
            end
            local methods = env.Methods
            plainTable(methods, "Methods")
            local meta = debug.getmetatable(base)
            assert(type(meta) == "table" and type(meta.__pairs) == "function" and Class.name(base),
                "base is not a native class")
            for name, method in pairs(methods) do
                local optionalDisplay = realm == "client" and name == "GetFactoryRallyDisplayPoint"
                assert(type(name) == "string" and name:sub(1, 2) ~= "__"
                    and (type(base[name]) == "function" or optionalDisplay),
                    "unsupported override: " .. tostring(name))
                assert(type(method) == "function", "override must be a function: " .. name)
            end
            local baseMethods, tables, copiedTables = {}, {}, {}
            -- Native LuaJIT pairs() ignores __pairs; call Classy's iterator explicitly.
            for name, value in meta.__pairs(base) do
                if type(value) == "function" and name:sub(1, 2) ~= "__" then baseMethods[name] = value end
                if type(value) == "table" and name ~= "__class" then tables[name] = clone(value, copiedTables) end
            end
            local result = Class("SCOMUel4511" .. realm, base)
            for name, value in pairs(tables) do result[name] = value end
            for name, method in pairs(methods) do
                local previous = base[name]
                result[name] = function(self, ...)
                    if type(self) ~= "table" or self.tpId ~= "uel4511" then
                        if previous then return previous(self, ...) end
                        return nil
                    end
                    return method(self, ...)
                end
            end
            env.Base = readOnly(baseMethods)
            env.Library = readOnly({TreeKnockdown = realm == "host" and SCOMTreeKnockdown or nil,
                Engine = Engine, EngineClasses = EngineClasses,
                EngineErrorCode = EngineErrorCode, Constants = Constants,
                WaitTicks = WaitTicks, WaitSeconds = WaitSeconds, KillThread = KillThread, Log = Log})
            derived[path] = {base = base, class = result}
            return result
        end)
        if not ok then warnOnce(path, child); return base, false end
        return child, true
    end

    SCOMUnitLibrary = {ConfigureTemplate = configureTemplate, DeriveClass = deriveClass}
end

-- Health-driven smoke uses ordinary native particle children, owned by the unit.
do
local Loaded = {}
local Thresholds = {0.75, 0.50, 0.25}
local Sites = {{0.18, 0.25, -0.20}, {-0.22, 0.18, 0.18}, {0.20, 0.28, 0.16}}
local FireThresholds = {0.25, 0.10}
local FireSites = {{0.18, 0.42, -0.20}, {-0.22, 0.40, 0.18}}

function SCO_ConfigureDamageSmoke(tp)
    if not table.find(tp.tags or {}, "SCFA_ALLUNITS") then return end
    local health = tp.defence and tp.defence.health
    local body = tp.collisionInfo
    if not health or not health.max or health.max <= 0 or not body then return end
    local size, center = body.collisionSize, body.centerOffset
    assert(size and center and size.x > 0 and size.y > 0 and size.z > 0,
        "SCOM damage smoke requires a valid body collider: " .. tp.general.tpId)
    local extent = math.max(size.x, size.y, size.z)
    local variant = extent < 1.4 and "small" or (extent < 4 and "medium" or "large")
    local path = "VFX/SCOM/DamageSmoke/scom_damage_smoke_" .. variant .. ".sanvfx"
    local firePath = "VFX/SCOM/DamageSmoke/scom_damage_fire_" .. variant .. ".sanvfx"
    tp.visuals = tp.visuals or {}
    tp.visuals.effectsPersistent = tp.visuals.effectsPersistent or {}
    local effects = tp.visuals.effectsPersistent
    -- Replays replace only our entries; source exhausts and faction effects stay intact.
    for index = #effects, 1, -1 do
        if effects[index].scoDamageSmoke or effects[index].scoDamageFire then table.remove(effects, index) end
    end
    for index, site in ipairs(Sites) do
        effects[#effects + 1] = {boneName = TemplateHeadEntityName, particleName = path,
            positionOffset = {x = center.x + size.x * site[1],
                y = center.y + size.y * site[2], z = center.z + size.z * site[3]},
            scoDamageSmoke = Thresholds[index]}
    end
    for index, site in ipairs(FireSites) do
        effects[#effects + 1] = {boneName = TemplateHeadEntityName, particleName = firePath,
            positionOffset = {x = center.x + size.x * site[1],
                y = center.y + size.y * site[2], z = center.z + size.z * site[3]},
            scoDamageFire = FireThresholds[index]}
    end
    if IsClient then
        for _, effectPath in ipairs({path, firePath}) do
            if not Loaded[effectPath] then
                assert(Engine.LoadEffect(effectPath), "SCOM damage effect failed to load: " .. effectPath)
                Loaded[effectPath] = true
            end
        end
    end
end
end

