-- SCOM source final template policy 1.1.0
SCO_SourceFinalizerOwnsIdleResetTurretRest = true
local SCO_SourceFinalizers = {}
do
local previous = SCO_SourceFinalizers['uca1201']
SCO_SourceFinalizers['uca1201'] = function(UnitTemplate)
if previous then previous(UnitTemplate) end
-- Source-matched existing weapon upgrade; exact muzzle identity is the key.
do
local tp=UnitTemplate
assert(tp.general.tpId=="uca1201",'Existing weapon appendix scope mismatch')
local rows={{["sourceIndex"]=1,["sourceLabel"]="SonicPulseBattery1",["nativeLabel"]=nil,["oldProjectile"]="paa111",["newProjectile"]="psf0048",["nativeMuzzles"]={"turret_muzzle_right"},["nativeMode"]={["damage"]=8,["rangeMin"]=0,["rangeMax"]=25},["sourceProjectile"]="/projectiles/AAASonicPulse02/AAASonicPulse02_proj.bp",["sourceBlueprintSha256"]="04fda000ad8a4be8036c2d76809c568abad59d7badb275f433e11c546be138a8"},{["sourceIndex"]=2,["sourceLabel"]="SonicPulseBattery2",["nativeLabel"]=nil,["oldProjectile"]="paa111",["newProjectile"]="psf0048",["nativeMuzzles"]={"turret_muzzle_left"},["nativeMode"]={["damage"]=8,["rangeMin"]=0,["rangeMax"]=25},["sourceProjectile"]="/projectiles/AAASonicPulse02/AAASonicPulse02_proj.bp",["sourceBlueprintSha256"]="04fda000ad8a4be8036c2d76809c568abad59d7badb275f433e11c546be138a8"}}
local updates={}
for _,r in ipairs(rows) do
local found
for _,w in ipairs(tp.weapons or {}) do
local bones,count={},0
for _,g in ipairs(w.muzzleGroups or {}) do for _,b in ipairs(g.muzzles or {}) do local key=string.lower(b);if not bones[key] then bones[key]=true;count=count+1 end end end
local matches=count==#r.nativeMuzzles
for _,b in ipairs(r.nativeMuzzles) do matches=matches and bones[b] end
matches=matches and (r.nativeLabel==nil or w.name==r.nativeLabel)
for key,value in pairs(r.nativeMode) do matches=matches and (w[key] or 0)==value end
if matches and (w.projectileTemplate==r.oldProjectile or w.projectileTemplate==r.newProjectile) then
assert(not found,'Ambiguous source projectile weapon '..tp.general.tpId..':'..r.sourceLabel)
found=w
end
end
assert(found,'Source projectile weapon changed '..tp.general.tpId..':'..r.sourceLabel)
updates[#updates+1]={weapon=found,row=r}
