for _,b in ipairs(r.nativeMuzzles) do matches=matches and bones[b] end
matches=matches and (r.nativeLabel==nil or w.name==r.nativeLabel)
for key,value in pairs(r.nativeMode) do
    if key=='damage' then
        -- The compiled FA artillery owner now emits retail 195; 100 is its
        -- known predecessor. No other damage value identifies this weapon.
        matches=matches and (w.damage==100 or w.damage==195)
    else
        matches=matches and (w[key] or 0)==value
    end
end
if matches and (w.projectileTemplate==r.oldProjectile or w.projectileTemplate==r.newProjectile) then
assert(not found,'Ambiguous source projectile weapon '..tp.general.tpId..':'..r.sourceLabel)
found=w
end
end
assert(found,'Source projectile weapon changed '..tp.general.tpId..':'..r.sourceLabel)
updates[#updates+1]={weapon=found,row=r}
end
for _,update in ipairs(updates) do local found,r=update.weapon,update.row
-- Commit retail damage only after every row and ambiguity check succeeds.
found.damage=195
found.projectileTemplate=r.newProjectile
found.scoFaProjectileIdentity={sourceIndex=r.sourceIndex,sourceLabel=r.sourceLabel,sourceProjectile=r.sourceProjectile,sourceBlueprintSha256=r.sourceBlueprintSha256}
end
end

end
end
