SCO_SourceFinalizers['uel4511'] = function(UnitTemplate)
if previous then previous(UnitTemplate) end
-- Fatboy's authored rest bones face straight out along the sides. FA TurretYaw
-- centers the firing arc; it must not also rotate Sanctuary's idle pose.
do
local tp = UnitTemplate
assert(tp.general.tpId == "uel4511", "Fatboy idle pose scope drift")
local marker = tp.additions and tp.additions.scoFatboyStraightIdle
assert(marker == nil or marker == true, "Fatboy idle pose marker drift")
local rows = {
    {label = "RightTurret01", bone = "Turret_Right01", yaw = -20, minimum = -120, maximum = 80},
    {label = "RightTurret02", bone = "Turret_Right02", yaw = 30, minimum = -80, maximum = 140},
    {label = "LeftTurret01", bone = "Turret_Left01", yaw = 20, minimum = -80, maximum = 120},
    {label = "LeftTurret02", bone = "Turret_Left02", yaw = -30, minimum = -140, maximum = 80},
}
local pending = {}
-- Validate all four owners before either aim policy or idle defaults can change.
for index, row in ipairs(rows) do
    local weapon = assert(tp.weapons and tp.weapons[index], "Fatboy idle weapon missing")
    local identity = weapon.scoFaProjectileIdentity
    local controllers = weapon.aimControllers
    local controller = controllers and controllers[1]
    assert(identity and identity.sourceIndex == index and identity.sourceLabel == row.label
        and weapon.projectileTemplate == "psf0154"
        and controllers and #controllers == 4
        and controller.aimBone == row.bone and controller.yawBone == row.bone
        and controller.pitchBone == nil and controller.defaultPitchAdjustment == nil
        and controller.yawMin == row.minimum and controller.yawMax == row.maximum
        and controller.yawSpeed == 50 and controller.poseResetTime == 3,
        "Fatboy idle yaw owner drift: " .. row.label)
    local expected = marker and 0 or row.yaw
    assert(controller.defaultYawAdjustment == expected,
        "Fatboy idle pose provenance drift: " .. row.label)
    pending[index] = controller
end

