do
local previous = SCO_SourceFinalizers['ugs1201']
SCO_SourceFinalizers['ugs1201'] = function(UnitTemplate)
if previous then previous(UnitTemplate) end
-- Tracer AA accuracy policy, scoped to its reviewed source projectile.
do
    local tp = UnitTemplate
    assert(tp.general.tpId == "ugs1201", "Tracer AA aim scope drift")
    local weapon
    for _, candidate in ipairs(tp.weapons or {}) do
        local identity = candidate.scoFaProjectileIdentity
        if identity and identity.sourceIndex == 1 and identity.sourceLabel == "AAGun" then
            assert(not weapon, "Duplicate Tracer AA source identity")
            assert(string.lower(identity.sourceBlueprintSha256)
                == "0460b42285f54f1b3cd041b431805ab8a0d54c1d6246c0ba26d6980156f19152",
                "Tracer AA projectile source drift")
            weapon = candidate
        end
    end
    assert(weapon and weapon.projectileTemplate == "psf0004"
        and weapon.rangeMin == 0 and weapon.rangeMax == 44
        and weapon.damage == 14 and weapon.reloadTime == 0.4
        and weapon.muzzleSalvoSize == 2 and weapon.muzzleSalvoDelay == 0.1
        and weapon.firingRandomness == 0
        and not weapon.scoTacticalOwned and not weapon.scoFaBombDrop
        and not weapon.scoFaHeadingArc and #(weapon.aimControllers or {}) == 1,
        "Tracer AA weapon drift")
    local aim = weapon.aimControllers[1]
    local originalAccuracy = aim.projectileSpeed == 45 and aim.aimTolerance == 0.5
        and aim.yawSpeed == 180 and aim.pitchSpeed == 180
    local improvedAccuracy = aim.projectileSpeed == 180 and aim.aimTolerance == 0.1
        and aim.yawSpeed == 720 and aim.pitchSpeed == 720
    local originalArc = aim.pitchMin == 0 and aim.pitchMax == 90
    local correctedArc = aim.pitchMin == -90 and aim.pitchMax == 0
    assert(aim.aimBone == "Turret_Muzzle_01" and aim.yawBone == "Turret"
        and aim.pitchBone == "Turret_Barrel" and aim.yawMin == -180
        and aim.yawMax == 180 and aim.leadTarget == true
        and aim.reduceMuzzleVelocityToTarget == false
        and (aim.defaultPitchAdjustment == 45 or aim.defaultPitchAdjustment == 0)
        and aim.solverType == "NoArc" and aim.aimGravity.x == 0
        and aim.aimGravity.y == 0 and aim.aimGravity.z == 0
        and (originalAccuracy or improvedAccuracy) and (originalArc or correctedArc),
        "Tracer AA aim identity drift")

    -- Imported Root reverses pitch: this arc raises the barrels physically.
    aim.pitchMin, aim.pitchMax = -90, 0
    -- Native NoArc already solves target velocity. Shorter flight limits the
    -- error from aircraft turning after launch; faster traverse follows passes.
    aim.projectileSpeed = 180
    aim.aimTolerance = 0.1
