local c={["sourceId"]="XSB2401",["targetId"]="uss4102",["weapons"]={["ExperimentalNuke"]={["sourceIndex"]=1,["sourceLabel"]="ExperimentalNuke",["targetClass"]=nil,["projectile"]="psf0136",["damage"]=0,["rangeMin"]=0,["rangeMax"]=20000,["reload"]=1.0,["interval"]=0.5,["muzzleVelocity"]=0,["muzzles"]={"Attachpoint"},["depthChargeRadius"]=nil,["counted"]=true}},["silo"]={["version"]="1.0.0",["sourceId"]="XSB2401",["role"]="launcher",["sourceStockpile"]=true,["autoIntercept"]=false,["sourceLabel"]="ExperimentalNuke",["initialAmmo"]=0,["maxAmmo"]=1,["buildPower"]=2160,["buildTime"]=129600,["cost"]={["alloys"]=600,["energy"]=6000},["projectile"]="psf0136",["muzzles"]={"Attachpoint"},["damage"]=0,["damageRadius"]=0,["rangeMin"]=0,["rangeMax"]=20000,["reload"]=1.0,["cycleReload"]=0,["muzzleVelocity"]=0,["deployDuration"]=0,["deployRate"]=10,["deployKey"]="sco_source_launch",["charge"]=5,["repackTimeout"]=32.5,["nukeRings"]={{["damage"]=1000001,["radius"]=45,["ticks"]=24,["totalTime"]=12},{["damage"]=7500,["radius"]=60,["ticks"]=20,["totalTime"]=5}},["launchAnimation"]=nil,["preserveAttack"]=false},["permanentOpen"]=nil}
tp.additions=tp.additions or {}
tp.general.orders=tp.general.orders or {};tp.general.toggles=tp.general.toggles or {}
tp.visuals=tp.visuals or {};tp.visuals.animations=tp.visuals.animations or {}
assert(tp.general.tpId==c.targetId and (not tp.additions.faSourceContract or tp.additions.faSourceContract.sourceId==c.sourceId),'Source interceptor template mismatch')
local previous=tp.additions.scoSourceInterception
if previous then assert(previous.sourceId==c.sourceId,'Conflicting source interceptor owner');for label,contract in pairs(previous.weapons or {}) do if not c.weapons[label] then c.weapons[label]=contract end end end
tp.additions.scoSourceInterception=c
for label,contract in pairs(c.weapons) do
local found
for _,w in ipairs(tp.weapons or {}) do
local expected,bones,count={}, {},0
for _,b in ipairs(contract.muzzles) do expected[string.lower(b)]=true end
for _,g in ipairs(w.muzzleGroups or {}) do for _,b in ipairs(g.muzzles or {}) do local key=string.lower(b);if not bones[key] then bones[key]=true;count=count+1 end end end
local matches=true;local expectedCount=0;for b in pairs(expected) do expectedCount=expectedCount+1;matches=matches and bones[b] end
matches=matches and count==expectedCount and (w.name==nil or w.name==label)
if matches then assert(not found,'Ambiguous source interceptor weapon');found=w end
end
assert(found,'Missing source interceptor weapon '..label);found.scoTacticalOwned=true;found.scoSourceInterceptionLabel=label
end
if c.permanentOpen then tp.visuals.animations[c.permanentOpen.key]=c.permanentOpen.animation end
tp.additions.scoStrategicSilo=nil
tp.additions.scoTactical=c.silo
tp.additions.faAnimationClosureWeaponDeploy=nil
tp.general.orders.StrategicManualLaunch=nil
tp.general.orders.ManualFire1=true
tp.general.orders.ManualFire2=not c.silo.autoIntercept or nil
if not c.silo.preserveAttack then tp.general.orders.Attack=nil;tp.general.orders.AttackMove=nil end
tp.general.toggles.Pause=false
tp.construction=tp.construction or {}
tp.construction.buildPower=c.silo.buildPower
if c.silo.launchAnimation then tp.visuals.animations[c.silo.deployKey]=c.silo.launchAnimation end
end

end
end
