do
local previous = SCO_SourceFinalizers['ucl4004']
SCO_SourceFinalizers['ucl4004'] = function(UnitTemplate)
if previous then previous(UnitTemplate) end
-- FA UAL0401 EyeWeapon uses PhasonLaserCollisionBeam's impact effect.
-- The endpoint carrier changes only ClientBeam's contact visual.
local tp = UnitTemplate
assert(tp.general and tp.general.tpId == "ucl4004",
    "Galactic Colossus Phason endpoint scope changed")

local weapons = tp.weapons
local eye = weapons and weapons[1]
assert(weapons and #weapons == 4
    and eye and eye.scoSourceLabel == "EyeWeapon"
    and (eye.projectileTemplate == "pad171" or eye.projectileTemplate == "pbf0004")
    and eye.beam and eye.beam.subMesh
    and eye.beamLifetime == -1
    and eye.damage == 500 and eye.rangeMax == 40
    and weapons[2] and weapons[2].scoSourceLabel == "RightArmTractor"
    and weapons[3] and weapons[3].scoSourceLabel == "LeftArmTractor",
    "Galactic Colossus EyeWeapon source contract changed")

if eye.projectileTemplate == "pbf0004" then return end
eye.projectileTemplate = "pbf0004"

end
end
