do
local previous = SCO_SourceFinalizers['uca1001']
SCO_SourceFinalizers['uca1001'] = function(UnitTemplate)
if previous then previous(UnitTemplate) end
-- Source muzzle FX for reviewed source weapon identities.
do
local tp=UnitTemplate
assert(tp.general.tpId=="uca1001",'Source muzzle scope drift')
for _,row in ipairs({ {
["nativeMuzzles"] = { "right_projectile" },
["path"] = "VFX/SCOM/Source/uca1001/muzzle_bomb.sanvfx",
["projectile"] = "pab101",
["sourceIndex"] = 1,
["sourceLabel"] = "Bomb",
} }) do
local found
for _,weapon in ipairs(tp.weapons or {}) do
local bones,count={},0
for _,group in ipairs(weapon.muzzleGroups or {}) do for _,bone in ipairs(group.muzzles or {}) do
local key=string.lower(bone);if not bones[key] then bones[key]=true;count=count+1 end
end end
local matches=count==#row.nativeMuzzles and weapon.projectileTemplate==row.projectile
for _,bone in ipairs(row.nativeMuzzles) do matches=matches and bones[bone] end
if matches then assert(not found,'Ambiguous source muzzle identity');found=weapon end
end
assert(found,'Source muzzle weapon changed '..tp.general.tpId..':'..row.sourceLabel)
found.effects=found.effects or {}
found.effects.onFire=row.path
found.effects.onFirePrefabID=nil
found.scoSourceMuzzle={sourceIndex=row.sourceIndex,sourceLabel=row.sourceLabel}
end
end

end
end
