-- XSL0305 retail script 6733fd88: mutually exclusive rifle modes.
do
local tp=UnitTemplate
local config={
["blueprintSha256"] = "97eee47e08938f6d4374c1a77c075d9bb2d19956d314bf1703a09f26ec0b628b",
["chargeSeconds"] = 0.5,
["defaultSniperMode"] = false,
["normalRange"] = 65,
["normalSpeed"] = 3,
["normalWeapon"] = "MainGun",
["scriptSha256"] = "6733fd88b40db73836ae7f8dbc744d1b80dd181e4c7ddd56dd8ff3af64560ad8",
["sniperRange"] = 75,
["sniperSpeed"] = 2.25,
["sniperWeapon"] = "SniperGun",
["sourceId"] = "XSL0305",
["targetId"] = "usl3801",
}
assert(tp.general.tpId=='usl3801','Sniper mode scope drift')
local cargo=tp.additions and tp.additions.scoCargo
assert(cargo and cargo.sourceId=='XSL0305','Sniper source identity drift')
assert(#tp.weapons==2,'Sniper weapon count drift')
local aliases={'SCO_SniperNormalMuzzle','SCO_SniperPrecisionMuzzle'}
local labels={'MainGun','SniperGun'}
local projectiles={'psf0172','psf0173'}
for index,weapon in ipairs(tp.weapons) do
    local identity=weapon.scoFaProjectileIdentity
    assert(identity and identity.sourceIndex==index and identity.sourceLabel==labels[index]
        and weapon.projectileTemplate==projectiles[index],'Sniper weapon identity drift')
    assert(#weapon.aimControllers==1 and #weapon.muzzleGroups==1
        and #weapon.muzzleGroups[1].muzzles==1,'Sniper muzzle topology drift')
    local aim=weapon.aimControllers[1]
    assert((aim.aimBone=='Muzzle' or aim.aimBone==aliases[index])
        and aim.yawBone=='Barrel' and aim.pitchBone=='Barrel'
        and (weapon.muzzleGroups[1].muzzles[1]=='Muzzle'
            or weapon.muzzleGroups[1].muzzles[1]==aliases[index]),'Sniper source bones drift')
    weapon.name=labels[index]
    aim.aimBone=aliases[index]
    aim.yawMin,aim.yawMax,aim.yawSpeed=-10,10,90
    aim.pitchMin,aim.pitchMax,aim.pitchSpeed=-50,50,30
    aim.aimTolerance=2
    weapon.muzzleGroups[1].muzzles={aliases[index]}
    weapon.muzzles={[aliases[index]]={aimController=aliases[index]}}
    weapon.muzzleSalvoDelay=0
    weapon.firingRandomness=0
end
tp.additions.scoSourceUnitModes=config
end

end
end
