if not c.legacyStaticVisual then
    assert(tp.visuals.animations.walk.sanAnimationPath=='Units/'..c.targetId..'/LOD0/'..c.targetId..'.sananimation',
        'Source generator animation asset identity drift')
end
local s=tp.additions.faSourceContract
if s then
    assert(s.sourceId==c.sourceId and string.lower(s.sourceBlueprintSha256)==c.sourceBlueprintSha256,
        'Seraphim generator source identity drift')
else
    tp.additions.faSourceContract={sourceId=c.sourceId,targetId=c.targetId,sourceBlueprint=c.sourceBlueprint,
        sourceBlueprintSha256=c.sourceBlueprintSha256,sourceScript=c.sourceScript}
end
-- The source callback owns Orb's acceleration; remove the former constant-speed owner.
if c.targetId=='uss3611' then
    local rotators=tp.additions.rotators or {}
    for index=#rotators,1,-1 do
        if rotators[index].boneName=='Orb' then table.remove(rotators,index) end
    end
    tp.additions.rotators=rotators
end
tp.additions.scoSourceSecondaryVisuals=c
end

end
end
do
local previous = SCO_SourceFinalizers['ugs3611']
SCO_SourceFinalizers['ugs3611'] = function(UnitTemplate)
if previous then previous(UnitTemplate) end
