                        weapon.scoCommanderEnhancementUnsupported = true
                        -- These source abilities use projectiles. A legacy beam
                        -- on the shared cannon muzzle would fire when its normal
                        -- weapon sends SetFiring, even while this weapon is off.
                        weapon.beam = nil
                        weapon.beamLifetime = nil
                    end
                end
            end
        end
        if SCOSupportTarget == "usl4002" then
            local labels = additions.scoCommanderEnhancementWeapons
            local primary = assert(weapons[labels.LightChronatronCannon], "SACU primary cannon missing")
            local dormant = assert(weapons[labels.OverCharge], "SACU Overcharge descriptor missing")
            assert(dormant.scoCommanderEnhancementUnsupported, "SACU shared muzzle owner changed")
            for _, weapon in ipairs({primary, dormant}) do
                assert(#weapon.muzzleGroups == 1 and #weapon.muzzleGroups[1].muzzles == 1
                    and weapon.muzzleGroups[1].muzzles[1] == "Right_Arm_Muzzle",
