            -- Its unused manual owner must retain the live cannon's flash/audio.
            dormant.effects, dormant.audio = primary.effects, primary.audio
        end
        defence = defence or {}
        defence.shields = defence.shields or {}
        general.toggles = general.toggles or {}
        -- Shield descriptors are indexed and their enhancement map stores
        -- those indexes. Sort the discovered IDs before appending so Lua hash
        -- iteration cannot reorder live shield ownership between builds.
        local shieldEnhancementOrder = {}
        for id, rule in pairs(SCOSupportContract.enhancements) do
            if rule.effects.shield then
                table.insert(shieldEnhancementOrder, id)
            end
        end
        table.sort(shieldEnhancementOrder)
        for _, id in ipairs(shieldEnhancementOrder) do
            local rule = SCOSupportContract.enhancements[id]
            local shield = rule.effects.shield
            local shieldId = general.tpId .. "_" .. id
            local radius = shield.sanctuaryRadius
            table.insert(defence.shields, {
                scoCommanderEnhancementShieldId=shieldId,
                entityName="SCOShield_"..id, boneName="Root", name=rule.name,
                type="Bubble", max=1, value=1, regen=0, regenDelay=1,
                rechargeTime=5, rechargeHPRatio=1,
                radii={x=radius,y=radius,z=radius},
                offset={x=0,y=shield.verticalOffset,z=0},
            })
            additions.scoCommanderEnhancementShields[shieldId] = #defence.shields
            general.toggles.Shield = true
        end
        construction = construction or {}
        construction.buildPower = SCOSupportContract.base.buildRate
        if not construction.canBuild then
