            construction.range = construction.range or 5
        end
        general.orders = general.orders or {}
        general.orders.Capture, general.orders.Repair, general.orders.Harvest = true, true, true
    end
    UnitTemplate.additions = additions
    UnitTemplate.defence = defence
    UnitTemplate.construction = construction
