uildTime"]=7500,["Icon"]="sp",["ImpactEffects"]="SeraphimShieldHit01",["MaintenanceConsumptionPerSecondEnergy"]=300,["Name"]="<LOC enhancements_0028>Personal Shield Generator",["OwnerShieldMesh"]="/units/xsl0301/xsl0301_personalshield_mesh",["RegenAssistMult"]=10,["ShieldEnergyDrainRechargeTime"]=5,["ShieldMaxHealth"]=25000,["ShieldRechargeTime"]=160,["ShieldRegenRate"]=22,["ShieldRegenStartTime"]=1,["ShowBones"]={"Back_Upgrade"},["Slot"]="Back",["UpgradeEffectBones"]={"Back_Upgrade"},["UpgradeUnitAmbientBones"]={"Torso"}},["removal"]={["BuildCostEnergy"]=1,["BuildCostMass"]=1,["BuildTime"]=0.1,["HideBones"]={"Back_Upgrade"},["Icon"]="sp",["Name"]="<LOC enhancements_0147>Remove Personal Shield Generator",["Prerequisite"]="Shield",["RemoveEnhancements"]={"Shield","ShieldRemove"},["Slot"]="Back"}},["description"]="Personal shield: 25000 health, 22 regeneration per second, 300 energy upkeep."},["Teleporter"]={["id"]="Teleporter",["name"]="Personal Teleporter",["icon"]="pqt",["slot"]="RCH",["cost"]={["mass"]=15000,["energy"]=1500000,["buildTime"]=18000},["removal"]={["id"]="TeleporterRemove",["name"]="Remove Personal Teleporter",["cost"]={["mass"]=1,["energy"]=1,["buildTime"]=0.1}},["remove"]={"Teleporter","TeleporterRemove"},["conflicts"]={"Overcharge"},["effects"]={["teleport"]={["energy"]=292500.0,["mass"]=0,["time"]=29.25,["energyModifier"]=2.5,["massModifier"]=0,["timeModifier"]=0.0001,["energyPerSecond"]=10000.0}},["limitations"]={},["capabilities"]={["add"]={},["remove"]={},["toggles"]={}},["visual"]={["show"]={"Back_Upgrade"},["hide"]={}},["source"]={["blueprint"]={["BuildCostEnergy"]=1500000,["BuildCostMass"]=15000,["BuildTime"]=18000,["Icon"]="pqt",["MaintenanceConsumptionPerSecondEnergy"]=10000,["Name"]="<LOC enhancements_0035>Personal Teleporter",["ShowBones"]={"Back_Upgrade"},["Slot"]="RCH",["UpgradeEffectBones"]={"Right_Arm_Muzzle","Right_Arm_Barrel"},["UpgradeUnitAmbientBones"]={"Torso"}},["removal"]={["BuildCostEnergy"]=1,["BuildCostMass"]=1,["BuildTime"]=0.1,["HideBones"]={"Back_Upgrade"},["Icon"]="pqt",["Name"]="<LOC enhancements_0036>Remove Personal Teleporter",["Prerequisite"]="Teleporter",["RemoveEnhancements"]={"Teleporter","TeleporterRemove"},["Slot"]="RCH"}},["description"]="Enables targeted teleportation. Each jump consumes 292500 energy over 29.25 seconds at full power."}},["visualSlots"]={["LCH"]={},["Back"]={},["RCH"]={}},["defaultHiddenBones"]={"Back_Upgrade"},["supportCommander"]=true,["sourceBlueprint"]={["archive"]="units.scd",["entry"]="units/XSL0301/XSL0301_unit.bp",["sha256"]="c450b8186498025b31daaf54936cc0ab75b463a23813c7e4d897f8b4bf36fb15",["bytes"]=28647},["sourceScript"]={["archive"]="units.scd",["entry"]="units/XSL0301/XSL0301_script.lua",["sha256"]="e9f482bda409b3ba8d2b608d57cecad6cde7c2692068800fbfc238f2d2491d93",["bytes"]=13906}}
-- Final template owner, after source weapon identity and faction prefab owners.
local general = assert(UnitTemplate and UnitTemplate.general, "SACU template argument missing")
local additions, weapons = UnitTemplate.additions, UnitTemplate.weapons
local defence, construction = UnitTemplate.defence, UnitTemplate.construction
-- XSL0301 is TECH3. The native donor's TECH4 tag hides it on the T3 gate's
-- initial menu and makes a queued SACU look like a factory upgrade.
local tierMarker = additions and additions.scoSupportCommanderTech
local tier3, tier4 = 0, 0
local tags = assert(UnitTemplate.tags, "Seraphim SACU tags missing")
for _, tag in ipairs(tags) do
    if tag == "TECH3" then tier3 = tier3 + 1 end
    if tag == "TECH4" then tier4 = tier4 + 1 end
end
assert(SCOSupportTarget == "usl4002" and SCOSupportContract.sourceId == "XSL0301"
    and SCOSupportContract.sourceBlueprint.sha256 == "c450b8186498025b31daaf54936cc0ab75b463a23813c7e4d897f8b4bf36fb15"
    and table.find(tags, "SCFA_TECH3") and table.find(tags, "SCFA_SUBCOMMANDER")
    and table.find(tags, "SCFA_BUILTBYQUANTUMGATE")
    and ((tierMarker == nil and tier3 == 0 and tier4 == 1)
        or (tierMarker == "1.0.0" and tier3 == 1 and tier4 == 0)),
    "Seraphim SACU source tier drifted")
if general and SCOSupportContract and general.tpId then
    if general.tpId ~= SCOSupportTarget then error("SACU template routing mismatch") end
    additions = additions or {}
    if additions.faSourceContract and additions.faSourceContract.sourceId
        and additions.faSourceContract.sourceId ~= SCOSupportContract.sourceId then
        error("SACU source identity mismatch")
    end
    if additions.scoSupportCommanderEnhancements ~= true then
        additions.scoSupportCommanderEnhancements = true
        additions.scoCommanderEnhancements = {
            version = "1.0.0", sourceId = SCOSupportContract.sourceId,
            faction = SCOSupportContract.faction,
        }
        additions.scoCommanderEnhancementWeapons = {}
        additions.scoCommanderEnhancementShields = {}
        for index, weapon in ipairs(weapons or {}) do
            local source = weapon.scoFaSourceWeapon
            local identity = weapon.scoFaProjectileIdentity
            local label = source and source.Label or identity and identity.sourceLabel
            if label then
                if additions.scoCommanderEnhancementWeapons[label] then
                    error("Duplicate SACU source weapon label: " .. label)
                end
                additions.scoCommanderEnhancementWeapons[label] = index
                local required = ({NMissile="NaniteMissileSystem", OverCharge="Overcharge", Missile="Missile"})[label]
                if required then
                    weapon.scoCommanderEnhancementRequired = required
                    if label == "OverCharge" or label == "Missile" then
                        -- The manual ability owner dispatches the source missile.
                        -- Native ordinary attack must never fire either weapon.
                        weapon.scoCommanderEnhancementUnsupported = true
                        -- These source abilities use projectiles. A legacy beam
                        -- on the shared cannon muzzle would fire when its normal
                        -- weapon sends SetFiring, even while this weapon is off.
                        weapon.beam = nil
                        weapon.beamLifetime = nil
                    end
                end
            end
        end
        if SCOSupportTarget == "usl4002" then
            local labels = additions.scoCommanderEnhancementWeapons
            local primary = assert(weapons[labels.LightChronatronCannon], "SACU primary cannon missing")
            local dormant = assert(weapons[labels.OverCharge], "SACU Overcharge descriptor missing")
            assert(dormant.scoCommanderEnhancementUnsupported, "SACU shared muzzle owner changed")
            for _, weapon in ipairs({primary, dormant}) do
                assert(#weapon.muzzleGroups == 1 and #weapon.muzzleGroups[1].muzzles == 1
                    and weapon.muzzleGroups[1].muzzles[1] == "Right_Arm_Muzzle",
                    "SACU shared cannon muzzle changed")
            end
            -- Native client registration keeps the last descriptor for a bone.
            -- Its unused manual owner must retain the live cannon's flash/audio.
            dormant.effects, dormant.audio = primary.effects, primary.audio
        end
        defence = defence or {}
        defence.shields = defence.shields or {}
        general.toggles = general.toggles or {}
        -- Shield descriptors are indexed and their enhancement map stores
        -- those indexes. Sort the discovered IDs before appending so Lua hash
        -- iteration cannot reorder live shield ownership between builds.
        local shieldEnhancementOrder = {}
        for id, rule in pairs(SCOSupportContract.enhancements) do
            if rule.effects.shield then
                table.insert(shieldEnhancementOrder, id)
            end
        end
        table.sort(shieldEnhancementOrder)
        for _, id in ipairs(shieldEnhancementOrder) do
            local rule = SCOSupportContract.enhancements[id]
            local shield = rule.effects.shield
            local shieldId = general.tpId .. "_" .. id
            local radius = shield.sanctuaryRadius
            table.insert(defence.shields, {
                scoCommanderEnhancementShieldId=shieldId,
                entityName="SCOShield_"..id, boneName="Root", name=rule.name,
                type="Bubble", max=1, value=1, regen=0, regenDelay=1,
                rechargeTime=5, rechargeHPRatio=1,
                radii={x=radius,y=radius,z=radius},
                offset={x=0,y=shield.verticalOffset,z=0},
            })
            additions.scoCommanderEnhancementShields[shieldId] = #defence.shields
            general.toggles.Shield = true
        end
        construction = construction or {}
        construction.buildPower = SCOSupportContract.base.buildRate
        if not construction.canBuild then
            local faction = ({Aeon="CHOSEN", UEF="EDA", Cybran="GUARD", Seraphim="SERAPHIM"})[SCOSupportContract.faction]
            construction.canBuild = "Tags."..faction.." * Tags.BUILDABLE_BY_T3_ENGINEER"
            construction.range = construction.range or 5
        end
        general.orders = general.orders or {}
        general.orders.Capture, general.orders.Repair, general.orders.Harvest = true, true, true
    end
    UnitTemplate.additions = additions
    UnitTemplate.defence = defence
    UnitTemplate.construction = construction
end

if tierMarker == nil then
    tags[assert(table.find(tags, "TECH4"))] = "TECH3"
    additions.scoSupportCommanderTech = "1.0.0"
end
-- ReadUnitTemplate indexed the donor tags before this final prefab policy.
Tags.TECH4[general.tpId] = nil
Tags(UnitTemplate)
end

end
end
