-- Reviewed engineer menus and source-matched platform for stationary air factories.
do
local tp=UnitTemplate
local c={["canBuild"]="Tags.CHOSEN * Tags.BUILDABLE_BY_T1_FACTORY * ((Tags.AIR * Tags.MOBILE) + Tags.AIR_FACTORY + Tags.ENGINEER)",["className"]={"unitsDefaultChosen","AeonPortAirFactory"},["engineers"]={"ucl1501"},["faction"]="CHOSEN",["originalCanBuild"]="Tags.CHOSEN * Tags.BUILDABLE_BY_T1_FACTORY * ((Tags.AIR * Tags.MOBILE) + Tags.AIR_FACTORY + Tags.ENGINEER)",["platformBoneName"]="Attachpoint",["platformEvidence"]={["bone"]="Attachpoint",["path"]="Units/ucs1512/LOD0/ucs1512.sanskeleton",["sha256"]="b066c64a4dd3b2433eef0bd44f424dbcc47a927d746ed10dc95d6db7081a82fb"},["sourceBlueprint"]={["archive"]="units.scd",["bytes"]=9869,["entry"]="units/UAB0102/UAB0102_unit.bp",["sha256"]="9b5583fba065681bed436f0777ab1e6187c10dda2da0e99e20b934aaa7bd84d8"},["sourceBuildableCategories"]={"BUILTBYTIER1FACTORY AEON MOBILE CONSTRUCTION","BUILTBYTIER1FACTORY AEON STRUCTURE AIR","BUILTBYTIER1FACTORY AEON MOBILE AIR","TRANSPORTBUILTBYTIER1FACTORY AEON MOBILE AIR"},["sourceId"]="UAB0102",["sourceScript"]={["archive"]="units.scd",["bytes"]=526,["entry"]="units/UAB0102/UAB0102_script.lua",["sha256"]="2663ae2ff8675ef8653e7cad199338b1c019bc7d8ca06da2958d92e2b77a7461"},["standardEngineers"]={"ucl1501"},["targetId"]="ucs1512",["tier"]=1,["upgradesTo"]="ucs2512",["version"]=1}
assert(tp.general.tpId==c.targetId,'Factory engineer target drift')
assert(tp.general.class[1]==c.className[1] and tp.general.class[2]==c.className[2],'Factory engineer class drift')
local tags={};for _,tag in ipairs(tp.tags) do tags[tag]=true end
assert(tags[c.faction] and tags.AIR_FACTORY and tags.STRUCTURE and tags['TECH'..c.tier],'Factory engineer role drift')
local build=assert(tp.construction,'Factory construction absent')
assert(build.upgradesTo==c.upgradesTo,'Factory upgrade chain drift')
assert(build.canBuild==c.originalCanBuild or build.canBuild==c.canBuild,'Factory build choices drift')
assert(build.platformBoneName==nil or build.platformBoneName==c.platformBoneName,'Factory platform ownership drift')
tp.additions=tp.additions or {}
local source=tp.additions.faSourceContract
if source then
    assert(source.sourceId==c.sourceId and string.lower(source.sourceBlueprintSha256)==string.lower(c.sourceBlueprint.sha256),'Factory source identity drift')
end
build.canBuild=c.canBuild
build.platformBoneName=c.platformBoneName
tp.additions.scoFactoryEngineerEgress=c
end

end
end
