local tags={};for _,tag in ipairs(tp.tags) do tags[tag]=true end
assert(tags[c.faction] and tags.AIR_FACTORY and tags.STRUCTURE and tags['TECH'..c.tier],'Factory engineer role drift')
local build=assert(tp.construction,'Factory construction absent')
assert(build.upgradesTo==c.upgradesTo,'Factory upgrade chain drift')
assert(build.canBuild==c.originalCanBuild or build.canBuild==c.canBuild,'Factory build choices drift')
assert(build.platformBoneName==nil or build.platformBoneName==c.platformBoneName,'Factory platform ownership drift')
tp.additions=tp.additions or {}
local source=tp.additions.faSourceContract
if source then
    assert(source.sourceId==c.sourceId and string.lower(source.sourceBlueprintSha256)==string.lower(c.sourceBlueprint.sha256),'Factory source identity drift')
end
build.canBuild=c.canBuild
build.platformBoneName=c.platformBoneName
tp.additions.scoFactoryEngineerEgress=c
end

end
end
