-- Mirror the native naval fallback roll-off with the reflected rig.
do
local construction = UnitTemplate.construction
local points = construction and construction.rollOffPoints
if points then
    for _, point in ipairs(points) do
        local offset = point.offset
        if offset and (offset.z == 8 or offset.z == -8)
            and (offset.x == 3 or offset.x == -3)
            and (point.unitSpin == 0 or point.unitSpin == 180) then
            offset.x = -3
        end
    end
end
end

end
