-- SCOM storage capacity for Forged Alliance starting resources 1.0.0
local function SCO_ApplyCommanderStorage(tp)
    local id = tp.general.tpId
    if id == 'uel0000' or id == 'ucl0000' or id == 'ugl0000' or id == 'usl0000' then
        tp.economy.initial = { alloys = 650, energy = 4000 }
        local storage = tp.economy.storage or {}
        storage.alloys = math.max(storage.alloys or 0, 650)
        storage.energy = math.max(storage.energy or 0, 4000)
        tp.economy.storage = storage
    end
end

