["usa1701"] = "vcd3101_death_air_small",
}
function SCO_ApplyAirDeathVisuals(tp)
    local id = tp.general and tp.general.tpId
    local name = scoAirDeathPaths[id]
    if not name then return tp end
    local original = 'VFX/Death/' .. name .. '.sanvfx'
    local replacement = 'VFX/SCOM/Death/' .. name .. '.sanvfx'
    local effects = assert(tp.visuals and tp.visuals.effectsInstant,
        'SCFA air death effect table missing: ' .. id)
    local matches = 0
    for _,event in ipairs({'onDeath','onImpact'}) do
        for _,effect in ipairs(effects[event] or {}) do
            if effect.particleName == original or effect.particleName == replacement then
                effect.particleName = replacement
                matches = matches + 1
            end
        end
    end
    assert(matches > 0, 'SCFA air death graph owner changed: ' .. id)
    return tp
end

