    ["VFX/SCOM/FieldFixes/AeonDeathSmoke/vcd3301_death_air_large.sanvfx"] = "VFX/SCOM/AeonExplosions/vcd3301_death_air_large.sanvfx",
    ["VFX/Death/vcd1101_death_land_small.sanvfx"] = "VFX/SCOM/AeonExplosions/vcd1101_death_land_small.sanvfx",
}

function SCO_ApplyAeonDeathSmokeVisuals(tp)
    local isAeon = false
    for _, tag in ipairs(tp.tags or {}) do
        if tag == "SCFA_AEON" or tag == "CHOSEN" then
            isAeon = true
            break
        end
    end
    if not isAeon then
        return tp
    end
    if not tp.visuals then
        return tp
    end
    local effects = tp.visuals.effectsInstant
    if not effects then
        effects = {}
        tp.visuals.effectsInstant = effects
    end
    -- Some imported units have no death effect. Use the existing faction
    -- blast for their domain; normal death callbacks still own when it plays.
    if not effects.onDeath or #effects.onDeath == 0 then
        local particleName = "VFX/SCOM/AeonExplosions/vcd1101_death_land_small.sanvfx"
        for _, tag in ipairs(tp.tags or {}) do
            if tag == "AIR" then
                particleName = "VFX/SCOM/AeonExplosions/vcd3101_death_air_small.sanvfx"
                break
            elseif tag == "STRUCTURE" then
                particleName = "VFX/SCOM/AeonExplosions/vcd2101_death_building_small.sanvfx"
                break
            end
        end
        effects.onDeath = {{particleName = particleName, boneName = "Root"}}
    end
    for _, event in ipairs({"onDeath", "onImpact"}) do
        for _, effect in ipairs(effects[event] or {}) do
            local replacement =
                scoAeonDeathSmokePaths[effect.particleName]
            if replacement then
                effect.particleName = replacement
            end
        end
    end
    return tp
end

