local scoCommanderMuzzles = {
["ugl0000"] = {
["bone"] = "Turret_Muzzle_02",
["original"] = "VFX/CybranAcuProjectiles/Muzzle/vcm1203_cannon_plasma_medium_muzzle.sanvfx",
["projectile"] = "psf0166",
["replacement"] = "VFX/SCOM/Commanders/Cybran/muzzle.sanvfx",
},
["usl0000"] = {
["bone"] = "Right_Turret_Muzzle",
["original"] = "VFX/Muzzle/vcm1203_cannon_plasma_medium_muzzle.sanvfx",
["projectile"] = "psf0169",
["replacement"] = "VFX/SCOM/Commanders/Seraphim/muzzle.sanvfx",
},
}
function SCO_ApplyCommanderMuzzleVisuals(tp)
    local id = tp.general and tp.general.tpId
    local row = scoCommanderMuzzles[id]
    if not row then return tp end
    local weapon = assert(tp.weapons and tp.weapons[1], 'Commander muzzle weapon missing: ' .. id)
    assert(weapon.projectileTemplate == row.projectile, 'Commander projectile owner changed: ' .. id)
    local muzzles = weapon.muzzleGroups and weapon.muzzleGroups[1] and weapon.muzzleGroups[1].muzzles
    assert(muzzles and #muzzles == 1 and muzzles[1] == row.bone,
        'Commander firing bone changed: ' .. id)
    local effects = assert(weapon.effects, 'Commander muzzle effects missing: ' .. id)
    assert(effects.onFire == row.original or effects.onFire == row.replacement,
        'Commander muzzle source changed: ' .. id)
    effects.onFire = row.replacement
    return tp
end

-- Atlantis aircraft storage is opt-in and never makes aircraft ground cargo.
local function SCO_ApplyAtlantisCarrier(tp)
    local tags = {}
    for _, tag in ipairs(tp.tags or {}) do tags[tag] = true end
    if tags.AIR and tags.MOBILE and not tags.TECH4 and not tags.TECH5 then
        tp.additions = tp.additions or {}
        local cargo = tp.additions.scoCargo or {
            portable = false, cargoClass = 1, slots = {}, canFire = false,
            attachOffset = {0, 0, 0}, unfoldDuration = 0,
        }
        cargo.airPortable = true
        tp.additions.scoCargo = cargo
    end
    if tp.general.tpId ~= "uen4001" then return end
    tp.additions = tp.additions or {}
    tp.construction = {
        buildPower = 240, range = 30,
        canBuild = "Tags.EDA * Tags.AIR * Tags.MOBILE * Tags.BUILDABLE_BY_T3_FACTORY",
        rollOffPoints = {{offset = {x = 0, y = 0, z = 0},
            platformOffset = {x = 0, y = 0, z = 0}, unitSpin = 0, rollOffTime = 0}},
    }
    local slots = {}
    for index = 1, 150 do
        slots[index] = {bone = "Root", cargoClass = 1, occupies = {index}}
    end
    tp.additions.scoCargo = {airStorage = true, portable = false, slots = slots,
        cargoClass = 10, canFire = false, attachOffset = {0, 0, 0}}
    if tp.additions.seaParityUnsupported then
        tp.additions.seaParityUnsupported.carrierDeck = nil
    end
end

-- SCOM source surface-carrier production 1.0.0.
local SCOSurfaceCarrierSpecs = {
    ucs2803 = {source = "UAS0303", faction = "AEON", class = "SCOMAeonCarrier",
        predecessor = "AeonPortNavalUnit", slots = 60},
    ugn3003 = {source = "URS0303", faction = "CYBRAN", class = "SCOMCybranCarrier",
        predecessor = "GuardNavalUnit", slots = 50},
    usn3003 = {source = "XSS0303", faction = "SERAPHIM", class = "SCOMSeraphimCarrier",
        predecessor = "SeraphimNavalUnit", slots = 60},
}
local SCOSurfaceCarrierPrevious = SCO_ApplyAtlantisCarrier
SCO_ApplyAtlantisCarrier = function(tp)
    SCOSurfaceCarrierPrevious(tp)
    local spec = SCOSurfaceCarrierSpecs[tp.general.tpId]
    if not spec then return end
    local tags = {}
    for _, tag in ipairs(tp.tags or {}) do tags[tag] = true end
    assert(tags["SCFA_" .. spec.faction] and tags.SCFA_NAVALCARRIER,
        "Surface carrier source category identity drifted")
    local source = tp.additions and tp.additions.faSourceContract
    -- The shipped Seraphim builder has source categories, but no faSourceContract.
    assert((source and source.sourceId == spec.source)
        or (not source and spec.source == "XSS0303"), "Surface carrier source identity drifted")
    assert(tp.general.class[2] == spec.predecessor
        or (tp.additions.scoSourceSurfaceCarrier == 1 and tp.general.class[2] == spec.class),
        "Surface carrier predecessor class drifted")
    local construction = assert(tp.construction, "Surface carrier construction contract missing")
    assert(construction.buildPower == 150
        or (construction.buildPower == nil and spec.source == "URS0303"),
        "Surface carrier source build rate drifted")
    local unsupported = assert(tp.additions.seaParityUnsupported,
        "Surface carrier predecessor gate missing")
    assert(unsupported.carrierDeck == true or tp.additions.scoSourceSurfaceCarrier == 1,
        "Surface carrier predecessor state changed")
    tp.general.class = {"scoAtlantisCarrier", spec.class}
    tp.general.orders = tp.general.orders or {}
    tp.general.orders.Transport = true
    tp.general.toggles = tp.general.toggles or {}
    tp.general.toggles.RepeatBuild = false
    construction.buildPower = 150
    construction.range = 30
    construction.canBuild = "Tags.SCFA_BUILTBYTIER3FACTORY * Tags.SCFA_" .. spec.faction
        .. " * Tags.SCFA_MOBILE * Tags.SCFA_AIR * (Tags.SCFA_ANTINAVY + Tags.SCFA_INTELLIGENCE + Tags.SCFA_ANTIAIR)"
    construction.rollOffPoints = {{offset = {x = 0, y = 0, z = 0},
        platformOffset = {x = 0, y = 0, z = 0}, unitSpin = 0, rollOffTime = 0}}
    local slots = {}
    for index = 1, spec.slots do
        slots[index] = {bone = "Root", cargoClass = 1, occupies = {index}}
    end
    tp.additions.scoCargo = {airStorage = true, portable = false, slots = slots,
        cargoClass = 10, canFire = false, attachOffset = {0, 0, 0}}
    tp.additions.scoSourceSurfaceCarrier = 1
    unsupported.carrierDeck = nil
end

function SCO_SourceFinalizeTemplate(tp)
    local finalizer = SCO_SourceFinalizers[tp.general.tpId]
    if finalizer then finalizer(tp) end
    SCO_ApplyCommanderStorage(tp)
    SCO_ApplyAirDeathVisuals(tp)
    SCO_ApplyAeonDeathSmokeVisuals(tp)
    SCO_ApplyStructureAnimationPolicy(tp)
    SCO_ApplySourceUpgradeLinks(tp)
    SCO_ApplySourceWeaponAudio(tp)
    Import('common/systems/scoSourceSubmarineTargeting.lua').PrepareTemplate(tp)
    SCO_ApplyTorpedoWeapons(tp)
    SCO_ApplyCommanderMuzzleVisuals(tp)
    SCO_ApplyAtlantisCarrier(tp)
    -- Restrict replacement-faction construction after every source rewrite.
    local tags = {}
    for _, tag in ipairs(tp.tags or {}) do tags[tag] = true end
    if not tags.PROMETHEAN and (tags.EDA or tags.CHOSEN or tags.GUARD or tags.SERAPHIM) then
        if not tags.SCFA_ALLUNITS and tp.general.tpId ~= 'ucl9505' then
            Import('common/units/availableUnits.lua').AvailableUnits[tp.general.tpId] = nil
        end
        local construction = tp.construction
        if construction and construction.canBuild ~= nil then
            assert(type(construction.canBuild) == 'string', 'Invalid SCOM construction category')
            local suffix = ' * Tags.SCFA_ALLUNITS'
            if construction.canBuild:sub(-#suffix) ~= suffix then
                construction.canBuild = '(' .. construction.canBuild .. ')' .. suffix
            end
        end
    end
    SCO_IdleResetFinalizeSourceTemplate(tp)
    SCO_FieldFixPostSourceUnitCorrections(tp)
    -- SCOM Fatboy private template module 1.0.0
    if tp.general.tpId == "uel4511" then
        local candidate, applied = SCOMUnitLibrary.ConfigureTemplate(tp, "scom/units/uel4511/template.lua")
        if applied then
            -- Native class and range registries retain these immutable branches.
            candidate.general = tp.general
            candidate.ranges = tp.ranges
            -- Preserve the original template object held by the native loader.
            -- Validation finished on a detached candidate; this commit cannot yield.
            for key in pairs(tp) do tp[key] = nil end
            for key, value in pairs(candidate) do tp[key] = value end
        end
    end
end
-- Final pre-prefab policy for 356 mapped FA STRUCTURE sources (340 composed).
