-- These source event clips were incorrectly installed as continuous idle motion.
local EventIdle = {
uss1702 = {"AnimUpgrade", "source_animupgrade"}, -- XSB3102: Display.AnimationUpgrade
uss2711 = {"AnimActivate", "source_animactivate"}, -- XSB4203: Display.AnimationPermOpen
uss3102 = {"AnimOpen", "fa_deploy"}, -- XSB2305: WeaponUnpackAnimation
