function SCO_ApplyStructureAnimationPolicy(tp)
local id = tp.general and tp.general.tpId
local source = Sources[id]
if not source then return end
if id == "ucs2806" then
-- HostUnit copies this table before the Aeon fabricator animation starts.
tp.general.toggles = tp.general.toggles or {}
tp.general.toggles.Production = true
end
local animations = tp.visuals and tp.visuals.animations
if not animations then return end
local policy = Bindings[id] or {}
local event = EventIdle[id]
for key, animation in pairs(animations) do
local rule = policy[key]
if animation.clipName ~= "Rest" then
assert(rule and animation.clipName == rule[1],
"SCOM unaudited structure animation: " .. id .. "/" .. key)
end
if key == "scoSourceDeath01" then
local config = tp.additions and tp.additions.scoSourceDeath
local variant = config and config.variants and config.variants[1]
assert(config and config.sourceId == source and #config.variants == 1
and variant.key == key and variant.durationSeconds > 0
and variant.weight > 0 and variant.rateMin > 0
and variant.rateMax >= variant.rateMin and rule[2] == Clamp,
"SCOM structure source death contract drifted: " .. id)
end
end
if event then
local idle = assert(animations.walk, "SCOM event structure has no idle pose: " .. id)
assert(idle.clipName == event[1] or idle.clipName == "Rest",
"SCOM structure idle clip changed: " .. id)
if idle.clipName ~= "Rest" then
if not animations[event[2]] then
animations[event[2]] = {clipName = idle.clipName,
sanAnimationPath = idle.sanAnimationPath, playbackMode = Clamp}
end
animations.walk = {clipName = "Rest", sanAnimationPath = idle.sanAnimationPath,
playbackMode = Clamp}
end
end
for key, animation in pairs(animations) do
animation.playbackMode = animation.clipName == "Rest" and Clamp or policy[key][2]
end
if id == "uss1702" then
-- XSB3102's 45-frame source upgrade is sampled by the existing HostUnit bridge.
assert(tp.construction and tp.construction.upgradesTo == "uss2702",
"SCOM Seraphim sonar upgrade target changed")
tp.additions = tp.additions or {}
tp.additions.progressBoundUpgradeAnimation = {
animationKey = "source_animupgrade", durationSeconds = 1.4666666984558105,
restAnimationKey = "walk",
}
animations.source_animupgrade.authoredSpeed = 1
elseif id == "ucs1614" then
-- UAB1102 AnimationPermOpen: the existing Aeon completion owner holds the endpoint.
tp.additions = tp.additions or {}
tp.additions.aeonStructureMotion = {
version = "1.0.2", kind = "permanent_open", rotatorCount = 0,
mapping = "UAB1102 -> ucs1614",
sourceBlueprint = "units/UAB1102/UAB1102_unit.bp",
sourceBlueprintSha256 = "226e38c51f687f906d0d30ba449d032223b40eed65aaff7bb8c0607b021f25b6",
sourceScript = "units/UAB1102/UAB1102_script.lua",
sourceScriptSha256 = "2f154a0ac97bbbce7193a468cb2eae0fb676480cffcde2071690912f0f91247a",
primaryClip = {key = "source_animopen", name = "AnimOpen",
durationSeconds = 2.4000000953674316, rate = 1},
}
end
end

-- SCOM Optional Packs opt2: repair only an invalid add-on construction-beam attachment.
-- Prefer a declared endpoint that exists in this prefab; otherwise use its verified
-- head entity. Never invent bones, skip a unit, or turn a prefab error into success.
function SCO_OptionalConstructionBeam(tp, prefab)
local id = tp.general and tp.general.tpId
if type(id) ~= 'string' or not (id:match('^w%a%a%d+$') or id:match('^sc2r_')) then return end
local construction = tp.construction
local config = type(construction) == 'table' and construction.beam
if type(config) ~= 'table' then return end
local names = {}
for _, entity in ipairs(prefab.hierarchyTemplate.entities) do
assert(not names[entity.entityName], 'SCOM opt2: duplicate prefab entity for '..id)
names[entity.entityName] = entity
end
local beam = names['Construction Beam']
if not beam or type(beam.parentEntityName) ~= 'string' or beam.parentEntityName == ''
or names[beam.parentEntityName] then return end
local old = beam.parentEntityName
local head = TemplateHeadEntityName
local function valid(name)
local seen = {}
while type(name) == 'string' and names[name] and not seen[name] and name ~= 'Construction Beam' do
if name == head then
local parent = names[name].parentEntityName
return parent == nil or parent == ''
end
seen[name] = true
name = names[name].parentEntityName
end
return false
end
local additions = tp.additions
local bones = type(additions) == 'table' and additions.buildBeamBones
local endpoints, changed = {}, false
if type(bones) == 'table' then
for _, bone in ipairs(bones) do
if valid(bone) then endpoints[#endpoints+1] = bone else changed = true end
end
end
local target = valid(config.boneName) and config.boneName or endpoints[1]
if not target and valid(head) then target = head end
assert(target, 'SCOM opt2: no valid construction-beam fallback for '..id)
-- Copy-on-write: packs may share construction/additions tables with a donor.
local function copy(value)
local result = {}
for key, entry in pairs(value) do result[key] = entry end
local mt = getmetatable(value)
if type(mt) == 'table' then setmetatable(result, mt) end
return result
end
local replacement = copy(construction)
local newConfig = copy(config)
rawset(newConfig, 'boneName', target)
rawset(newConfig, 'offset', {x=0, y=0, z=0})
rawset(replacement, 'beam', newConfig)
local newAdditions
if type(bones) == 'table' and (changed or #bones == 0) then
if #endpoints == 0 then endpoints[1] = target end
newAdditions = copy(additions)
rawset(newAdditions, 'buildBeamBones', endpoints)
end
local translation = EngineClasses.float3(0, 0, 0)
rawset(tp, 'construction', replacement)
if newAdditions then rawset(tp, 'additions', newAdditions) end
beam.parentEntityName = target
beam.localTranslation = translation
if type(Log) == 'function' then
Log('[SCOM Optional Packs opt2] '..id..': construction beam '..old..' -> '..target..' (missing attachment)')
end
end
-- Source sonar, Cybran shield and Hive upgrade links; native Structure owns the work.
local SourceUpgradeLinks = {
    ues5020 = {source="UEB3102", target="ues5021",
        hash="17bcd5ab1edd7a57b1dc7923cfd8b0740a335e9f52008ab62fb1e78df7308a66"},
    ues5021 = {source="UEB3202", target="uen3005",
        hash="96d9618c3d88fe6582e3bfb814dd0a582bf19533a9861cac74b93ce37bfa2020"},
    ugs5008 = {source="URB3102", target="ugs5010",
        hash="3467e9fecf5a278ba1987ec390f5cd270ce2d43fe2ec37babd91dca81ccd2827"},
    ugs5010 = {source="URB3202", target="ugn3005",
        hash="e87775a04b66d376282913696ff67b8310b53fe17ff4233413b7ed51fe7f0c1a"},
    ugs2401 = {source="URB4202", target="ugs5012", old="ugs3401",
        hash="4053e6d1379b4bfa280932e1790346a4a722e8368dcf3be77325b5fa08bd12c4"},
    ugs5012 = {source="URB4204", target="ugs5013",
        hash="ffb34c53c36bf2ae438d1c041ba1ba9e1c089a327b93d173e9312def4006dfb9"},
    ugs5013 = {source="URB4205", target="ugs5014",
        hash="1fca98ab7de7a06c63cd92ddec0ebe89f3fc2f61f21ded458cb9a2f5449cc172"},
    ugs5014 = {source="URB4206", target="ugs3401",
        hash="ca7f4fa4691fc0a2ecab35f97b13f92d2d0811008f12e8595c4efdf4f51d8ece"},
    ugs2501 = {source="XRB0104", target="ugs5026", old="ugs3501",
        hash="33df9d71506323628c40288aaf5df5ce6bea3f90ee7b176232ca1ed253580a05"},
    ugs5026 = {source="XRB0204", target="ugs3501",
        hash="2d4bd826f7b7ffb0e843680acfe630b2955251333e5eb50faec16269b6139e6b"},
}
function SCO_ApplySourceUpgradeLinks(tp)
    local id = tp.general and tp.general.tpId
    local hiveCount = ({ugs2501=1, ugs5026=2, ugs3501=3})[id]
    if hiveCount then
        -- The generated middle-stage template only bound its embedded beam.
        if id == "ugs5026" and tp.additions.buildBeamBones == nil then
            tp.additions.buildBeamBones = {"Attachpoint01", "Attachpoint02"}
        end
        local bones = tp.additions and tp.additions.buildBeamBones
        assert(type(bones) == "table" and #bones == hiveCount,
            "Hive source build muzzles drifted for " .. id)
        for index, bone in ipairs(bones) do
            assert(bone == string.format("Attachpoint%02d", index),
                "Hive source build muzzle order drifted for " .. id)
        end
        tp.additions.multiConstructionBeam = {
            prefabName = "SCOM_CybranHiveMuzzleBeam",
            materialPath = "VFX/SCOM/CybranBuildDrones/build_beam.sanmaterial",
            shrink = tp.construction.beam.shrink,
        }
    end
    local rule = SourceUpgradeLinks[id]
    if not rule then return tp end
    local source = tp.additions and tp.additions.faSourceContract
    local construction = tp.construction
    assert(source and (source.sourceId == rule.source or source.mapping == rule.source .. " -> " .. id)
        and source.sourceBlueprintSha256 == rule.hash,
        "Source upgrade blueprint identity drifted for " .. id)
    assert(type(construction) == "table" and type(construction.buildPower) == "number"
        and construction.buildPower > 0,
        "Source upgrade construction missing for " .. id)
    assert(construction.upgradesTo == rule.old or construction.upgradesTo == rule.target,
        "Source upgrade predecessor drifted for " .. id)
    if id == "ugs5026" then
        assert(tp.general.class[2] == "GuardEngineeringStation" and type(tp.tags) == "table",
            "Source middle Hive station class drifted")
    end
    -- FA BuildableCategory lists the next stage only. Keep native queue validation
    -- and self-upgrade execution aligned, including stages within the same tech tier.
    construction.canBuild = "Tags." .. rule.target
    construction.upgradesTo = rule.target
    if id == "ugs5026" then
        local tagged = false
        for _, tag in ipairs(tp.tags) do
            if tag == "ENGINEERING_STATION" then tagged = true end
        end
        if not tagged then
            table.insert(tp.tags, "ENGINEERING_STATION")
            -- Native template import indexes tags before creating the prefab.
            if Tags then Tags(tp) end
        end
    end
    return tp
end
-- Keep the Cybran ACU laser loop; give Tracer each-shot cannon audio.
function SCO_ApplySourceWeaponAudio(tp)
    if tp.general.tpId == "ugs1201" then
        local weapon = assert(tp.weapons and tp.weapons[1], "Tracer AA audio weapon missing")
        local identity = weapon.scoFaProjectileIdentity
        local audio = weapon.audio and weapon.audio.onFire
        assert(identity and identity.sourceIndex == 1 and identity.sourceLabel == "AAGun"
            and string.lower(identity.sourceBlueprintSha256)
                == "0460b42285f54f1b3cd041b431805ab8a0d54c1d6246c0ba26d6980156f19152"
            and weapon.projectileTemplate == "psf0004" and not weapon.beam
            and #weapon.muzzleGroups == 2
            and #weapon.muzzleGroups[1].muzzles == 1
            and weapon.muzzleGroups[1].muzzles[1] == "Turret_Muzzle_01"
            and #weapon.muzzleGroups[2].muzzles == 1
            and weapon.muzzleGroups[2].muzzles[1] == "Turret_Muzzle_02"
            and audio and ((audio.name == "aglm5114" and audio.looping == true)
                or (audio.name == "agom1110" and audio.looping == false)),
            "Tracer AA audio contract drift")
        -- Existing Guard small-cannon event. The native one-shot prefab fires
        -- with each muzzle command, so sound follows the real salvo cadence.
        weapon.audio.onFire = { name = "agom1110", looping = false }
        return
    end
    if tp.general.tpId ~= 'ugl0000' then return end
    local weapon = assert(tp.weapons[3], 'Cybran ACU laser audio slot missing')
    local audio = weapon.audio and weapon.audio.onFire
    assert(weapon.beam and audio and audio.name == 'aglm5130',
        'Cybran ACU laser audio contract changed')
    assert(weapon.muzzleGroups[1].muzzles[1] == 'Turret_Muzzle_03',
        'Cybran ACU laser audio muzzle changed')
    -- There is no one-shot aglm5130 event. Native persistent muzzle audio
    -- resolves aglm5130_start/stop and stops it when firing ends or is destroyed.
    audio.looping = true
end
-- Novax source shell partitions retain the original rig and bind indices.
local function SourceSplitMesh(tp)
    local special = tp.additions and tp.additions.scoSpecial
    local split = special and special.splitMesh
    if not split then return nil end
    assert(tp.general.tpId == 'uea5009', 'Source split mesh scope changed')
    local prefix = 'Units/uea5009/LOD0/'
    local function asset(path, suffix)
        assert(type(path) == 'string' and string.sub(path, 1, #prefix) == prefix
            and not string.find(path, '..', 1, true)
            and string.sub(path, -#suffix) == suffix, 'Invalid source shell asset path')
    end
    asset(split.bodyModel, '.sanmodel')
    asset(split.skeleton, '.sanskeleton')
    assert(#split.shells == 4, 'Novax source shell count changed')
    for index, shell in ipairs(split.shells) do
        assert(shell.entityName == 'SCO_Shell0' .. index, 'Novax shell identity changed')
        asset(shell.model, '.sanmodel')
        asset(shell.material, '.sanmaterial')
    end
    return split
end

function SCO_SourceBodyModel(tp, original)
    local split = SourceSplitMesh(tp)
    return split and split.bodyModel or original
end

function SCO_SourceShellMeshes(tp, hierarchy, skins, skinBones, lods, culling, skeletonBones, renderDistance)
    local special = tp.additions and tp.additions.scoSpecial
    local target = special and special.groundTargetEntity
    if target then
        assert(tp.general.tpId == 'usl5002' and target == 'SCO_OthuyGroundTarget',
            'Source ground target identity changed')
        for _, existing in ipairs(hierarchy) do
            assert(existing.entityName ~= target, 'Source ground target already exists')
        end
        table.insert(hierarchy, EngineClasses.EntityTemplate(target, TemplateHeadEntityName,
            EngineClasses.float3(0, 0, 0), 1.0, GetIdentityQuaternion(), true))
    end
    local split = SourceSplitMesh(tp)
    if not split then return end
    local existingNames = {}
    for _, existing in ipairs(hierarchy) do existingNames[existing.entityName] = true end
    for _, shell in ipairs(split.shells) do
        local entity = shell.entityName
        assert(not existingNames[entity], 'Novax shell entity already exists')
        table.insert(hierarchy, EngineClasses.EntityTemplate(entity, TemplateHeadEntityName,
            EngineClasses.float3(0, 0, 0), 1.0, GetIdentityQuaternion(), false))
        existingNames[entity] = true
        table.insert(skins, EngineClasses.SkinnedMeshTemplate(entity, split.skeleton, shell.model,
            shell.material, ShadowCastingMode.On, EngineClasses.float4(1, 1, 1, 1),
            EngineClasses.float4(-1, 0, 0, 0), true))
        for index, bone in ipairs(skeletonBones) do
            -- Native skin-bone components have one renderer owner. Identity
            -- children follow the animated bones without replacing body's owner.
            local alias = entity .. '_Bone' .. (index - 1)
            assert(existingNames[bone.boneName], 'Novax source skin bone absent')
            assert(not existingNames[alias], 'Novax shell bone alias already exists')
            table.insert(hierarchy, EngineClasses.EntityTemplate(alias, bone.boneName,
                EngineClasses.float3(0, 0, 0), 1.0, GetIdentityQuaternion(), false))
            existingNames[alias] = true
            table.insert(skinBones, EngineClasses.SkinnedMeshBoneTemplate(alias, entity, index - 1))
        end
        table.insert(lods, EngineClasses.LODTemplate(entity, {
            EngineClasses.LODLevelTemplate(shell.model, shell.material, renderDistance,
                ShadowCastingMode.On, 0, 0, 0, 0, 0, false, false)
        }, split.skeleton))
        table.insert(culling, EngineClasses.CullingTemplate(entity, 10))
    end
end
-- Two source modes share the physical barrel, but native aim and muzzle
-- components require distinct entity owners. Identity children preserve pose.
function SCO_SourceSniperPrefab(tp,prefab)
    local config=tp.additions and tp.additions.scoSourceUnitModes
    if not config or not config.sniperWeapon then return end
    -- Native Sanctuary source templates may retain their native tpId while
    -- carrying the imported FA target contract. Keep both identities pinned.
    assert((tp.general.tpId=='usl3801' or config.targetId=='usl3801') and
        config.targetId=='usl3801' and config.sourceId=='XSL0305',
        'Sniper prefab scope drift')
    local hierarchy=prefab.hierarchyTemplate.entities
    local names={}
    for _,entity in ipairs(hierarchy) do names[entity.entityName]=true end
    assert(names.Muzzle and names.Barrel,'Sniper physical bones absent')
    for _,name in ipairs({'SCO_SniperNormalMuzzle','SCO_SniperPrecisionMuzzle'}) do
        assert(not names[name],'Sniper alias already exists')
        table.insert(hierarchy,EngineClasses.EntityTemplate(name,'Muzzle',
            EngineClasses.float3(0,0,0),1,GetIdentityQuaternion(),true))
    end
end
