local function SCO_ApplyMeasuredSelectionBracket(tp, prefab)
    local spec = SCO_MeasuredSelectionBounds[tp.general.tpId]
    if not spec then return end

    local entityCount = 0
    for _, entity in ipairs(prefab.hierarchyTemplate.entities) do
        if entity.entityName == 'Selection Bracket' then
            assert(entity.parentEntityName == TemplateHeadEntityName,
                'SCOM selection bracket parent drift: '..tp.general.tpId)
            entity.localTranslation = EngineClasses.float3(spec[3], 0, spec[4])
            entityCount = entityCount + 1
        end
    end
    local meshCount = 0
    for _, mesh in ipairs(prefab.localTemplate.meshTemplates) do
        if mesh.entityName == 'Selection Bracket' then
            assert(mesh.meshPath == 'VFX/Models/Static/Quad Up.sanmodel'
                and mesh.materialPath == 'VFX/Objective Markers/Visual Marker_Unit Default_Flat_Brackets 08.sanmaterial'
                and mesh.disabled == true,
                'SCOM selection bracket mesh drift: '..tp.general.tpId)
            mesh.scale = EngineClasses.float3(spec[1], 1, spec[2])
            meshCount = meshCount + 1
        end
    end
    local colliderCount = 0
    for _, collider in ipairs(prefab.localTemplate.volumeColliderTemplates) do
        if collider.entityName == 'Selection Collider' then
            assert(collider.collisionWorldID == CollisionWorld.Selection
                and collider.type == ColliderType.Box,
                'SCOM selection click collider contract drift: '..tp.general.tpId)
            collider.size = EngineClasses.float3(spec[5], spec[6], spec[7])
            collider.offset = EngineClasses.float3(spec[3], spec[8], spec[4])
            colliderCount = colliderCount + 1
        end
    end
    assert(entityCount == 1 and meshCount == 1 and colliderCount == 1,
        'SCOM selection geometry count drift: '..tp.general.tpId)
end

local function SCO_SimulateNovaxAttachHierarchy(tp, prefab)
  if tp.general.tpId ~= 'ues5043' then return end

  local additions = tp.additions
  local special = additions and additions.scoSpecial
  local source = additions and additions.faSourceContract
  assert(special and special.kind == 'novaxLauncher'
      and special.sourceId == 'XEB2402'
      and special.child == 'uea5009'
      and special.attachBone == 'Attachpoint01'
      and source and source.sourceId == 'XEB2402'
      and source.targetId == 'ues5043', 'Novax attachment source drift')

  local entities = {}
  for _, entity in ipairs(prefab.hierarchyTemplate.entities) do
      if entity.entityName == 'Root' or entity.entityName == 'B03'
          or entity.entityName == 'Attachpoint01' then
          assert(entities[entity.entityName] == nil,
              'Duplicate Novax hierarchy entity: '..entity.entityName)
          entities[entity.entityName] = entity
      end
  end
  local root = entities.Root
  local parent = entities.B03
  local attachment = entities.Attachpoint01
  assert(root and root.parentEntityName == TemplateHeadEntityName
      and parent and parent.parentEntityName == 'Root'
      and attachment and attachment.parentEntityName == 'B03',
      'Novax attachment hierarchy drift')

  root.forceSimulated = true
  parent.forceSimulated = true
  attachment.forceSimulated = true
end

-- Use the same grid skirt as placement collision for every SCOM structure.
-- The existing Construction Bracket stays disabled until client build mode enables it.
local function SCO_ApplyStructureBuildGuide(tp, prefab)
    local tags = tp.tags or {}
    local structure = false
    for _, tag in ipairs(tags) do
        if tag == 'STRUCTURE' or tag == 'SCFA_FERRYBEACON' then
            structure = true
        end
    end
    if not structure then return end

    local skirt = tp.skirtSize
    if not skirt or not skirt.x or not skirt.y
        or skirt.x <= 0 or skirt.y <= 0
        or skirt.x ~= math.floor(skirt.x) or skirt.y ~= math.floor(skirt.y) then
        return
    end

    local entities, meshes = 0, 0
    for _, entity in ipairs(prefab.hierarchyTemplate.entities) do
        if entity.entityName == 'Construction Bracket' then
            assert(entity.parentEntityName == TemplateHeadEntityName,
                'SCOM build guide parent drift: '..tp.general.tpId)
            entities = entities + 1
        end
    end
    for _, mesh in ipairs(prefab.localTemplate.meshTemplates) do
        if mesh.entityName == 'Construction Bracket' then
            assert(mesh.meshPath == 'VFX/Models/Static/Quad Up.sanmodel'
                and mesh.materialPath == 'VFX/Objective Markers/Visual Marker_Building Footprint_01.sanmaterial'
                and mesh.disabled == true,
                'SCOM build guide stock mesh drift: '..tp.general.tpId)
            mesh.materialPath = 'VFX/SCOM/BuildGuide/BorderGreen.sanmaterial'
            mesh.scale = EngineClasses.float3(skirt.x, 1, skirt.y)
            meshes = meshes + 1
        end
    end
    assert(entities == 1 and meshes == 1,
        'SCOM build guide bracket count drift: '..tp.general.tpId)
end

function SCO_SourceSecondaryVisuals(tp,prefab)
  SCO_ApplyMeasuredSelectionBracket(tp, prefab)
  SCO_ApplyStructureBuildGuide(tp, prefab)
  SCO_SimulateNovaxAttachHierarchy(tp, prefab)
  SCO_OptionalConstructionBeam(tp,prefab)
  local c=tp.additions and tp.additions.scoSourceSecondaryVisuals
  if not c then return end
  local optionalId=tp.general.tpId
  if type(c.targetId)=='string'
      and c.targetId:match('^u[ecgs]%a%d+$')
      and type(optionalId)=='string'
      and (optionalId:match('^w%a%a%d+$') or optionalId:match('^sc2r_')) then
      return
  end
  local source=tp.additions.faSourceContract
  assert(tp.general.tpId==c.targetId or (source and source.targetId==c.targetId),'Secondary visual target drift')
  assert(source and source.sourceId==c.sourceId and string.lower(source.sourceBlueprintSha256)==c.sourceBlueprintSha256,
      'Secondary visual source identity drift')
  local hierarchy=prefab.hierarchyTemplate.entities
  local localTemplate=prefab.localTemplate
  localTemplate.meshTemplates=localTemplate.meshTemplates or {}
  localTemplate.cullingTemplates=localTemplate.cullingTemplates or {}
  local names={}
  for _,entity in ipairs(hierarchy) do names[entity.entityName]=entity end
  for _,mesh in ipairs(c.meshes or {}) do
      assert(names[mesh.bone],'Secondary visual attachment bone absent: '..mesh.bone)
      assert(mesh.model:match('^VFX/SCOM/Secondary/[%w_]+%.sanmodel$') and
          mesh.material:match('^VFX/SCOM/Secondary/[%w_]+%.sanmaterial$'),'Invalid secondary source asset path')
      if not names[mesh.entityName] then
          table.insert(hierarchy,EngineClasses.EntityTemplate(mesh.entityName,mesh.bone,
              EngineClasses.float3(unpack(mesh.offset)),1,GetIdentityQuaternion(),false))
          table.insert(localTemplate.meshTemplates,EngineClasses.MeshTemplate(mesh.entityName,mesh.model,mesh.material,
              EngineClasses.float3(mesh.scale,mesh.scale,mesh.scale),ShadowCastingMode.Off,
              EngineClasses.float4(1,1,1,1),EngineClasses.float4(),true))
          local radius=0
          for axis=1,3 do radius=radius+math.max(math.abs(mesh.geometry.boundsMin[axis]),math.abs(mesh.geometry.boundsMax[axis]))^2 end
          table.insert(localTemplate.cullingTemplates,EngineClasses.CullingTemplate(mesh.entityName,math.sqrt(radius)*mesh.scale))
          names[mesh.entityName]=true
      end
  end
  if c.rotators then
      local global=prefab.globalTemplate
      global.rotatorTemplates=global.rotatorTemplates or {}
      local existing={}
      for _,rotator in ipairs(global.rotatorTemplates) do existing[rotator.entityName]=true end
      for _,rotator in ipairs(c.rotators) do
          assert(names[rotator.bone],'Source rotator bone absent: '..rotator.bone)
          if c.forceSimulatedRotators then names[rotator.bone].forceSimulated=true end
          if not existing[rotator.bone] then
              table.insert(global.rotatorTemplates,EngineClasses.RotatorTemplate(rotator.bone,EngineClasses.float3(),false,false))
              existing[rotator.bone]=true
          end
      end
  end
  for _,beam in ipairs(c.beams or {}) do
      assert(names[beam.bone] and names[beam.endBone],'Secondary beam source endpoint absent')
      if not names[beam.entityName] then
          table.insert(hierarchy,EngineClasses.EntityTemplate(beam.entityName,beam.bone,
              EngineClasses.float3(),1,GetIdentityQuaternion(),false))
          table.insert(localTemplate.meshTemplates,EngineClasses.MeshTemplate(beam.entityName,beam.model,beam.material,
              EngineClasses.float3(1,1,1),ShadowCastingMode.Off,EngineClasses.float4(),EngineClasses.float4(),true))
          table.insert(localTemplate.cullingTemplates,EngineClasses.CullingTemplate(beam.entityName,20))
          names[beam.entityName]=true
      end
  end
end
-- Called after other source prefab helpers. Never replace their components.
function SCO_SourceDynamicVisuals(tp,prefab)
    local c=tp.additions and tp.additions.scoSourceDynamicVisuals
    if not c then return end
    local source=tp.additions.faSourceContract
    assert(tp.general.tpId==c.targetId and source and source.sourceId==c.sourceId
        and string.lower(source.sourceBlueprintSha256)==c.sourceBlueprintSha256,'Dynamic prefab source drift')
    local entities={}
    for _,entity in ipairs(prefab.hierarchyTemplate.entities) do entities[entity.entityName]=entity end
    for _,bone in ipairs(c.wings and c.wings.bones or {}) do
        assert(entities[bone],'Source wing bone absent: '..bone)
        entities[bone].forceSimulated=true
    end
    for _,bone in ipairs(c.thrust and c.thrust.bones or {}) do
        assert(entities[bone],'Source thrust bone absent: '..bone)
        entities[bone].forceSimulated=true
    end
    for _,barrel in ipairs(c.barrels or {}) do
        assert(entities[barrel.bone],'Source visual barrel bone absent: '..barrel.bone)
        -- Aim owns the simulated bone. The client composes visual spin afterward.
        entities[barrel.bone].forceSimulated=true
    end
    local barrel=c.barrel
    if barrel and not barrel.dormantReason then
        assert(entities[barrel.bone],'Source barrel bone absent: '..barrel.bone)
        entities[barrel.bone].forceSimulated=true
        local global=prefab.globalTemplate
        global.rotatorTemplates=global.rotatorTemplates or {}
        for _,rotator in ipairs(global.rotatorTemplates) do
            if rotator.entityName==barrel.bone then
                assert(prefab.scoDynamicRotator==barrel.bone,'Dynamic rotator ownership collision')
                return
            end
        end
        table.insert(global.rotatorTemplates,EngineClasses.RotatorTemplate(barrel.bone,EngineClasses.float3(),false,false))
        prefab.scoDynamicRotator=barrel.bone
    end
end
-- Native two-axis joints for imported gunship ground weapons.
-- LuaInterface.CreateGlobalPrefabTemplates discards pitch when both axes name
-- one entity. Keep the authored joint as pitch and insert its independent yaw
-- parent at the same pivot; the offset leaves every authored local pose intact.
-- XSL0103 aims the complete Turret; Turret_Barrel is its recoil child.
-- Native yaw/pitch require different entities. The cancelling translations
-- split those axes at the authored pivot without changing skin or clip data.
local function SCO_ZthueeAimHierarchy(tp, entityNameToHierarchyIndex, hierarchyEntities)
    local weapon
    for _, candidate in ipairs(tp.weapons or {}) do
        local source = candidate.scoFaProjectileIdentity
        if source and source.sourceIndex == 1 and source.sourceLabel == "MainGun" then
            assert(not weapon and candidate.projectileTemplate == "psf0144"
                and string.lower(source.sourceBlueprintSha256) ==
                    "e709f74fa0682d04ae61e1cebc2aa9d6a480f9efa0453c6531f328f0be18cbec",
                "SCOM Zthuee source weapon changed")
            weapon = candidate
        end
    end
    assert(weapon and weapon.aimControllers and #weapon.aimControllers == 1,
        "SCOM Zthuee controller count changed")
    local aim = weapon.aimControllers[1]
    local yawName, offsetName = "SCOZthueeYaw", "SCOZthueeYawOffset"
    local original = aim.yawBone == "Turret" and aim.pitchBone == "Turret_Barrel"
    local repaired = aim.yawBone == yawName and aim.pitchBone == "Turret"
    assert(aim.aimBone == "Turret_Muzzle" and (original or repaired),
        "SCOM Zthuee aim ownership changed")
    local turretIndex = assert(entityNameToHierarchyIndex.Turret)
    local turret = hierarchyEntities[turretIndex]
    local barrel = hierarchyEntities[assert(entityNameToHierarchyIndex.Turret_Barrel)]
    local muzzle = hierarchyEntities[assert(entityNameToHierarchyIndex.Turret_Muzzle)]
    assert(entityNameToHierarchyIndex.Root and barrel.parentEntityName == "Turret"
        and muzzle.parentEntityName == "Turret_Barrel",
        "SCOM Zthuee recoil hierarchy changed")
    local p = turret.localTranslation
    if not entityNameToHierarchyIndex[yawName] then
        assert(original and turret.parentEntityName == "Root"
            and not entityNameToHierarchyIndex[offsetName],
            "SCOM Zthuee pivot hierarchy changed")
        local yaw = EngineClasses.EntityTemplate(yawName, "Root",
            EngineClasses.float3(p.x, p.y, p.z), 1, GetIdentityQuaternion(), true)
        local offset = EngineClasses.EntityTemplate(offsetName, yawName,
            EngineClasses.float3(-p.x, -p.y, -p.z), 1, GetIdentityQuaternion(), true)
        turret.parentEntityName = offsetName
        table.insert(hierarchyEntities, turretIndex, yaw)
        table.insert(hierarchyEntities, turretIndex + 1, offset)
        for index, entity in ipairs(hierarchyEntities) do
            entityNameToHierarchyIndex[entity.entityName] = index
        end
    else
        local yaw = hierarchyEntities[entityNameToHierarchyIndex[yawName]]
        local offset = hierarchyEntities[assert(entityNameToHierarchyIndex[offsetName])]
        assert(repaired and turret.parentEntityName == offsetName
            and yaw.parentEntityName == "Root" and offset.parentEntityName == yawName
            and yaw.localTranslation.x == p.x and yaw.localTranslation.y == p.y
            and yaw.localTranslation.z == p.z
            and offset.localTranslation.x == -p.x and offset.localTranslation.y == -p.y
            and offset.localTranslation.z == -p.z,
            "SCOM Zthuee existing pivot changed")
    end
    aim.yawBone = yawName
    aim.pitchBone = "Turret"
    turret.forceSimulated = true
    muzzle.forceSimulated = true
end

local SCO_GunshipAimSpecs = {
    uea5005 = { sourceId = "UEA0203", weapon = "Turret01", projectile = "psf0034", zeroGravity = true, joints = {
        { aim = "Muzzle", pitch = "Muzzle", parent = "Root" },
    } },
    uea5008 = { sourceId = "UEA0305", weapon = "Plasma01", projectile = "psf0032", zeroGravity = true, joints = {
        { aim = "Turret_Down_Muzzle_01", pitch = "Turret_Down_01", parent = "Root" },
        { aim = "Turret_Down_Muzzle_02", pitch = "Turret_Down_Barrel_02", parent = "Turret_Down_02" },
    } },
    uga5008 = { sourceId = "XRA0105", weapon = "MainGun", projectile = "psf0017",
        composedSolver = "NoArc", sourceArc = "RULEUBA_None", runtimeSolver = "LowArc", joints = {
        { aim = "Laser_Muzzle", pitch = "Laser_Muzzle", parent = "Root" },
    } },
}

function SCO_UefGunshipAimHierarchy(tp, entityNameToHierarchyIndex, hierarchyEntities)
    if tp.general.tpId == "usl1101" then
        SCO_ZthueeAimHierarchy(tp, entityNameToHierarchyIndex, hierarchyEntities)
        return
    end
    local spec = SCO_GunshipAimSpecs[tp.general.tpId]
    if not spec then return end
    local sourceContract = tp.additions and tp.additions.faSourceContract
    assert(sourceContract and sourceContract.sourceId == spec.sourceId,
        "SCOM gunship source identity changed")
    local weapon
    for _, candidate in ipairs(tp.weapons or {}) do
        if candidate.name == spec.weapon then
            assert(not weapon, "SCOM gunship weapon duplicated")
            weapon = candidate
        end
    end
    assert(weapon and weapon.projectileTemplate == spec.projectile
        and #weapon.aimControllers == #spec.joints,
        "SCOM gunship controller count changed")
    local source = assert(weapon.scoFaSourceWeapon)
    assert(source.Label == spec.weapon and source.TurretPitch < 0,
        "SCOM gunship source pitch contract changed")
    for index, joint in ipairs(spec.joints) do
        local aim = weapon.aimControllers[index]
        local yawName = "SCOGunshipYaw_" .. joint.pitch
        local offsetName = yawName .. "Offset"
        assert(aim.aimBone == joint.aim and aim.pitchBone == joint.pitch
            and (aim.yawBone == joint.pitch or aim.yawBone == yawName),
            "SCOM gunship source joint changed")
        local childIndex = assert(entityNameToHierarchyIndex[joint.pitch])
        local child = hierarchyEntities[childIndex]
        if not entityNameToHierarchyIndex[yawName] then
            assert(child.parentEntityName == joint.parent
                and not entityNameToHierarchyIndex[offsetName],
                "SCOM gunship pivot hierarchy changed")
            local p = child.localTranslation
            local yaw = EngineClasses.EntityTemplate(yawName, joint.parent,
                EngineClasses.float3(p.x, p.y, p.z), 1, GetIdentityQuaternion(), true)
            local offset = EngineClasses.EntityTemplate(offsetName, yawName,
                EngineClasses.float3(-p.x, -p.y, -p.z), 1, GetIdentityQuaternion(), true)
            child.parentEntityName = offsetName
            table.insert(hierarchyEntities, childIndex, yaw)
            table.insert(hierarchyEntities, childIndex + 1, offset)
            for entityIndex, entity in ipairs(hierarchyEntities) do
                entityNameToHierarchyIndex[entity.entityName] = entityIndex
            end
        else
            assert(child.parentEntityName == offsetName
                and hierarchyEntities[entityNameToHierarchyIndex[offsetName]].parentEntityName == yawName,
                "SCOM gunship existing wrapper changed")
        end
        aim.yawBone = yawName
        -- These installed mobile rigs rest along +Z. Native pitch negation
        -- therefore maps the source physical elevation interval directly.
        aim.pitchMin = source.TurretPitch - source.TurretPitchRange
        aim.pitchMax = source.TurretPitch + source.TurretPitchRange
        if spec.runtimeSolver then
            assert((aim.solverType == spec.composedSolver or aim.solverType == spec.runtimeSolver)
                and source.BallisticArc == spec.sourceArc,
                "SCOM gunship source solver changed")
            aim.solverType = spec.runtimeSolver
        end
        -- The UEF source projectiles explicitly disable gravity in Created().
        -- Broadsword's LowArc solver must use that same acceleration. Jester's
        -- CDFLaserHeavy01 retains its authored gravity.
        if spec.zeroGravity then
            aim.aimGravity = EngineClasses.float3(0, 0, 0)
        else
            assert(aim.aimGravity.x == 0 and aim.aimGravity.y == -4.9
                and aim.aimGravity.z == 0, "SCOM gunship source gravity changed")
        end
        hierarchyEntities[entityNameToHierarchyIndex[joint.aim]].forceSimulated = true
    end
end
-- Existing rig parts only; no mesh, texture, pivot or native component replacement.
function SCO_FactoryClearancePrefab(tp,prefab)
    local posture=tp.additions and tp.additions.scoFactoryPosture
    local config=tp.additions and (tp.additions.scoFactoryEgress or posture)
    local rig=config and config.clearanceRig
    if not rig then return end
    local source=tp.additions.faSourceContract
    -- Earlier reviewed ports identify their source by blueprint path. Newer
    -- contracts also expose sourceId; when present it must agree with that path.
    local expectedBlueprint='units/'..config.sourceId..'/'..config.sourceId..'_unit.bp'
    local nativeSourceAlias=source and source.mapping==config.sourceId..' -> '..config.targetId
    assert((config.targetId==tp.general.tpId or nativeSourceAlias) and source and source.sourceBlueprint==expectedBlueprint
        and (source.sourceId==nil or source.sourceId==config.sourceId),
        'Factory clearance source identity drift')
    assert(rig.adaptation==true and rig.duration>0 and rig.duration<math.huge,'Invalid factory clearance rig')
    if posture then assert(type(posture.allowedFactoryId)=='string','Factory posture scope missing') end
    local entities,seen={},{}
    for _,entity in ipairs(prefab.hierarchyTemplate.entities) do entities[entity.entityName]=entity end
    for _,bone in ipairs(rig.bones) do
        assert(entities[bone.boneName] and not seen[bone.boneName],'Factory clearance bone missing or duplicated')
        if bone.translationOnly then
            assert(posture and bone.composition=='bind-translation' and bone.translation
                and not bone.bindRotation and not bone.axis and not bone.degrees,'Invalid translation-only posture')
        else
            assert(not posture,'Factory posture must preserve native joint rotations')
            assert(bone.composition=='bind*local-axis' and bone.bindRotation,'Factory clearance basis missing')
            local axis=bone.axis
            if type(axis)=='string' then assert(axis=='x' or axis=='y' or axis=='z','Invalid clearance axis')
            else assert(type(axis)=='table' and math.abs(axis.x^2+axis.y^2+axis.z^2-1)<.00001,'Clearance axis is not normalized') end
            assert(type(bone.degrees)=='number' and bone.degrees==bone.degrees and math.abs(bone.degrees)<=180,'Invalid clearance angle')
        end
        if bone.translation then
            assert(bone.bindPosition,'Factory slider bind position missing')
            for _,key in ipairs({'x','y','z'}) do
                local value=bone.translation[key]
                assert(type(value)=='number' and value==value and math.abs(value)<math.huge,'Invalid clearance translation')
            end
        end
        seen[bone.boneName]=true
        entities[bone.boneName].forceSimulated=true
    end
end
-- XSB2401's rigid Nuke mesh and psf0136 share this source-authored origin.
do
    local previous = SCO_SourceFinalizers['uss4102']
    SCO_SourceFinalizers['uss4102'] = function(tp)
        if previous then previous(tp) end
        assert(tp.general.tpId == 'uss4102', 'Yolona missile scope drift')
        local silo = tp.additions and tp.additions.scoTactical
        assert(silo and silo.sourceId == 'XSB2401' and silo.projectile == 'psf0136'
            and silo.maxAmmo == 1, 'Yolona missile stockpile drift')
        tp.additions.scoYolonaMissile = {
            version = '1.0.0', bone = 'Nuke', root = 'Root', lift = 6.555,
            -- Installed .057-scale rig; slider local +Z becomes parent +Y.
            position = {x = .03510554122913923, y = -4.9710147399902365, z = .0000005866009745152829},
            rotation = {x = -.7071068654802295, y = .00000016858740158000525,
                z = .00000016858738650711404, w = .7071066968928154},
            -- Existing psf0136 extraction proved all 1908 corners against Nuke.
            projectileOrigin = {x = -.0000000006436675434625372,
                y = -.0000003855591734492862, z = 2.3970380452224235},
        }
    end
end
-- SCOM Kennel host pod attachments 1.0.0
function SCO_SourcePodAttachments(tp, prefab)
    local id = tp.general.tpId
    local expected = id == 'ues2501' and {'AttachSpecial01'}
        or id == 'ues3501' and {'AttachSpecial01', 'AttachSpecial02'}
    if not expected then return end
    local config = tp.additions and tp.additions.scoSourcePods
    assert(config and config.kind == 'tower' and config.targetId == id
        and #config.slots == #expected, 'Kennel pod configuration drift: '..id)
    local entities = {}
    for _, entity in ipairs(prefab.hierarchyTemplate.entities) do
        entities[entity.entityName] = entity
    end
    for index, bone in ipairs(expected) do
        local entity = entities[bone]
        assert(config.slots[index].bone == bone and entity
            and entity.parentEntityName == 'B01', 'Kennel pod bone drift: '..id..'/'..bone)
        entity.forceSimulated = true
    end
end


-- SCOM startup prefab diagnostics 2.1.88.4
do
    local original = CreateUnitPrefab
    if type(original) ~= "function" then
        error("SCOM startup: completed prefab loader is unavailable", 0)
    end
    CreateUnitPrefab = function(tp)
        local id = type(tp) == "table" and type(tp.general) == "table"
            and tp.general.tpId or "<missing template identity>"
        local ok, errorCode, prefabId = pcall(original, tp)
        if not ok then
            error("SCOM startup prefab " .. tostring(id) .. ": " .. tostring(errorCode), 0)
        end
        return errorCode, prefabId
    end
end

-- Call beside SCO_UefGunshipAimHierarchy, before native aim component marshaling.
-- Preserve each authored muzzle pivot while assigning yaw and pitch to different
-- entities. The native marshaler otherwise drops a coincident pitch component.
function SCO_AhwassaAimHierarchy(tp, entityNameToHierarchyIndex, hierarchyEntities)
    if tp.general.tpId ~= "usa4011" then return end
    local source = tp.additions and tp.additions.faSurfaceBomberSourceContract
    assert(source and source.sourceUnitId == "XSA0402"
        and source.sourceBlueprintSha256 == "19ad26d88df8e9b1e7ae5fbfd680e266d935659a843dea3c6931325b81e799c5"
        and tp.additions.scoAircraftVisualRoll == 180,
        "SCOM Ahwassa visual/weapon source changed")
    local seen = {}
    for _, weapon in ipairs(tp.weapons or {}) do
        local contract = weapon.scoFaHeadingArc
        if contract then
            local boneName = ({
                RightFrontAutocannon = "Right_Front_Autocannon_Muzzle",
                LeftFrontAutocannon = "Left_Front_Autocannon_Muzzle",
                RightRearAutocannon = "Right_Rear_Autocannon_Muzzle",
                LeftRearAutocannon = "Left_Rear_Autocannon_Muzzle",
            })[contract.sourceLabel]
            assert(boneName and not seen[boneName]
                and contract.sourceUnitId == "XSA0402"
                and weapon.projectileTemplate == "psf0101"
                and #weapon.aimControllers == 1,
                "SCOM Ahwassa AA layout changed")
            seen[boneName] = true
            local aim = weapon.aimControllers[1]
            local yawName = "SCOAhwassaYaw_" .. boneName
            local offsetName = yawName .. "Offset"
            assert(aim.aimBone == boneName and aim.pitchBone == boneName
                and (aim.yawBone == boneName or aim.yawBone == yawName)
                and aim.pitchMin == -90 and aim.pitchMax == 90
                and aim.yawMin == -180 and aim.yawMax == 180,
                "SCOM Ahwassa AA axis policy changed")
            local index = assert(entityNameToHierarchyIndex[boneName])
            local bone = hierarchyEntities[index]
            local p = bone.localTranslation
            if not entityNameToHierarchyIndex[yawName] then
                assert(aim.yawBone == boneName and bone.parentEntityName == "Root"
                    and not entityNameToHierarchyIndex[offsetName],
                    "SCOM Ahwassa AA original pivot changed")
                local yaw = EngineClasses.EntityTemplate(yawName, "Root",
                    EngineClasses.float3(p.x, p.y, p.z), 1, GetIdentityQuaternion(), true)
                local offset = EngineClasses.EntityTemplate(offsetName, yawName,
                    EngineClasses.float3(-p.x, -p.y, -p.z), 1, GetIdentityQuaternion(), true)
                bone.parentEntityName = offsetName
                table.insert(hierarchyEntities, index, yaw)
                table.insert(hierarchyEntities, index + 1, offset)
                for entityIndex, entity in ipairs(hierarchyEntities) do
                    entityNameToHierarchyIndex[entity.entityName] = entityIndex
                end
            else
                local yaw = hierarchyEntities[entityNameToHierarchyIndex[yawName]]
                local offset = hierarchyEntities[assert(entityNameToHierarchyIndex[offsetName])]
                assert(aim.yawBone == yawName and bone.parentEntityName == offsetName
                    and yaw.parentEntityName == "Root" and offset.parentEntityName == yawName
                    and yaw.localTranslation.x == p.x and yaw.localTranslation.y == p.y
                    and yaw.localTranslation.z == p.z
                    and offset.localTranslation.x == -p.x and offset.localTranslation.y == -p.y
                    and offset.localTranslation.z == -p.z,
                    "SCOM Ahwassa AA existing pivot changed")
            end
            aim.yawBone = yawName
            bone.forceSimulated = true
        end
    end
    local count = 0
    for _ in pairs(seen) do count = count + 1 end
    assert(count == 4, "SCOM Ahwassa AA weapon count changed")
end
